def strategy(hist, state, pos, ind) -> dict:
    # Parameters
    macd_fast, macd_slow, macd_signal = 8, 17, 9
    atr_period = 14
    pyramid_step = 2.0
    pyramid_adds = 1
    fixed_stop_k = 1.0
    time_stop_n = 128
    sizing_f0 = 0.25

    # Calculate MACD
    macd_line, signal_line, _ = ind.macd(hist.close, macd_fast, macd_slow, macd_signal)

    # Calculate ATR
    atr = ind.atr(hist, atr_period)

    # Determine signal
    if len(hist) < macd_slow + macd_signal:
        return {"target": pos, "stop": None, "take": None}

    macd_cross_bullish = macd_line[-1] > signal_line[-1] and macd_line[-2] <= signal_line[-2]
    macd_cross_bearish = macd_line[-1] < signal_line[-1] and macd_line[-2] >= signal_line[-2]

    # Determine entry and exit signals
    if pos == 0:
        if macd_cross_bullish:
            entry_price = hist.close[-1]
            entry_atr = atr[-1]
            target = sizing_f0
            stop = entry_price - fixed_stop_k * entry_atr
            state['entry_price'] = entry_price
            state['entry_atr'] = entry_atr
            state['last_add_price'] = entry_price
            state['adds'] = 0
            state['bars_since_signal'] = 0
            return {"target": target, "stop": stop, "take": None}
        elif macd_cross_bearish:
            entry_price = hist.close[-1]
            entry_atr = atr[-1]
            target = -sizing_f0
            stop = entry_price + fixed_stop_k * entry_atr
            state['entry_price'] = entry_price
            state['entry_atr'] = entry_atr
            state['last_add_price'] = entry_price
            state['adds'] = 0
            state['bars_since_signal'] = 0
            return {"target": target, "stop": stop, "take": None}
    else:
        # Check for opposite MACD cross to exit
        if (pos > 0 and macd_cross_bearish) or (pos < 0 and macd_cross_bullish):
            return {"target": 0, "stop": None, "take": None}

        # Check for time stop
        if 'bars_since_signal' in state:
            state['bars_since_signal'] += 1
            if state['bars_since_signal'] >= time_stop_n:
                return {"target": 0, "stop": None, "take": None}

        # Check for pyramid
        if pos > 0 and state['adds'] < pyramid_adds:
            if hist.close[-1] >= state['last_add_price'] + pyramid_step * state['entry_atr']:
                state['last_add_price'] = hist.close[-1]
                state['adds'] += 1
                return {"target": min(1.0, pos + sizing_f0), "stop": state['entry_price'] - fixed_stop_k * state['entry_atr'], "take": None}
        elif pos < 0 and state['adds'] < pyramid_adds:
            if hist.close[-1] <= state['last_add_price'] - pyramid_step * state['entry_atr']:
                state['last_add_price'] = hist.close[-1]
                state['adds'] += 1
                return {"target": max(-1.0, pos - sizing_f0), "stop": state['entry_price'] + fixed_stop_k * state['entry_atr'], "take": None}

    # Return current position with stop
    stop = state['entry_price'] - fixed_stop_k * state['entry_atr'] if pos > 0 else state['entry_price'] + fixed_stop_k * state['entry_atr']
    return {"target": pos, "stop": stop, "take": None}

