def strategy(hist, state, pos, ind) -> dict:
    # Parameters from the strategy
    signal_id = "ma_cross"
    signal_params = {"kind": "ema", "fast": 5, "slow": 50}
    direction = "long_short"
    filter_id = "htf_trend"
    filter_params = {"minutes": 240, "n": 20}
    sizing_id = "fixed_frac"
    sizing_params = {"f": 1.0}
    risk_ids = ["fixed_stop", "time_stop"]
    risk_params = [{"k": 1.5}, {"n": 16}]

    # Calculate indicators
    if signal_id == "ma_cross":
        if signal_params["kind"] == "sma":
            fast_ma = ind.sma(hist.close, signal_params["fast"])
            slow_ma = ind.sma(hist.close, signal_params["slow"])
        elif signal_params["kind"] == "ema":
            fast_ma = ind.ema(hist.close, signal_params["fast"])
            slow_ma = ind.ema(hist.close, signal_params["slow"])

        # Determine signal
        if fast_ma[-1] > slow_ma[-1] and fast_ma[-2] <= slow_ma[-2]:
            signal = "long"
        elif fast_ma[-1] < slow_ma[-1] and fast_ma[-2] >= slow_ma[-2]:
            signal = "short"
        else:
            signal = None

    # Filter
    if filter_id == "htf_trend":
        htf_hist = hist.htf(filter_params["minutes"])
        htf_ema = ind.ema(htf_hist.close, filter_params["n"])
        if htf_hist.close[-1] > htf_ema[-1]:
            filter_signal = "long"
        elif htf_hist.close[-1] < htf_ema[-1]:
            filter_signal = "short"
        else:
            filter_signal = None

    # Sizing
    if sizing_id == "fixed_frac":
        position_fraction = sizing_params["f"]

    # Risk management
    atr_14 = ind.atr(hist, 14)
    entry_atr = atr_14[-1] if "entry_atr" not in state else state["entry_atr"]
    entry_price = hist.close[-1] if "entry_price" not in state else state["entry_price"]
    bars_since_signal = 0 if "bars_since_signal" not in state else state["bars_since_signal"]

    # Update bars since signal
    if "in_trade" in state and state["in_trade"]:
        bars_since_signal += 1

    # Check for opposite signal to close position
    if pos != 0 and signal is not None and (pos > 0 and signal == "short" or pos < 0 and signal == "long"):
        return {"target": 0, "stop": None, "take": None}

    # Check filter
    if filter_signal is not None and signal is not None and signal != filter_signal:
        signal = None

    # Execute signal
    if signal is not None and pos == 0:
        if signal == "long":
            target = position_fraction
        elif signal == "short":
            target = -position_fraction

        entry_price = hist.close[-1]
        entry_atr = atr_14[-1]
        bars_since_signal = 0

        state["entry_price"] = entry_price
        state["entry_atr"] = entry_atr
        state["bars_since_signal"] = bars_since_signal
        state["in_trade"] = True

        return {"target": target, "stop": None, "take": None}

    # Risk management during trade
    stop = None
    take = None

    if "in_trade" in state and state["in_trade"]:
        if risk_ids[0] == "fixed_stop":
            if pos > 0:
                stop = entry_price - risk_params[0]["k"] * entry_atr
            elif pos < 0:
                stop = entry_price + risk_params[0]["k"] * entry_atr

        if risk_ids[1] == "time_stop":
            if bars_since_signal >= risk_params[1]["n"]:
                return {"target": 0, "stop": None, "take": None}

    # Update state
    state["bars_since_signal"] = bars_since_signal

    # Return current position if no new signal
    return {"target": pos, "stop": stop, "take": take}

