def strategy(hist, state, pos, ind) -> dict:
    # Parameters from the strategy
    macd_fast, macd_slow, macd_signal = 5, 35, 5
    sizing_fraction = 0.25
    time_stop_bars = 32
    cooldown_bars = 4

    # Calculate MACD
    macd_line, signal_line, _ = ind.macd(hist.close, macd_fast, macd_slow, macd_signal)

    # Determine the current signal
    if len(macd_line) < 2:
        return {"target": pos, "stop": None, "take": None}

    macd_cross_above = macd_line[-1] > signal_line[-1] and macd_line[-2] <= signal_line[-2]
    macd_cross_below = macd_line[-1] < signal_line[-1] and macd_line[-2] >= signal_line[-2]

    # Determine the target position
    target = pos
    if pos == 0:
        if macd_cross_above:
            target = sizing_fraction
        elif macd_cross_below:
            target = -sizing_fraction
    else:
        if (pos > 0 and macd_cross_below) or (pos < 0 and macd_cross_above):
            target = 0

    # Round target to the 0.05 grid
    target = round(target / 0.05) * 0.05

    # Time stop and cooldown logic
    stop = None
    take = None

    if pos != 0:
        # Check for time stop
        if "entry_bar" not in state:
            state["entry_bar"] = len(hist) - 1
        bars_since_entry = len(hist) - 1 - state["entry_bar"]
        if bars_since_entry >= time_stop_bars:
            target = 0

    # Cooldown logic
    if target == 0 and pos == 0:
        if "last_exit_bar" in state:
            bars_since_last_exit = len(hist) - 1 - state["last_exit_bar"]
            if bars_since_last_exit < cooldown_bars:
                target = pos

    # Update state
    if target == 0 and pos != 0:
        state["last_exit_bar"] = len(hist) - 1
        del state["entry_bar"]

    return {"target": target, "stop": stop, "take": take}

