def strategy(hist, state, pos, ind) -> dict:
    # Parameters from the strategy
    macd_fast, macd_slow, macd_signal = 8, 17, 9
    trailing_stop_factor = 1.5
    position_size = 0.25

    # Calculate MACD
    macd_line, signal_line, _ = ind.macd(hist.close, macd_fast, macd_slow, macd_signal)

    # Calculate ATR
    atr = ind.atr(hist, 14)
    entry_atr = atr[-1] if 'entry_atr' not in state else state['entry_atr']

    # Determine the signal
    if pos == 0:
        if macd_line[-1] > signal_line[-1] and macd_line[-2] <= signal_line[-2]:
            # Bullish MACD crossover
            state['target_price'] = hist.close[-1]
            state['entry_atr'] = entry_atr = atr[-1]
            state['best_price'] = hist.high[-1]
            return {"target": position_size, "stop": None, "take": None}
        elif macd_line[-1] < signal_line[-1] and macd_line[-2] >= signal_line[-2]:
            # Bearish MACD crossover
            state['target_price'] = hist.close[-1]
            state['entry_atr'] = entry_atr = atr[-1]
            state['best_price'] = hist.low[-1]
            return {"target": -position_size, "stop": None, "take": None}

    # Update best price for trailing stop
    if pos > 0:
        state['best_price'] = max(state['best_price'], hist.high[-1])
    elif pos < 0:
        state['best_price'] = min(state['best_price'], hist.low[-1])

    # Calculate trailing stop
    trailing_stop = state['best_price'] - trailing_stop_factor * entry_atr if pos > 0 else state['best_price'] + trailing_stop_factor * entry_atr

    # Check for opposite MACD crossover to close the position
    if pos > 0 and macd_line[-1] < signal_line[-1] and macd_line[-2] >= signal_line[-2]:
        return {"target": 0, "stop": None, "take": None}
    elif pos < 0 and macd_line[-1] > signal_line[-1] and macd_line[-2] <= signal_line[-2]:
        return {"target": 0, "stop": None, "take": None}

    # Return the current position with the updated stop
    return {"target": pos, "stop": trailing_stop, "take": None}

