def strategy(hist, state, pos, ind) -> dict:
    # Constants
    ATR_PERIOD = 14
    HTF_MINUTES = 60
    HTF_TREND_PERIOD = 20
    BREAKOUT_PULLBACK_N = 48
    BREAKOUT_PULLBACK_WAIT = 16
    PYRAMID_F0 = 0.25
    PYRAMID_STEP = 2.0
    PYRAMID_ADDS = 1
    FIXED_STOP_K = 1.5
    TAKE_PROFIT_C = 2.0
    TIME_STOP_N = 32

    # Calculate ATR
    atr = ind.atr(hist, ATR_PERIOD)
    entry_atr = atr[-1] if 'entry_atr' not in state else state['entry_atr']

    # Calculate HTF EMA for trend filter
    htf_close = hist.htf(HTF_MINUTES).close
    htf_ema = ind.ema(htf_close, HTF_TREND_PERIOD)

    # Breakout Pullback Signal
    high_48 = ind.highest(hist.high, BREAKOUT_PULLBACK_N)
    low_48 = ind.lowest(hist.low, BREAKOUT_PULLBACK_N)

    if 'breakout_high' not in state and hist.close[-1] > high_48[-2]:
        state['breakout_high'] = hist.close[-1]
        state['breakout_time'] = len(hist) - 1

    if 'breakout_low' not in state and hist.close[-1] < low_48[-2]:
        state['breakout_low'] = hist.close[-1]
        state['breakout_time'] = len(hist) - 1

    if 'breakout_high' in state:
        if len(hist) - state['breakout_time'] > BREAKOUT_PULLBACK_WAIT:
            del state['breakout_high']
            del state['breakout_time']
        elif hist.low[-1] <= state['breakout_high']:
            if pos == 0 and htf_close[-1] > htf_ema[-1]:
                target = round(PYRAMID_F0 * 2, 2)  # Start with 0.5, but round to 0.5 grid
                state['entry_price'] = hist.close[-1]
                state['entry_atr'] = entry_atr
                state['last_add_price'] = hist.close[-1]
                state['adds'] = 0
                state['entry_time'] = len(hist) - 1
                return {"target": target, "stop": state['entry_price'] - FIXED_STOP_K * entry_atr, "take": state['entry_price'] + TAKE_PROFIT_C * entry_atr}

    if 'breakout_low' in state:
        if len(hist) - state['breakout_time'] > BREAKOUT_PULLBACK_WAIT:
            del state['breakout_low']
            del state['breakout_time']
        elif hist.high[-1] >= state['breakout_low']:
            if pos == 0 and htf_close[-1] < htf_ema[-1]:
                target = round(-PYRAMID_F0 * 2, 2)  # Start with -0.5, but round to 0.5 grid
                state['entry_price'] = hist.close[-1]
                state['entry_atr'] = entry_atr
                state['last_add_price'] = hist.close[-1]
                state['adds'] = 0
                state['entry_time'] = len(hist) - 1
                return {"target": target, "stop": state['entry_price'] + FIXED_STOP_K * entry_atr, "take": state['entry_price'] - TAKE_PROFIT_C * entry_atr}

    # Pyramid
    if pos > 0 and 'last_add_price' in state and hist.close[-1] >= state['last_add_price'] + PYRAMID_STEP * entry_atr and state['adds'] < PYRAMID_ADDS:
        state['last_add_price'] = hist.close[-1]
        state['adds'] += 1
        return {"target": min(pos + PYRAMID_F0, 1.0), "stop": state['entry_price'] - FIXED_STOP_K * entry_atr, "take": state['entry_price'] + TAKE_PROFIT_C * entry_atr}

    if pos < 0 and 'last_add_price' in state and hist.close[-1] <= state['last_add_price'] - PYRAMID_STEP * entry_atr and state['adds'] < PYRAMID_ADDS:
        state['last_add_price'] = hist.close[-1]
        state['adds'] += 1
        return {"target": max(pos - PYRAMID_F0, -1.0), "stop": state['entry_price'] + FIXED_STOP_K * entry_atr, "take": state['entry_price'] - TAKE_PROFIT_C * entry_atr}

    # Time Stop
    if 'entry_time' in state and len(hist) - state['entry_time'] >= TIME_STOP_N:
        return {"target": 0, "stop": None, "take": None}

    # Opposite Signal
    if pos > 0 and hist.close[-1] < low_48[-2]:
        return {"target": 0, "stop": None, "take": None}

    if pos < 0 and hist.close[-1] > high_48[-2]:
        return {"target": 0, "stop": None, "take": None}

    # Continue with current stop and take
    if pos != 0:
        return {"target": pos, "stop": state['entry_price'] - FIXED_STOP_K * entry_atr if pos > 0 else state['entry_price'] + FIXED_STOP_K * entry_atr, "take": state['entry_price'] + TAKE_PROFIT_C * entry_atr if pos > 0 else state['entry_price'] - TAKE_PROFIT_C * entry_atr}

    return {"target": pos, "stop": None, "take": None}

import math
import numpy as np

def strategy(hist, state, pos, ind) -> dict:
    # Parameters from the strategy specification
    n = 96
    wait = 32
    htf_minutes = 240
    htf_n = 50
    sizing_frac = 0.75
    stop_k = 3.0
    time_stop_n = 32

    # Calculate the 4-hour EMA for the filter
    htf_hist = hist.htf(htf_minutes)
    htf_ema = ind.ema(htf_hist.close, htf_n)

    # Calculate the 14-bar ATR for stop levels
    atr_14 = ind.atr(hist, 14)
    entry_atr = atr_14[-1]

    # Calculate the 96-bar Donchian high and low for the breakout
    donchian_high = ind.highest(hist.high, n)
    donchian_low = ind.lowest(hist.low, n)

    # Determine the signal for breakout and retest
    if pos == 0:
        # Check for long breakout and retest
        if hist.close[-1] > donchian_high[-2] and 'long_breakout' not in state:
            state['long_breakout'] = hist.close[-1]
            state['long_breakout_time'] = len(hist) - 1
        elif 'long_breakout' in state:
            if len(hist) - 1 - state['long_breakout_time'] <= wait:
                if hist.low[-1] <= state['long_breakout']:
                    if htf_hist.close[-1] > htf_ema[-1]:  # 4-hour EMA filter for long
                        target = sizing_frac
                        stop = hist.close[-1] - stop_k * entry_atr
                        time_stop = hist.close[-1] + time_stop_n * entry_atr
                        del state['long_breakout']
                        del state['long_breakout_time']
                        return {"target": target, "stop": stop, "take": time_stop}
            else:
                del state['long_breakout']
                del state['long_breakout_time']

        # Check for short breakout and retest
        if hist.close[-1] < donchian_low[-2] and 'short_breakout' not in state:
            state['short_breakout'] = hist.close[-1]
            state['short_breakout_time'] = len(hist) - 1
        elif 'short_breakout' in state:
            if len(hist) - 1 - state['short_breakout_time'] <= wait:
                if hist.high[-1] >= state['short_breakout']:
                    if htf_hist.close[-1] < htf_ema[-1]:  # 4-hour EMA filter for short
                        target = -sizing_frac
                        stop = hist.close[-1] + stop_k * entry_atr
                        time_stop = hist.close[-1] - time_stop_n * entry_atr
                        del state['short_breakout']
                        del state['short_breakout_time']
                        return {"target": target, "stop": stop, "take": time_stop}
            else:
                del state['short_breakout']
                del state['short_breakout_time']

    # Check for opposite signal to close the position
    if pos > 0:
        if hist.close[-1] < donchian_low[-2]:
            return {"target": 0, "stop": None, "take": None}
    elif pos < 0:
        if hist.close[-1] > donchian_high[-2]:
            return {"target": 0, "stop": None, "take": None}

    # Maintain stop and take levels if in a position
    if pos > 0:
        stop = hist.close[-1] - stop_k * entry_atr
        time_stop = hist.close[-1] + time_stop_n * entry_atr
        return {"target": pos, "stop": stop, "take": time_stop}
    elif pos < 0:
        stop = hist.close[-1] + stop_k * entry_atr
        time_stop = hist.close[-1] - time_stop_n * entry_atr
        return {"target": pos, "stop": stop, "take": time_stop}

    # No change if no signal or in a position
    return {"target": pos, "stop": None, "take": None}

