    direction = "long_short"
    filter_id = "htf_trend"
    filter_params = {"minutes": 240, "n": 20}
    sizing_id = "atr_risk"
    sizing_params = {"r": 0.01, "k": 3.0}
    risk_ids = ["box_shift", "breakeven", "trailing_hwm"]
    risk_params = [
        {"lo": 2.0, "hi": 2.0, "step": 2.0},
        {"a": 0.5},
        {"b": 1.5, "after_be": True}
    ]

    # Calculate indicators
    atr_14 = ind.atr(hist, 14)
    entry_atr = atr_14[-1] if "entry_atr" not in state else state["entry_atr"]
    htf_240 = hist.htf(240)
    htf_ema_20 = ind.ema(htf_240.close, 20)
    htf_close = htf_240.close

    # Signal calculation
    if signal_id == "donchian_break":
        n = signal_params["n"]
        highest_high = ind.highest(hist.high, n)
        lowest_low = ind.lowest(hist.low, n)
        bullish_signal = hist.close[-1] > highest_high[-1]
        bearish_signal = hist.close[-1] < lowest_low[-1]

    # Filter calculation
    if filter_id == "htf_trend":
        minutes = filter_params["minutes"]
        n = filter_params["n"]
        htf_ema = ind.ema(htf_close, n)
        htf_close_prev = htf_close[-2] if len(htf_close) > 1 else htf_close[-1]
        htf_ema_prev = htf_ema[-2] if len(htf_ema) > 1 else htf_ema[-1]
        long_allowed = htf_close_prev > htf_ema_prev
        short_allowed = htf_close_prev < htf_ema_prev

    # Sizing calculation
    if sizing_id == "atr_risk":
        r = sizing_params["r"]
        k = sizing_params["k"]
        position_fraction = r * hist.close[-1] / (k * entry_atr)
        position_fraction = max(0.05, min(1.0, position_fraction))

