                state["anchor"] = anchor + step * entry_atr
        elif pos < 0:
            if hist.low[-1] <= anchor - step * entry_atr:
                state["anchor"] = anchor - step * entry_atr

    if risk_ids[1] == "breakeven":
        a = risk_params[1]["a"]
        if pos > 0:
            if hist.high[-1] >= state["entry_price"] + a * entry_atr:
                stop = state["entry_price"]
        elif pos < 0:
            if hist.low[-1] <= state["entry_price"] - a * entry_atr:
