            elif not after_be:
                stop = state["hwm"] - b * entry_atr
        elif pos < 0:
            if "hwm" not in state or hist.low[-1] < state["hwm"]:
                state["hwm"] = hist.low[-1]
            if after_be and stop == state["entry_price"]:
                stop = state["hwm"] + b * entry_atr
            elif not after_be:
                stop = state["hwm"] + b * entry_atr

    # Cooldown and daily cap are not explicitly handled in this strategy

    # Determine target position
    target = pos
    if pos == 0:
        if direction == "long_short":
            if bullish_signal and long_allowed:
                target = position_fraction
                state["entry_price"] = hist.close[-1]
                state["entry_atr"] = entry_atr
                del state["anchor"] if "anchor" in state else None
                del state["hwm"] if "hwm" in state else None
            elif bearish_signal and short_allowed:
                target = -position_fraction
                state["entry_price"] = hist.close[-1]
