def strategy(hist, state, pos, ind) -> dict:
    # Parameters from the strategy
    signal_id = "breakout_pullback"
    signal_params = {"n": 48, "wait": 16}
    direction = "long_only"
    filter_id = "htf_trend"
    filter_params = {"minutes": 60, "n": 20}
    sizing_id = "fixed_frac"
    sizing_params = {"f": 0.75}
    risk_ids = ["partial_take", "breakeven", "trailing_hwm"]
    risk_params = [{"c": 1.5}, {"a": 2.0}, {"b": 1.5, "after_be": True}]

    # Helper functions
    def round_to_grid(value, grid=0.05):
        return round(value / grid) * grid

    def ma_cross(kind, fast, slow, close):
        if kind == 'sma':
            fast_ma = ind.sma(close, fast)
            slow_ma = ind.sma(close, slow)
        elif kind == 'ema':
            fast_ma = ind.ema(close, fast)
            slow_ma = ind.ema(close, slow)
        else:
            raise ValueError("Invalid MA type")
        return fast_ma, slow_ma

    def macd_cross(fsg, close):
        macd_line, signal_line, _ = ind.macd(close, *fsg)
        return macd_line, signal_line

    def donchian_break(n, high, low):
        highest_high = ind.highest(high, n)
        lowest_low = ind.lowest(low, n)
        return highest_high, lowest_low

    def rsi_revert(n, lo, close):
        rsi = ind.rsi(close, n)
        return rsi

    def box_breakout(m, w, high, low, atr):
        highest_high = ind.highest(high, m)
        lowest_low = ind.lowest(low, m)
        box_height = highest_high - lowest_low
        valid_box = box_height <= w * atr
        return highest_high, lowest_low, valid_box

    def breakout_pullback(n, wait, high, low):
        highest_high = ind.highest(high, n)
        if 'breakout_level' not in state:
            state['breakout_level'] = None
            state['breakout_bar'] = None

        if high[-1] > highest_high[-1]:
            state['breakout_level'] = highest_high[-1]
            state['breakout_bar'] = len(hist) - 1

        if state['breakout_level'] is not None:
            if len(hist) - 1 - state['breakout_bar'] <= wait:
                if low[-1] <= state['breakout_level']:
                    return True
            else:
                state['breakout_level'] = None
                state['breakout_bar'] = None

        return False

    def htf_trend(minutes, n, close):
        htf_close = hist.htf(minutes).close
        htf_ema = ind.ema(htf_close, n)
        return htf_close, htf_ema

    def fixed_frac(f, close):
        return f

    def atr_risk(r, k, close, atr):
        position_size = r * close / (k * atr)
        return max(0.05, min(1.0, position_size))

    def pyramid(f0, step, adds, close, entry_price, entry_atr, last_add_price):
        if 'add_count' not in state:
            state['add_count'] = 0

        position_size = f0 + state['add_count'] * step / 100
        if state['add_count'] < adds:
            if (close[-1] - last_add_price[-1]) >= entry_atr:
                state['add_count'] += 1
                last_add_price[-1] = close[-1]
                position_size = f0 + state['add_count'] * step / 100

        return position_size, last_add_price

    def fixed_stop(k, entry_price, entry_atr):
        stop = entry_price - k * entry_atr
        return stop

    def breakeven(a, entry_price, entry_atr, high, low):
        if 'breakeven_set' not in state:
            state['breakeven_set'] = False

        if not state['breakeven_set'] and (high[-1] - entry_price) >= a * entry_atr:
            state['breakeven_set'] = True
            return entry_price

        return None

    def trailing_hwm(b, after_be, entry_price, entry_atr, high, low):
        if 'hwm' not in state:
            state['hwm'] = entry_price

        if after_be and 'breakeven_set' in state and state['breakeven_set']:
            state['hwm'] = max(state['hwm'], high[-1])
        else:
            state['hwm'] = max(state['hwm'], high[-1])

        stop = state['hwm'] - b * entry_atr
        return stop

    def time_stop(n, entry_bar):
        if 'entry_bar' not in state:
            state['entry_bar'] = entry_bar

        if len(hist) - 1 - state['entry_bar'] >= n:
            return True

        return False

    def take_profit(c, entry_price, entry_atr):
        take = entry_price + c * entry_atr
        return take

    def partial_take(c, entry_price, entry_atr, high, low):
        if 'partial_taken' not in state:
            state['partial_taken'] = False

        if not state['partial_taken'] and (high[-1] - entry_price) >= c * entry_atr:
            state['partial_taken'] = True
            return True

        return False

    def box_shift(lo, hi, step, entry_price, entry_atr, high, low):
        if 'anchor' not in state:
            state['anchor'] = entry_price

        if (high[-1] - state['anchor']) >= step * entry_atr:
            state['anchor'] = state['anchor'] + step * entry_atr

        stop = state['anchor'] - lo * entry_atr
        take = state['anchor'] + hi * entry_atr
        return stop, take

    def cooldown(n, exit_bar):
        if 'exit_bar' not in state:
            state['exit_bar'] = None

        if exit_bar is not None:
            state['exit_bar'] = exit_bar

        if state['exit_bar'] is not None and len(hist) - 1 - state['exit_bar'] < n:
            return True

        return False

    def daily_cap(k, time):
        if 'last_entry_time' not in state:
            state['last_entry_time'] = None

        current_day = time[-1] // (24 * 60 * 60 * 1000)
        if state['last_entry_time'] is not None:
            last_entry_day = state['last_entry_time'] // (24 * 60 * 60 * 1000)
            if current_day == last_entry_day:
                return True

        return False

    # Signal calculation
    if signal_id == "breakout_pullback":
        signal = breakout_pullback(signal_params["n"], signal_params["wait"], hist.high, hist.low)
    else:
        raise ValueError("Invalid signal id")

    # Filter calculation
    if filter_id == "htf_trend":
        htf_close, htf_ema = htf_trend(filter_params["minutes"], filter_params["n"], hist.close)
        filter_condition = htf_close[-1] > htf_ema[-1]
    else:
        raise ValueError("Invalid filter id")

    # Sizing calculation
    if sizing_id == "fixed_frac":
        position_size = fixed_frac(sizing_params["f"], hist.close)
    else:
        raise ValueError("Invalid sizing id")

    # Risk calculations
    atr = ind.atr(hist, 14)
    entry_atr = atr[-1]
    entry_price = hist.close[-1]
    entry_bar = len(hist) - 1

    stop = None
    take = None

    for risk_id, risk_param in zip(risk_ids, risk_params):
        if risk_id == "fixed_stop":
            stop = fixed_stop(risk_param["k"], entry_price, entry_atr)
        elif risk_id == "breakeven":
            breakeven_stop = breakeven(risk_param["a"], entry_price, entry_atr, hist.high, hist.low)
            if breakeven_stop is not None:
                stop = breakeven_stop
        elif risk_id == "trailing_hwm":
            trailing_stop = trailing_hwm(risk_param["b"], risk_param["after_be"], entry_price, entry_atr, hist.high, hist.low)
            if stop is None or trailing_stop < stop:
                stop = trailing_stop
        elif risk_id == "time_stop":
            if time_stop(risk_param["n"], entry_bar):
                stop = hist.open[-1]
        elif risk_id == "take_profit":
            take = take_profit(risk_param["c"], entry_price, entry_atr)
        elif risk_id == "partial_take":
            if partial_take(risk_param["c"], entry_price, entry_atr, hist.high, hist.low):
                position_size /= 2
        elif risk_id == "box_shift":
            box_stop, box_take = box_shift(risk_param["lo"], risk_param["hi"], risk_param["step"], entry_price, entry_atr, hist.high, hist.low)
            if stop is None or box_stop < stop:
                stop = box_stop
            if take is None or box_take > take:
                take = box_take
        elif risk_id == "cooldown":
            if cooldown(risk_param["n"], state.get('exit_bar', None)):
                signal = False
        elif risk_id == "daily_cap":
            if daily_cap(risk_param["k"], hist.time):
                signal = False
        else:
            raise ValueError("Invalid risk id")

    # Determine target position
    target = 0.0
    if pos == 0.0 and signal and filter_condition:
        target = round_to_grid(position_size)
    elif pos != 0.0:
        target = pos

    # Update state for exit bar
    if pos == 0.0 and state.get('exit_bar', None) is not None:
        del state['exit_bar']

    if pos != 0.0 and target == 0.0:
        state['exit_bar'] = len(hist) - 1

    return {"target": target, "stop": stop, "take": take}

