def strategy(hist, state, pos, ind) -> dict:
    # Parameters
    fast_sma_period = 10
    slow_sma_period = 200
    atr_period = 14
    pyramid_step = 1.0
    max_adds = 1
    trailing_stop_factor = 1.5
    time_stop_bars = 256

    # Calculate indicators
    sma_fast = ind.sma(hist.close, fast_sma_period)
    sma_slow = ind.sma(hist.close, slow_sma_period)
    atr = ind.atr(hist, atr_period)

    # Signal detection
    if len(hist) < slow_sma_period:
        return {"target": pos, "stop": None, "take": None}

    # Check for golden cross (bullish signal)
    if sma_fast[-1] > sma_slow[-1] and sma_fast[-2] <= sma_slow[-2]:
        if pos == 0:
            entry_price = hist.close[-1]
            entry_atr = atr[-1]
            state['entry_price'] = entry_price
            state['entry_atr'] = entry_atr
            state['last_add_price'] = entry_price
            state['adds'] = 0
            state['bars_since_signal'] = 0
            state['highest_high'] = entry_price
            return {"target": 0.25, "stop": entry_price - trailing_stop_factor * entry_atr, "take": None}

    # Check for death cross (bearish signal)
    if sma_fast[-1] < sma_slow[-1] and sma_fast[-2] >= sma_slow[-2]:
        if pos > 0:
            return {"target": 0, "stop": None, "take": None}

    # Pyramid logic
    if pos > 0:
        if state['adds'] < max_adds:
            if hist.close[-1] >= state['last_add_price'] + pyramid_step * state['entry_atr']:
                state['last_add_price'] = hist.close[-1]
                state['adds'] += 1
                return {"target": min(0.25 * (state['adds'] + 1), 1.0), "stop": state['highest_high'] - trailing_stop_factor * state['entry_atr'], "take": None}

    # Trailing stop logic
    if pos > 0:
        state['highest_high'] = max(state['highest_high'], hist.high[-1])
        new_stop = state['highest_high'] - trailing_stop_factor * state['entry_atr']
        if new_stop > state.get('stop', -math.inf):
            state['stop'] = new_stop

    # Time stop logic
    if pos > 0:
        state['bars_since_signal'] += 1
        if state['bars_since_signal'] >= time_stop_bars:
            return {"target": 0, "stop": None, "take": None}

    # Return current position, stop, and take
    return {"target": pos, "stop": state.get('stop', None), "take": None}

