    filter_id = "htf_trend"
    filter_params = {"minutes": 240, "n": 50}
    sizing_id = "atr_risk"
    sizing_params = {"r": 0.01, "k": 1.0}
    risk_ids = ["box_shift", "trailing_hwm", "time_stop"]
    risk_params = [
        {"lo": 1.0, "hi": 2.0, "step": 2.0},
        {"b": 2.0, "after_be": False},
        {"n": 32}
    ]

    # Helper functions
    def round_to_grid(value, grid=0.05):
        return round(value / grid) * grid

    def calculate_atr(hist, n):
        return ind.atr(hist, n)

    def calculate_ema(x, n):
        return ind.ema(x, n)

    def calculate_highest(x, n):
        return ind.highest(x, n)

    def calculate_lowest(x, n):
        return ind.lowest(x, n)

    def calculate_macd(x, fast, slow, signal):
        return ind.macd(x, fast, slow, signal)

    def calculate_rsi(x, n):
        return ind.rsi(x, n)

    # Signal block: box_breakout
    def box_breakout(hist, m, w):
        high = calculate_highest(hist.high, m)
        low = calculate_lowest(hist.low, m)
        atr = calculate_atr(hist, 14)
        box_height = high - low
        valid_box = box_height <= w * atr[-1]
        breakout_long = hist.close[-1] > high and valid_box
        breakout_short = hist.close[-1] < low and valid_box
        return breakout_long, breakout_short

    # Filter block: htf_trend
    def htf_trend(hist, minutes, n):
        htf_hist = hist.htf(minutes)
        htf_close = htf_hist.close
        htf_ema = calculate_ema(htf_close, n)
        long_filter = htf_close[-1] > htf_ema[-1]
        short_filter = htf_close[-1] < htf_ema[-1]
        return long_filter, short_filter

    # Sizing block: atr_risk
    def atr_risk(hist, r, k):
        atr = calculate_atr(hist, 14)
        entry_atr = atr[-1]
        position_fraction = r * hist.close[-1] / (k * entry_atr)
        position_fraction = max(0.05, min(1.0, position_fraction))
        return position_fraction

    # Risk blocks
    def box_shift(state, entry_price, entry_atr, close, lo, hi, step):
        if 'anchor' not in state:
            state['anchor'] = entry_price
        anchor = state['anchor']
        stop = anchor - lo * entry_atr
        target = anchor + hi * entry_atr
        if close >= anchor + step * entry_atr:
            new_anchor = anchor + step * entry_atr
            state['anchor'] = new_anchor
            stop = new_anchor - lo * entry_atr
            target = new_anchor + hi * entry_atr
        return stop, target

    def trailing_hwm(state, entry_price, entry_atr, high, low, b, after_be):
        if 'best_price' not in state:
            state['best_price'] = entry_price
        best_price = state['best_price']
        if pos > 0:
            best_price = max(best_price, high)
        elif pos < 0:
            best_price = min(best_price, low)
        state['best_price'] = best_price
        stop = best_price - b * entry_atr
        if after_be and 'breakeven' in state and state['breakeven']:
            stop = entry_price
        return stop

    def time_stop(state, entry_bar, n):
        if 'entry_bar' not in state:
            state['entry_bar'] = entry_bar
        bars_since_entry = len(hist) - 1 - state['entry_bar']
        if bars_since_entry >= n:
            return 0.0
        return None

    def breakeven(state, entry_price, entry_atr, close, a):
        if pos > 0 and close >= entry_price + a * entry_atr:
            state['breakeven'] = True
        elif pos < 0 and close <= entry_price - a * entry_atr:
            state['breakeven'] = True
        if 'breakeven' in state and state['breakeven']:
            return entry_price
        return None

    def partial_take(state, entry_price, entry_atr, close, c):
        if 'partial_taken' not in state and pos > 0 and close >= entry_price + c * entry_atr:
            state['partial_taken'] = True
            return pos / 2
        elif 'partial_taken' not in state and pos < 0 and close <= entry_price - c * entry_atr:
            state['partial_taken'] = True
            return pos / 2
        return pos

    def take_profit(entry_price, entry_atr, c):
        if pos > 0:
            return entry_price + c * entry_atr
        elif pos < 0:
            return entry_price - c * entry_atr
        return None

    def cooldown(state, n):
        if 'last_exit_bar' in state:
            bars_since_exit = len(hist) - 1 - state['last_exit_bar']
            if bars_since_exit < n:
                return True
        return False

    def daily_cap(state):
        current_day = hist.time[-1] // (1000 * 60 * 60 * 24)
        if 'last_entry_day' in state and state['last_entry_day'] == current_day:
            return True
        return False

    # Main logic
    if pos == 0:
        if 'cooldown' in state and cooldown(state, 4):
            return {"target": pos, "stop": None, "take": None}
        if 'daily_cap' in state and daily_cap(state):
            return {"target": pos, "stop": None, "take": None}

        breakout_long, breakout_short = box_breakout(hist, **signal_params)
        long_filter, short_filter = htf_trend(hist, **filter_params)

        if direction == "long_only":
            breakout_short = False
        elif direction == "long_short":
            breakout_long = breakout_long and long_filter
            breakout_short = breakout_short and short_filter

        if breakout_long:
            entry_price = hist.close[-1]
            entry_atr = calculate_atr(hist, 14)[-1]
            position_fraction = atr_risk(hist, **sizing_params)
            state['entry_price'] = entry_price
            state['entry_atr'] = entry_atr
            state['entry_bar'] = len(hist) - 1
            state['last_entry_day'] = hist.time[-1] // (1000 * 60 * 60 * 24)
            del state.get('last_exit_bar', None)
            del state.get('anchor', None)
            del state.get('best_price', None)
            del state.get('breakeven', None)
            del state.get('partial_taken', None)
            return {"target": round_to_grid(position_fraction), "stop": None, "take": None}
        elif breakout_short:
            entry_price = hist.close[-1]
            entry_atr = calculate_atr(hist, 14)[-1]
            position_fraction = -atr_risk(hist, **sizing_params)
            state['entry_price'] = entry_price
            state['entry_atr'] = entry_atr
            state['entry_bar'] = len(hist) - 1
            state['last_entry_day'] = hist.time[-1] // (1000 * 60 * 60 * 24)
            del state.get('last_exit_bar', None)
            del state.get('anchor', None)
            del state.get('best_price', None)
            del state.get('breakeven', None)
            del state.get('partial_taken', None)
            return {"target": round_to_grid(position_fraction), "stop": None, "take": None}

    if pos != 0:
        entry_price = state['entry_price']
        entry_atr = state['entry_atr']

        stop = None
        take = None

        for risk_id, risk_param in zip(risk_ids, risk_params):
            if risk_id == "box_shift":
                stop, take = box_shift(state, entry_price, entry_atr, hist.close[-1], **risk_param)
            elif risk_id == "trailing_hwm":
                stop = trailing_hwm(state, entry_price, entry_atr, hist.high[-1], hist.low[-1], **risk_param)
            elif risk_id == "time_stop":
                stop = time_stop(state, state['entry_bar'], **risk_param)
            elif risk_id == "breakeven":
                stop = breakeven(state, entry_price, entry_atr, hist.close[-1], **risk_param)
            elif risk_id == "partial_take":
                pos = partial_take(state, entry_price, entry_atr, hist.close[-1], **risk_param)
            elif risk_id == "take_profit":
                take = take_profit(entry_price, entry_atr, **risk_param)
            elif risk_id == "cooldown":
                if cooldown(state, **risk_param):
                    return {"target": 0, "stop": None, "take": None}
            elif risk_id == "daily_cap":
                if daily_cap(state):
                    return {"target": 0, "stop": None, "take": None}

        if stop is not None and (pos > 0 and hist.low[-1] <= stop) or (pos < 0 and hist.high[-1] >= stop):
            state['last_exit_bar'] = len(hist) - 1
            return {"target": 0, "stop": None, "take": None}

        if take is not None and (pos > 0 and hist.high[-1] >= take) or (pos < 0 and hist.low[-1] <= take):
            state['last_exit_bar'] = len(hist) - 1
            return {"target": 0, "stop": None, "take": None}

        return {"target": round_to_grid(pos), "stop": stop, "take": take}

    return {"target": pos, "stop": None, "take": None}

