    lowest_low = ind.lowest(hist.low, signal_params["m"])
    box_height = highest_high - lowest_low
    box_valid = box_height <= signal_params["w"] * entry_atr
    box_breakout_long = hist.close[-1] > highest_high[-1] and box_valid

    # Sizing: ATR Risk
    close = hist.close[-1]
    position_size = sizing_params["r"] * close / (sizing_params["k"] * entry_atr)
    position_size = max(0.05, min(1.0, position_size))

    # Risk: Fixed Stop
    fixed_stop_price = None
    if pos > 0:
        fixed_stop_price = hist.close[-1] - risk_params[0]["k"] * entry_atr

    # Risk: Breakeven
    breakeven_price = None
    if pos > 0 and "breakeven_triggered" not in state:
        breakeven_level = hist.close[-1] + risk_params[1]["a"] * entry_atr
        if hist.close[-1] >= breakeven_level:
            breakeven_price = hist.close[-1]
            state["breakeven_triggered"] = True

    # Risk: Trailing HWM
    trailing_stop_price = None
    if pos > 0:
        if "best_price" not in state:
            state["best_price"] = hist.close[-1]
        else:
            state["best_price"] = max(state["best_price"], hist.close[-1])

        if state.get("breakeven_triggered", False):
            trailing_stop_price = state["best_price"] - risk_params[2]["b"] * entry_atr
        else:
            trailing_stop_price = fixed_stop_price

    # Cooldown
    if "last_exit_time" in state:
        current_time = hist.time[-1]
        last_exit_time = state["last_exit_time"]
        if (current_time - last_exit_time) < 4 * 15 * 60 * 1000:  # 4 bars * 15 minutes * 60 seconds * 1000 ms
            return {"target": pos, "stop": trailing_stop_price, "take": None}

    # Daily Cap
    current_day = hist.time[-1] // (24 * 60 * 60 * 1000)
    if "last_entry_day" in state and state["last_entry_day"] == current_day:
        return {"target": pos, "stop": trailing_stop_price, "take": None}

    # Entry Logic
    if pos == 0 and htf_trend_long and box_breakout_long:
        return {"target": position_size, "stop": trailing_stop_price, "take": None}

    # Exit Logic
    if pos > 0 and hist.close[-1] <= trailing_stop_price:
        state["last_exit_time"] = hist.time[-1]
        state["last_entry_day"] = current_day
        return {"target": 0, "stop": None, "take": None}

    # Short signals just bail out longs
    if pos > 0 and (hist.close[-1] < lowest_low[-1] or box_height > signal_params["w"] * entry_atr):
        state["last_exit_time"] = hist.time[-1]
        state["last_entry_day"] = current_day
        return {"target": 0, "stop": None, "take": None}

    return {"target": pos, "stop": trailing_stop_price, "take": None}

