    pyramid_step = 2.0
    max_adds = 2
    take_profit_factor = 3.0
    time_stop_bars = 64
    cooldown_bars = 4

    # Calculate RSI
    rsi = ind.rsi(hist.close, rsi_period)
    atr = ind.atr(hist, 14)

    # Determine the current RSI conditions
    rsi_current = rsi[-1]
    rsi_previous = rsi[-2]

    # Determine the signal
    signal = None
    if rsi_previous <= rsi_oversold and rsi_current > rsi_oversold:
        signal = "long"
    elif rsi_previous >= rsi_overbought and rsi_current < rsi_overbought:
        signal = "short"

    # Check for existing position and opposite signal
    if pos != 0 and signal is not None:
        if (pos > 0 and signal == "short") or (pos < 0 and signal == "long"):
            return {"target": 0, "stop": None, "take": None}

    # Cooldown check
    if "last_exit_time" in state and len(hist) - state["last_exit_time"] <= cooldown_bars:
        return {"target": pos, "stop": None, "take": None}

    # Time stop check
    if "entry_time" in state and len(hist) - state["entry_time"] >= time_stop_bars:
        return {"target": 0, "stop": None, "take": None}

    # Entry logic
    if signal is not None and pos == 0:
        entry_price = hist.close[-1]
        entry_atr = atr[-1]
        state["entry_price"] = entry_price
        state["entry_atr"] = entry_atr
        state["entry_time"] = len(hist)
        state["last_add_price"] = entry_price
        state["adds"] = 0
        target = initial_size
        stop = None
        take = entry_price + take_profit_factor * entry_atr if signal == "long" else entry_price - take_profit_factor * entry_atr
        return {"target": target, "stop": stop, "take": take}

    # Pyramid logic
    if pos > 0 and signal == "long":
        if hist.close[-1] >= state["last_add_price"] + pyramid_step * state["entry_atr"] and state["adds"] < max_adds:
            state["last_add_price"] = hist.close[-1]
            state["adds"] += 1
            target = min(1.0, pos + initial_size)
            return {"target": target, "stop": None, "take": None}
    elif pos < 0 and signal == "short":
        if hist.close[-1] <= state["last_add_price"] - pyramid_step * state["entry_atr"] and state["adds"] < max_adds:
            state["last_add_price"] = hist.close[-1]
            state["adds"] += 1
            target = max(-1.0, pos - initial_size)
            return {"target": target, "stop": None, "take": None}

    # Maintain existing stop and take
    if pos > 0:
        stop = state["entry_price"] - take_profit_factor * state["entry_atr"]
        take = state["entry_price"] + take_profit_factor * state["entry_atr"]
    elif pos < 0:
        stop = state["entry_price"] + take_profit_factor * state["entry_atr"]
        take = state["entry_price"] - take_profit_factor * state["entry_atr"]

    return {"target": pos, "stop": stop, "take": take}

