        lowest_low = ind.lowest(low, m)
        box_height = highest_high - lowest_low
        valid_box = box_height <= w * atr
        return highest_high, lowest_low, valid_box

    def breakout_pullback(n, wait, high, low):
        highest_high = ind.highest(high, n)
        if 'breakout_level' not in state:
            state['breakout_level'] = None
            state['breakout_time'] = None

        if high[-1] > highest_high[-1]:
            state['breakout_level'] = highest_high[-1]
            state['breakout_time'] = len(hist) - 1

        if state['breakout_level'] is not None:
            if len(hist) - 1 - state['breakout_time'] <= wait:
                if low[-1] <= state['breakout_level']:
                    return True
            else:
                state['breakout_level'] = None
                state['breakout_time'] = None
        return False

    def htf_trend(minutes, n, close):
        htf_close = hist.htf(minutes).close
        htf_ema = ind.ema(htf_close, n)
        return htf_close, htf_ema

    def atr_risk(r, k, close, atr):
        position_size = r * close[-1] / (k * atr[-1])
        position_size = max(0.05, min(1.0, position_size))
        return position_size

    def time_stop(n, entry_time):
        return len(hist) - 1 - entry_time >= n

    # Signal calculation
    signal = False
    if signal_id == "breakout_pullback":
        signal = breakout_pullback(signal_params["n"], signal_params["wait"], hist.high, hist.low)

    # Filter calculation
    filter_pass = True
    if filter_id == "htf_trend":
        htf_close, htf_ema = htf_trend(filter_params["minutes"], filter_params["n"], hist.close)
        if direction == "long_only":
            filter_pass = htf_close[-1] > htf_ema[-1]
        elif direction == "long_short":
            filter_pass = htf_close[-1] < htf_ema[-1]

    # Sizing calculation
    atr = ind.atr(hist, 14)
    position_size = 0.0
    if sizing_id == "atr_risk":
        position_size = atr_risk(sizing_params["r"], sizing_params["k"], hist.close, atr)

    # Risk management
    stop = None
    take = None
    if risk_ids and risk_params:
        for risk_id, risk_param in zip(risk_ids, risk_params):
            if risk_id == "time_stop":
                if pos != 0 and time_stop(risk_param["n"], state.get("entry_time", 0)):
                    return {"target": 0.0, "stop": None, "take": None}

    # Entry logic
    if pos == 0 and signal and filter_pass:
        state["entry_time"] = len(hist) - 1
        state["entry_price"] = hist.close[-1]
        state["entry_atr"] = atr[-1]
        return {"target": round_to_grid(position_size), "stop": None, "take": None}

    # Exit logic
    if pos != 0:
        if risk_ids and risk_params:
            for risk_id, risk_param in zip(risk_ids, risk_params):
                if risk_id == "time_stop":
                    if time_stop(risk_param["n"], state.get("entry_time", 0)):
                        return {"target": 0.0, "stop": None, "take": None}

    return {"target": pos, "stop": stop, "take": take}

