            ma_slow = ind.ema(hist.close, signal_params["slow"])

        bullish_signal = (ma_fast[-1] > ma_slow[-1]) and (ma_fast[-2] <= ma_slow[-2])
        bearish_signal = (ma_fast[-1] < ma_slow[-1]) and (ma_fast[-2] >= ma_slow[-2])

    # Filter calculation
    if filter_id == "no_filter":
        filter_pass = True
    elif filter_id == "htf_trend":
        htf_minutes = filter_params["minutes"]
