    elif sizing_id == "pyramid":
        f0 = sizing_params["f0"]
        step = sizing_params["step"]
        adds = sizing_params["adds"]
        if "entry_price" not in state:
            state["entry_price"] = hist.close[-1]
            state["position_fraction"] = f0
            state["adds"] = 0
        else:
            entry_price = state["entry_price"]
            position_fraction = state["position_fraction"]
            current_adds = state["adds"]
            entry_atr = state["entry_atr"]
            if current_adds < adds:
                if (pos > 0 and hist.close[-1] >= entry_price + step * entry_atr) or (pos < 0 and hist.close[-1] <= entry_price - step * entry_atr):
                    position_fraction = min(1.0, position_fraction + f0)
                    state["entry_price"] = hist.close[-1]
                    state["position_fraction"] = position_fraction
                    state["adds"] = current_adds + 1
        position_fraction = round(position_fraction / 0.05) * 0.05

    # Risk management
    stop = None
    take = None
    if risk_ids:
        for risk_id, risk_param in zip(risk_ids, risk_params):
            if risk_id == "fixed_stop":
                k = risk_param["k"]
                if pos > 0:
                    stop = hist.close[-1] - k * atr_14[-1]
                elif pos < 0:
                    stop = hist.close[-1] + k * atr_14[-1]
            elif risk_id == "breakeven":
                a = risk_param["a"]
                if pos > 0 and hist.close[-1] >= state["entry_price"] + a * state["entry_atr"]:
                    stop = state["entry_price"]
                elif pos < 0 and hist.close[-1] <= state["entry_price"] - a * state["entry_atr"]:
                    stop = state["entry_price"]
