                b = risk_param["b"]
                after_be = risk_param["after_be"]
                if pos > 0:
                    if "hwm" not in state or hist.high[-1] > state["hwm"]:
                        state["hwm"] = hist.high[-1]
                    if after_be and stop is not None and stop >= state["entry_price"]:
