                    if "hwm" not in state or hist.low[-1] < state["hwm"]:
                        state["hwm"] = hist.low[-1]
                    if after_be and stop is not None and stop <= state["entry_price"]:
                        stop = state["hwm"] + b * state["entry_atr"]
                    elif not after_be:
                        stop = state["hwm"] + b * state["entry_atr"]
