                    bars_since_signal = len(hist) - state["signal_bar"]
                    if bars_since_signal >= n:
                        return {"target": 0, "stop": None, "take": None}
            elif risk_id == "take_profit":
                c = risk_param["c"]
                if pos > 0:
                    take = hist.close[-1] + c * state["entry_atr"]
                elif pos < 0:
                    take = hist.close[-1] - c * state["entry_atr"]
            elif risk_id == "partial_take":
                c = risk_param["c"]
                if pos > 0 and hist.close[-1] >= state["entry_price"] + c * state["entry_atr"]:
                    position_fraction = round(position_fraction / 2 / 0.05) * 0.05
                    state["position_fraction"] = position_fraction
                elif pos < 0 and hist.close[-1] <= state["entry_price"] - c * state["entry_atr"]:
                    position_fraction = round(position_fraction / 2 / 0.05) * 0.05
                    state["position_fraction"] = position_fraction
            elif risk_id == "box_shift":
                lo = risk_param["lo"]
                hi = risk_param["hi"]
                step = risk_param["step"]
                if "anchor" not in state:
                    state["anchor"] = hist.close[-1]
                if pos > 0:
                    if hist.close[-1] >= state["anchor"] + step * state["entry_atr"]:
                        state["anchor"] = hist.close[-1]
                        stop = state["anchor"] - lo * state["entry_atr"]
                        take = state["anchor"] + hi * state["entry_atr"]
                elif pos < 0:
                    if hist.close[-1] <= state["anchor"] - step * state["entry_atr"]:
                        state["anchor"] = hist.close[-1]
                        stop = state["anchor"] + lo * state["entry_atr"]
                        take = state["anchor"] - hi * state["entry_atr"]
            elif risk_id == "cooldown":
                n = risk_param["n"]
                if "exit_bar" in state:
                    bars_since_exit = len(hist) - state["exit_bar"]
                    if bars_since_exit < n:
                        return {"target": 0, "stop": None, "take": None}
            elif risk_id == "daily_cap":
                k = risk_param["k"]
                current_time = hist.time[-1]
                current_day = current_time // (24 * 60 * 60 * 1000)
                if "last_entry_day" in state and state["last_entry_day"] == current_day:
                    return {"target": 0, "stop": None, "take": None}
                else:
                    state["last_entry_day"] = current_day

    # Determine target
    if pos == 0:
        if filter_pass:
            if bullish_signal:
                state["entry_price"] = hist.close[-1]
                state["entry_atr"] = atr_14[-1]
                state["signal_bar"] = len(hist)
                del state.get("exit_bar", None)
                return {"target": position_fraction, "stop": stop, "take": take}
            elif bearish_signal:
                state["entry_price"] = hist.close[-1]
                state["entry_atr"] = atr_14[-1]
                state["signal_bar"] = len(hist)
                del state.get("exit_bar", None)
                return {"target": -position_fraction, "stop": stop, "take": take}
    else:
        if (pos > 0 and bearish_signal) or (pos < 0 and bullish_signal):
            state["exit_bar"] = len(hist)
            del state.get("signal_bar", None)
            return {"target": 0, "stop": None, "take": None}

    return {"target": pos, "stop": stop, "take": take}

