def strategy(hist, state, pos, ind) -> dict:
    # Parameters
    fast_ema_period = 5
    slow_ema_period = 50
    position_size = 0.75
    partial_take_factor = 1.5
    time_stop_bars = 64
    cooldown_bars = 16

    # Calculate EMAs
    fast_ema = ind.ema(hist.close, fast_ema_period)
    slow_ema = ind.ema(hist.close, slow_ema_period)
    atr_14 = ind.atr(hist, 14)

    # Determine signal
    if len(hist) < max(fast_ema_period, slow_ema_period, 14):
        return {"target": pos, "stop": None, "take": None}

    # Check for crossover
    ema_cross_up = fast_ema[-1] > slow_ema[-1] and fast_ema[-2] <= slow_ema[-2]
    ema_cross_down = fast_ema[-1] < slow_ema[-1] and fast_ema[-2] >= slow_ema[-2]

    # Determine direction
    direction = None
    if ema_cross_up:
        direction = "long"
    elif ema_cross_down:
        direction = "short"

    # Check for opposite signal to close position
    if pos > 0 and ema_cross_down:
        return {"target": 0, "stop": None, "take": None}
    elif pos < 0 and ema_cross_up:
        return {"target": 0, "stop": None, "take": None}

    # Cooldown check
    if "last_exit_bar" in state and len(hist) - state["last_exit_bar"] < cooldown_bars:
        return {"target": pos, "stop": None, "take": None}

    # Entry logic
    if direction is not None and pos == 0:
        entry_price = hist.close[-1]
        entry_atr = atr_14[-1]
        target = position_size if direction == "long" else -position_size
        stop = entry_price - partial_take_factor * entry_atr if direction == "long" else entry_price + partial_take_factor * entry_atr
        take = None
        state["entry_price"] = entry_price
        state["entry_atr"] = entry_atr
        state["signal_bar"] = len(hist) - 1
        state["partial_taken"] = False
        return {"target": target, "stop": stop, "take": take}

    # Existing position logic
    if pos != 0:
        entry_price = state["entry_price"]
        entry_atr = state["entry_atr"]
        signal_bar = state["signal_bar"]
        partial_taken = state["partial_taken"]

        # Time stop
        if len(hist) - signal_bar >= time_stop_bars:
            return {"target": 0, "stop": None, "take": None}

        # Partial take profit
        if not partial_taken:
            if (direction == "long" and hist.close[-1] >= entry_price + partial_take_factor * entry_atr) or \
               (direction == "short" and hist.close[-1] <= entry_price - partial_take_factor * entry_atr):
                state["partial_taken"] = True
                return {"target": pos / 2, "stop": None, "take": None}

        # Stop and take levels
        stop = entry_price - 2 * entry_atr if direction == "long" else entry_price + 2 * entry_atr
        take = None

        return {"target": pos, "stop": stop, "take": take}

    return {"target": pos, "stop": None, "take": None}

