def strategy(hist, state, pos, ind) -> dict:
    # Constants
    DONCHIAN_N = 20
    HTF_MINUTES = 240
    HTF_N = 50
    ATR_N = 14
    RISK_R = 0.01
    RISK_K = 1.0
    PARTIAL_TAKE_C = 2.0
    DAILY_CAP_K = 2

    # Calculate indicators
    htf = hist.htf(HTF_MINUTES)
    htf_ema = ind.ema(htf.close, HTF_N)
    atr = ind.atr(hist, ATR_N)
    donchian_high = ind.highest(hist.high, DONCHIAN_N)
    donchian_low = ind.lowest(hist.low, DONCHIAN_N)

    # Get current bar index
    t = len(hist) - 1

    # Calculate entry ATR
    entry_atr = atr[t] if 'entry_atr' not in state else state['entry_atr']

    # Calculate position size
    def calculate_position_size(close, entry_atr):
        size = RISK_R * close / (RISK_K * entry_atr)
        return max(0.05, min(1.0, size))

    # Check daily cap
    current_day = hist.time[t] // (1000 * 60 * 60 * 24)
    if 'last_trade_day' in state and state['last_trade_day'] == current_day:
        daily_trades = state.get('daily_trades', 0)
        if daily_trades >= DAILY_CAP_K:
            return {"target": pos, "stop": None, "take": None}

    # Check for cooldown
    if 'cooldown_until' in state and t < state['cooldown_until']:
        return {"target": pos, "stop": None, "take": None}

    # Check for opposite Donchian breakout while running
    if pos > 0 and hist.close[t] < donchian_low[t]:
        return {"target": 0, "stop": None, "take": None}
    if pos < 0 and hist.close[t] > donchian_high[t]:
        return {"target": 0, "stop": None, "take": None}

    # Check for new entry signals
    if pos == 0:
        # Long signal
        if hist.close[t] > donchian_high[t] and htf.close[t] > htf_ema[t]:
            target = calculate_position_size(hist.close[t], atr[t])
            state['entry_atr'] = atr[t]
            state['entry_price'] = hist.close[t]
            state['last_trade_day'] = current_day
            state['daily_trades'] = state.get('daily_trades', 0) + 1
            state['partial_take_triggered'] = False
            return {"target": target, "stop": None, "take": None}

        # Short signal
        if hist.close[t] < donchian_low[t] and htf.close[t] < htf_ema[t]:
            target = -calculate_position_size(hist.close[t], atr[t])
            state['entry_atr'] = atr[t]
            state['entry_price'] = hist.close[t]
            state['last_trade_day'] = current_day
            state['daily_trades'] = state.get('daily_trades', 0) + 1
            state['partial_take_triggered'] = False
            return {"target": target, "stop": None, "take": None}

    # Calculate stop and take levels
    stop = None
    take = None

    if pos > 0:
        stop = state['entry_price'] - entry_atr
        if not state['partial_take_triggered'] and hist.close[t] >= state['entry_price'] + PARTIAL_TAKE_C * entry_atr:
            state['partial_take_triggered'] = True
            target = pos / 2
            return {"target": target, "stop": stop, "take": None}

    if pos < 0:
        stop = state['entry_price'] + entry_atr
        if not state['partial_take_triggered'] and hist.close[t] <= state['entry_price'] - PARTIAL_TAKE_C * entry_atr:
            state['partial_take_triggered'] = True
            target = pos / 2
            return {"target": target, "stop": stop, "take": None}

    return {"target": pos, "stop": stop, "take": take}

