def strategy(hist, state, pos, ind) -> dict:
    # Constants
    ATR_PERIOD = 14
    DONCHIAN_PERIOD = 48
    PULLBACK_WAIT = 32
    PYRAMID_F0 = 0.25
    PYRAMID_STEP = 1.0
    PYRAMID_ADDS = 2
    BREAKEVEN_A = 2.0
    TAKE_PROFIT_C = 4.0
    TRAILING_HWM_B = 4.0
    TRAILING_HWM_AFTER_BE = True

    # Calculate ATR
    atr = ind.atr(hist, ATR_PERIOD)
    entry_atr = atr[-1] if 'entry_atr' not in state else state['entry_atr']

    # Calculate Donchian Channel
    donchian_high = ind.highest(hist.high, DONCHIAN_PERIOD)
    donchian_low = ind.lowest(hist.low, DONCHIAN_PERIOD)

    # Breakout Pullback Signal
    if 'breakout_level' not in state:
        if hist.close[-1] > donchian_high[-2]:
            state['breakout_level'] = donchian_high[-2]
            state['breakout_time'] = len(hist) - 1
        elif hist.close[-1] < donchian_low[-2]:
            state['breakout_level'] = donchian_low[-2]
            state['breakout_time'] = len(hist) - 1
    else:
        if len(hist) - 1 - state['breakout_time'] > PULLBACK_WAIT:
            del state['breakout_level']
            del state['breakout_time']
        elif pos == 0:
            if hist.close[-1] <= state['breakout_level'] and hist.close[-2] > state['breakout_level']:
                target = PYRAMID_F0
                state['entry_price'] = hist.close[-1]
                state['entry_atr'] = entry_atr
                state['last_add_price'] = hist.close[-1]
                state['adds'] = 0
                state['breakeven_hit'] = False
                return {"target": target, "stop": None, "take": None}
            elif hist.close[-1] >= state['breakout_level'] and hist.close[-2] < state['breakout_level']:
                target = -PYRAMID_F0
                state['entry_price'] = hist.close[-1]
                state['entry_atr'] = entry_atr
                state['last_add_price'] = hist.close[-1]
                state['adds'] = 0
                state['breakeven_hit'] = False
                return {"target": target, "stop": None, "take": None}

    # Opposite signal to close position
    if pos > 0 and hist.close[-1] < donchian_low[-2]:
        return {"target": 0, "stop": None, "take": None}
    elif pos < 0 and hist.close[-1] > donchian_high[-2]:
        return {"target": 0, "stop": None, "take": None}

    # Pyramid Sizing
    if pos > 0 and state['adds'] < PYRAMID_ADDS:
        if hist.close[-1] >= state['last_add_price'] + PYRAMID_STEP * entry_atr:
            state['last_add_price'] = hist.close[-1]
            state['adds'] += 1
            return {"target": min(pos + PYRAMID_F0, 1.0), "stop": None, "take": None}
    elif pos < 0 and state['adds'] < PYRAMID_ADDS:
        if hist.close[-1] <= state['last_add_price'] - PYRAMID_STEP * entry_atr:
            state['last_add_price'] = hist.close[-1]
            state['adds'] += 1
            return {"target": max(pos - PYRAMID_F0, -1.0), "stop": None, "take": None}

    # Breakeven Stop
    if pos > 0 and not state['breakeven_hit'] and hist.close[-1] >= state['entry_price'] + BREAKEVEN_A * entry_atr:
        state['breakeven_hit'] = True
    elif pos < 0 and not state['breakeven_hit'] and hist.close[-1] <= state['entry_price'] - BREAKEVEN_A * entry_atr:
        state['breakeven_hit'] = True

    # Trailing Stop
    if pos > 0:
        if state['breakeven_hit']:
            stop = max(state['entry_price'], hist.low[-1] + TRAILING_HWM_B * entry_atr)
        else:
            stop = state['entry_price'] - TRAILING_HWM_B * entry_atr
    elif pos < 0:
        if state['breakeven_hit']:
            stop = min(state['entry_price'], hist.high[-1] - TRAILING_HWM_B * entry_atr)
        else:
            stop = state['entry_price'] + TRAILING_HWM_B * entry_atr
    else:
        stop = None

    # Take Profit
    if pos > 0:
        take = state['entry_price'] + TAKE_PROFIT_C * entry_atr
    elif pos < 0:
        take = state['entry_price'] - TAKE_PROFIT_C * entry_atr
    else:
        take = None

    return {"target": pos, "stop": stop, "take": take}

