def strategy(hist, state, pos, ind) -> dict:
    # Parameters from the strategy specification
    signal_id = "breakout_pullback"
    signal_params = {"n": 48, "wait": 8}
    direction = "long_short"
    filter_id = "htf_trend"
    filter_params = {"minutes": 240, "n": 20}
    sizing_id = "pyramid"
    sizing_params = {"f0": 0.5, "step": 1.0, "adds": 1}
    risk_ids = ["trailing_hwm", "cooldown"]
    risk_params = [{"b": 4.0, "after_be": False}, {"n": 48}]

    # Helper functions
    def round_to_grid(value, grid=0.05):
        return round(value / grid) * grid

    def ma_cross(kind, fast, slow, close):
        if kind == 'sma':
            fast_ma = ind.sma(close, fast)
            slow_ma = ind.sma(close, slow)
        elif kind == 'ema':
            fast_ma = ind.ema(close, fast)
            slow_ma = ind.ema(close, slow)
        else:
            raise ValueError("Invalid MA type")
        return fast_ma, slow_ma

    def macd_cross(fast, slow, signal, close):
        macd_line, signal_line, _ = ind.macd(close, fast, slow, signal)
        return macd_line, signal_line

    def donchian_break(n, high, low):
        highest_high = ind.highest(high, n)
        lowest_low = ind.lowest(low, n)
        return highest_high, lowest_low

    def rsi_revert(n, lo, close):
        rsi = ind.rsi(close, n)
        return rsi

    def box_breakout(m, w, high, low, atr):
        highest_high = ind.highest(high, m)
        lowest_low = ind.lowest(low, m)
        box_height = highest_high - lowest_low
        valid_box = box_height <= w * atr
        return highest_high, lowest_low, valid_box

    def breakout_pullback(n, wait, high, low):
        highest_high = ind.highest(high, n)
        lowest_low = ind.lowest(low, n)
        breakout_level = None
        breakout_bar = None
        for i in range(1, wait + 1):
            if len(hist) - i >= 0:
                if high[-i] > highest_high[-i-1]:
                    breakout_level = highest_high[-i-1]
                    breakout_bar = len(hist) - i
                    break
                elif low[-i] < lowest_low[-i-1]:
                    breakout_level = lowest_low[-i-1]
                    breakout_bar = len(hist) - i
                    break
        if breakout_level is not None and len(hist) - breakout_bar <= wait:
            if low[-1] <= breakout_level:
                return True, "bullish"
            elif high[-1] >= breakout_level:
                return True, "bearish"
        return False, None

    def htf_trend(minutes, n, close):
        htf_close = hist.htf(minutes).close
        htf_ema = ind.ema(htf_close, n)
        return htf_close, htf_ema

    def atr_risk(r, k, close, atr):
        position_size = r * close / (k * atr)
        return max(0.05, min(1.0, position_size))

    def fixed_frac(f):
        return f

    def pyramid(f0, step, adds, close, entry_price, entry_atr, last_add_price, num_adds):
        if num_adds >= adds:
            return f0, last_add_price
        if (close[-1] >= last_add_price + step * entry_atr and pos > 0) or (close[-1] <= last_add_price - step * entry_atr and pos < 0):
            return min(1.0, f0 + (num_adds + 1) * step * f0), close[-1]
        return f0, last_add_price

    def fixed_stop(k, entry_price, entry_atr):
        stop = entry_price - k * entry_atr if pos > 0 else entry_price + k * entry_atr
        return stop

    def breakeven(a, entry_price, entry_atr, high, low):
        breakeven_price = entry_price + a * entry_atr if pos > 0 else entry_price - a * entry_atr
        if pos > 0 and high[-1] >= breakeven_price:
            return entry_price
        elif pos < 0 and low[-1] <= breakeven_price:
            return entry_price
        return None

    def trailing_hwm(b, after_be, entry_price, entry_atr, high, low, best_price, be_triggered):
        if pos > 0:
            current_best = max(best_price, high[-1])
        elif pos < 0:
            current_best = min(best_price, low[-1])
        else:
            return None, best_price, be_triggered

        if after_be and not be_triggered:
            breakeven_price = entry_price + entry_atr if pos > 0 else entry_price - entry_atr
            if pos > 0 and high[-1] >= breakeven_price:
                be_triggered = True
            elif pos < 0 and low[-1] <= breakeven_price:
                be_triggered = True

        if be_triggered:
            stop = current_best - b * entry_atr if pos > 0 else current_best + b * entry_atr
        else:
            stop = entry_price - b * entry_atr if pos > 0 else entry_price + b * entry_atr

        return stop, current_best, be_triggered

    def time_stop(n, entry_bar):
        if len(hist) - entry_bar >= n:
            return 0.0
        return None

    def take_profit(c, entry_price, entry_atr):
        take = entry_price + c * entry_atr if pos > 0 else entry_price - c * entry_atr
        return take

    def partial_take(c, entry_price, entry_atr, high, low, take_triggered):
        take_price = entry_price + c * entry_atr if pos > 0 else entry_price - c * entry_atr
        if not take_triggered and ((pos > 0 and high[-1] >= take_price) or (pos < 0 and low[-1] <= take_price)):
            take_triggered = True
            return pos / 2, take_triggered
        return pos, take_triggered

    def box_shift(lo, hi, step, entry_price, entry_atr, high, low, anchor, stop, target, shift_triggered):
        if pos > 0:
            current_best = max(anchor, high[-1])
        elif pos < 0:
            current_best = min(anchor, low[-1])
        else:
            return anchor, stop, target, shift_triggered

        if (pos > 0 and high[-1] >= anchor + step * entry_atr) or (pos < 0 and low[-1] <= anchor - step * entry_atr):
            shift_triggered = True
            anchor = current_best
            stop = anchor - lo * entry_atr if pos > 0 else anchor + lo * entry_atr
            target = anchor + hi * entry_atr if pos > 0 else anchor - hi * entry_atr

        return anchor, stop, target, shift_triggered

    def cooldown(n, last_exit_bar):
        if len(hist) - last_exit_bar < n:
            return True
        return False

    def daily_cap(k, last_entry_time):
        current_time = hist.time[-1]
        current_day = current_time // (24 * 60 * 60 * 1000)
        last_entry_day = last_entry_time // (24 * 60 * 60 * 1000)
        if current_day > last_entry_day:
            return False
        return True

    # Signal block
    high = hist.high
    low = hist.low
    close = hist.close
    atr = ind.atr(hist, 14)

    if signal_id == "breakout_pullback":
        breakout, signal_direction = breakout_pullback(signal_params["n"], signal_params["wait"], high, low)
    else:
        raise ValueError("Invalid signal block")

    # Filter block
    if filter_id == "htf_trend":
        htf_close, htf_ema = htf_trend(filter_params["minutes"], filter_params["n"], close)
        if pos == 0:
            if signal_direction == "bullish" and htf_close[-1] <= htf_ema[-1]:
                breakout = False
            elif signal_direction == "bearish" and htf_close[-1] >= htf_ema[-1]:
                breakout = False
    else:
        raise ValueError("Invalid filter block")

    # Sizing block
    if sizing_id == "fixed_frac":
        position_size = fixed_frac(sizing_params["f"])
    elif sizing_id == "atr_risk":
        position_size = atr_risk(sizing_params["r"], sizing_params["k"], close[-1], atr[-1])
    elif sizing_id == "pyramid":
        if "entry_price" not in state:
            state["entry_price"] = close[-1]
            state["entry_atr"] = atr[-1]
            state["last_add_price"] = close[-1]
            state["num_adds"] = 0
        position_size, state["last_add_price"] = pyramid(
            sizing_params["f0"], sizing_params["step"], sizing_params["adds"],
            close, state["entry_price"], state["entry_atr"], state["last_add_price"], state["num_adds"]
        )
        state["num_adds"] = 1 if state["last_add_price"] != close[-1] else state["num_adds"]
    else:
        raise ValueError("Invalid sizing block")

    # Risk blocks
    stop = None
    take = None
    be_triggered = state.get("be_triggered", False)
    shift_triggered = state.get("shift_triggered", False)
    last_add_price = state.get("last_add_price", close[-1])
    num_adds = state.get("num_adds", 0)
    entry_price = state.get("entry_price", close[-1])
    entry_atr = state.get("entry_atr", atr[-1])
    anchor = state.get("anchor", entry_price)
    best_price = state.get("best_price", entry_price)
    last_exit_bar = state.get("last_exit_bar", -math.inf)
    last_entry_time = state.get("last_entry_time", -math.inf)

    for i, risk_id in enumerate(risk_ids):
        if risk_id == "fixed_stop":
            stop = fixed_stop(risk_params[i]["k"], entry_price, entry_atr)
        elif risk_id == "breakeven":
            new_stop = breakeven(risk_params[i]["a"], entry_price, entry_atr, high, low)
            if new_stop is not None:
                stop = new_stop
                be_triggered = True
        elif risk_id == "trailing_hwm":
            stop, best_price, be_triggered = trailing_hwm(
                risk_params[i]["b"], risk_params[i]["after_be"], entry_price, entry_atr, high, low, best_price, be_triggered
            )
        elif risk_id == "time_stop":
            if pos != 0:
                stop = time_stop(risk_params[i]["n"], state.get("entry_bar", len(hist) - 1))
        elif risk_id == "take_profit":
            take = take_profit(risk_params[i]["c"], entry_price, entry_atr)
        elif risk_id == "partial_take":
            pos, take_triggered = partial_take(
                risk_params[i]["c"], entry_price, entry_atr, high, low, state.get("take_triggered", False)
            )
            if take_triggered:
                state["take_triggered"] = True
        elif risk_id == "box_shift":
            anchor, stop, target, shift_triggered = box_shift(
                risk_params[i]["lo"], risk_params[i]["hi"], risk_params[i]["step"],
                entry_price, entry_atr, high, low, anchor, stop, take, shift_triggered
            )
        elif risk_id == "cooldown":
            if pos == 0 and cooldown(risk_params[i]["n"], last_exit_bar):
                breakout = False
        elif risk_id == "daily_cap":
            if pos == 0 and daily_cap(risk_params[i]["k"], last_entry_time):
                breakout = False
        else:
            raise ValueError("Invalid risk block")

    # Entry logic
    if pos == 0 and breakout:
        if signal_direction == "bullish":
            target = round_to_grid(position_size)
        elif signal_direction == "bearish":
            target = round_to_grid(-position_size)
        state["entry_price"] = close[-1]
        state["entry_atr"] = atr[-1]
        state["entry_bar"] = len(hist) - 1
        state["last_entry_time"] = hist.time[-1]
        state["be_triggered"] = False
        state["shift_triggered"] = False
        state["last_add_price"] = close[-1]
        state["num_adds"] = 0
        state["anchor"] = close[-1]
        state["best_price"] = close[-1]
        state["take_triggered"] = False
    elif pos != 0 and signal_direction is not None:
        target = 0.0
        state["last_exit_bar"] = len(hist) - 1
        state["be_triggered"] = False
        state["shift_triggered"] = False
        state["last_add_price"] = close[-1]
        state["num_adds"] = 0
        state["anchor"] = close[-1]
        state["best_price"] = close[-1]
        state["take_triggered"] = False
    else:
        target = round_to_grid(pos)

    return {"target": target, "stop": stop, "take": take}

