    sizing_params = {"r": 0.005, "k": 2.0}
    risk_ids = ["box_shift", "time_stop", "daily_cap"]
    risk_params = [{"lo": 1.0, "hi": 3.0, "step": 1.0}, {"n": 32}, {"k": 3}]

    # Helper functions
    def round_to_grid(value, grid=0.05):
        return round(value / grid) * grid

    def get_daily_bar_index(hist):
        current_time = hist.time[-1]
        daily_start_time = current_time - (current_time % (24 * 60 * 60 * 1000))
        return np.searchsorted(hist.time, daily_start_time, side='right') - 1

    # Signal calculation
    if signal_id == "breakout_pullback":
        n = signal_params["n"]
        wait = signal_params["wait"]
        highs = ind.highest(hist.high, n)
        lows = ind.lowest(hist.low, n)

        if len(hist) < n + wait:
            return {"target": pos, "stop": None, "take": None}

        current_high = highs[-1]
        current_low = lows[-1]

        if hist.close[-1] > current_high:
            breakout_level = current_high
            breakout_time = len(hist) - 1
            state["breakout_level"] = breakout_level
            state["breakout_time"] = breakout_time
        elif hist.close[-1] < current_low:
            breakout_level = current_low
            breakout_time = len(hist) - 1
            state["breakout_level"] = breakout_level
            state["breakout_time"] = breakout_time

        if "breakout_level" in state and "breakout_time" in state:
            breakout_level = state["breakout_level"]
            breakout_time = state["breakout_time"]

            if len(hist) - breakout_time > wait:
                del state["breakout_level"]
                del state["breakout_time"]
            elif (pos == 0 and hist.close[-1] <= breakout_level and hist.close[-2] > breakout_level):
                signal = "long"
            elif (pos == 0 and hist.close[-1] >= breakout_level and hist.close[-2] < breakout_level):
                signal = "short"
            else:
                return {"target": pos, "stop": None, "take": None}
        else:
            return {"target": pos, "stop": None, "take": None}
    else:
        return {"target": pos, "stop": None, "take": None}

    # Filter calculation
    if filter_id == "htf_trend":
        minutes = filter_params["minutes"]
        n = filter_params["n"]
        htf_hist = hist.htf(minutes)
        htf_close = htf_hist.close
        htf_ema = ind.ema(htf_close, n)

        if len(htf_close) < n:
            return {"target": pos, "stop": None, "take": None}

        if signal == "long" and htf_close[-1] <= htf_ema[-1]:
            return {"target": pos, "stop": None, "take": None}
        elif signal == "short" and htf_close[-1] >= htf_ema[-1]:
            return {"target": pos, "stop": None, "take": None}

    # Sizing calculation
    if sizing_id == "atr_risk":
        r = sizing_params["r"]
        k = sizing_params["k"]
        atr_14 = ind.atr(hist, 14)[-1]
        entry_price = hist.close[-1]
        position_fraction = r * entry_price / (k * atr_14)
        position_fraction = max(0.05, min(1.0, position_fraction))
    else:
        position_fraction = 0.0

    # Risk management
    entry_atr = atr_14
    entry_price = hist.close[-1]
    bars_since_signal = len(hist) - 1

    stop = None
    take = None

    if risk_ids and risk_params:
        for risk_id, risk_param in zip(risk_ids, risk_params):
            if risk_id == "box_shift":
                lo = risk_param["lo"]
                hi = risk_param["hi"]
                step = risk_param["step"]

                if pos > 0:
                    anchor = state.get("anchor", entry_price)
                    stop = anchor - lo * entry_atr
                    take = anchor + hi * entry_atr

                    if hist.close[-1] >= anchor + step * entry_atr:
                        state["anchor"] = anchor + step * entry_atr
                elif pos < 0:
                    anchor = state.get("anchor", entry_price)
                    stop = anchor + lo * entry_atr
                    take = anchor - hi * entry_atr

                    if hist.close[-1] <= anchor - step * entry_atr:
                        state["anchor"] = anchor - step * entry_atr
            elif risk_id == "time_stop":
                n = risk_param["n"]
                if bars_since_signal >= n:
                    return {"target": 0, "stop": None, "take": None}
            elif risk_id == "daily_cap":
                k = risk_param["k"]
                daily_bar_index = get_daily_bar_index(hist)
                if daily_bar_index in state.get("daily_trades", []):
                    return {"target": pos, "stop": None, "take": None}
                else:
                    state.setdefault("daily_trades", []).append(daily_bar_index)
                    if len(state["daily_trades"]) > k:
                        state["daily_trades"].pop(0)

    # Determine target
    if pos == 0 and signal:
        target = position_fraction if signal == "long" else -position_fraction
    else:
        target = pos

    return {"target": round_to_grid(target), "stop": stop, "take": take}

import math
import numpy as np

def strategy(hist, state, pos, ind) -> dict:
    # Constants
    n = 48
    wait = 16
    atr_period = 14
    atr_multiplier = 2.0
    box_shift_step = 2.0
    time_stop_bars = 128
    cooldown_bars = 48
    position_size = 0.5

    # Calculate ATR
    atr = ind.atr(hist, atr_period)
    entry_atr = atr[-1] if 'entry_atr' not in state else state['entry_atr']

    # Calculate 48-bar high and low
    highest_high = ind.highest(hist.high, n)
    lowest_low = ind.lowest(hist.low, n)

    # Breakout Pullback Signal
    if pos == 0:
        if 'breakout_high' not in state and hist.close[-1] > highest_high[-2]:
            state['breakout_high'] = hist.close[-1]
            state['breakout_time'] = len(hist) - 1
        elif 'breakout_low' not in state and hist.close[-1] < lowest_low[-2]:
            state['breakout_low'] = hist.close[-1]
            state['breakout_time'] = len(hist) - 1

        if 'breakout_high' in state:
            if len(hist) - 1 - state['breakout_time'] <= wait:
                if hist.low[-1] <= state['breakout_high']:
                    # Bullish signal
                    state['entry_price'] = hist.close[-1]
                    state['entry_atr'] = entry_atr
                    state['anchor'] = state['entry_price']
                    state['stop'] = state['anchor'] - atr_multiplier * state['entry_atr']
                    state['target'] = state['anchor'] + atr_multiplier * state['entry_atr']
                    state['breakout_high'] = None
                    state['breakout_time'] = None
                    state['entry_time'] = len(hist) - 1
                    state['cooldown'] = len(hist) - 1 + cooldown_bars
                    return {"target": position_size, "stop": state['stop'], "take": state['target']}
            else:
                state['breakout_high'] = None
                state['breakout_time'] = None

        if 'breakout_low' in state:
            if len(hist) - 1 - state['breakout_time'] <= wait:
                if hist.high[-1] >= state['breakout_low']:
                    # Bearish signal
                    state['entry_price'] = hist.close[-1]
                    state['entry_atr'] = entry_atr
                    state['anchor'] = state['entry_price']
                    state['stop'] = state['anchor'] + atr_multiplier * state['entry_atr']
                    state['target'] = state['anchor'] - atr_multiplier * state['entry_atr']
                    state['breakout_low'] = None
                    state['breakout_time'] = None
                    state['entry_time'] = len(hist) - 1
                    state['cooldown'] = len(hist) - 1 + cooldown_bars
                    return {"target": -position_size, "stop": state['stop'], "take": state['target']}
            else:
                state['breakout_low'] = None
                state['breakout_time'] = None

    # Exit on opposite signal
    if pos > 0:
        if hist.close[-1] < lowest_low[-2]:
            return {"target": 0, "stop": None, "take": None}
    elif pos < 0:
        if hist.close[-1] > highest_high[-2]:
            return {"target": 0, "stop": None, "take": None}

    # Trailing HWM
    if pos > 0:
        if hist.high[-1] > state['anchor']:
            state['anchor'] = hist.high[-1]
            state['stop'] = state['anchor'] - atr_multiplier * state['entry_atr']
            state['target'] = state['anchor'] + atr_multiplier * state['entry_atr']
    elif pos < 0:
        if hist.low[-1] < state['anchor']:
            state['anchor'] = hist.low[-1]
            state['stop'] = state['anchor'] + atr_multiplier * state['entry_atr']
            state['target'] = state['anchor'] - atr_multiplier * state['entry_atr']

    # Box Shift
    if pos > 0:
        while hist.close[-1] >= state['target']:
            state['anchor'] += box_shift_step * state['entry_atr']
            state['stop'] = state['anchor'] - atr_multiplier * state['entry_atr']
            state['target'] = state['anchor'] + atr_multiplier * state['entry_atr']
    elif pos < 0:
        while hist.close[-1] <= state['target']:
            state['anchor'] -= box_shift_step * state['entry_atr']
            state['stop'] = state['anchor'] + atr_multiplier * state['entry_atr']
            state['target'] = state['anchor'] - atr_multiplier * state['entry_atr']

    # Time Stop
    if 'entry_time' in state and len(hist) - 1 - state['entry_time'] >= time_stop_bars:
        return {"target": 0, "stop": None, "take": None}

    # Cooldown
    if 'cooldown' in state and len(hist) - 1 < state['cooldown']:
        return {"target": 0, "stop": None, "take": None}

    # Return current position if no new signals
    return {"target": pos, "stop": state.get('stop', None), "take": state.get('target', None)}

