        breakeven = get_breakeven(state)
        if breakeven is None:
            breakeven = False
            set_breakeven(state, breakeven)
        if is_long(pos) and not breakeven and hist.close[-1] >= entry_price + a * entry_atr:
            breakeven = True
            set_breakeven(state, breakeven)
            set_stop_level(state, entry_price)
        elif is_short(pos) and not breakeven and hist.close[-1] <= entry_price - a * entry_atr:
            breakeven = True
            set_breakeven(state, breakeven)
            set_stop_level(state, entry_price)

    # Cooldown and daily cap
    cooldown = get_cooldown(state)
    if cooldown > 0:
        set_cooldown(state, cooldown - 1)

    daily_cap = get_daily_cap(state)
    current_day = hist.time[-1] // (24 * 60 * 60 * 1000)
    if daily_cap is None or daily_cap != current_day:
        set_daily_cap(state, current_day)
        set_cooldown(state, 0)

    # Entry logic
    target = pos
    stop = None
    take = None

    if is_flat(pos) and cooldown == 0:
        if direction == "long_only" or direction == "long_short":
            if bullish_signal and htf_trend_long:
                entry_price = hist.close[-1]
                entry_atr = ind.atr(hist, 14)[-1]
                set_entry_price(state, entry_price)
                set_entry_atr(state, entry_atr)
                set_last_add_price(state, entry_price)
                set_add_count(state, 0)
                target = position_size
                stop = entry_price - 2 * entry_atr
                take = entry_price + 3 * entry_atr
        if direction == "long_short":
            if bearish_signal and htf_trend_short:
                entry_price = hist.close[-1]
                entry_atr = ind.atr(hist, 14)[-1]
                set_entry_price(state, entry_price)
                set_entry_atr(state, entry_atr)
                set_last_add_price(state, entry_price)
                set_add_count(state, 0)
                target = -position_size
                stop = entry_price + 2 * entry_atr
                take = entry_price - 3 * entry_atr

    # Exit logic
    if is_long(pos):
        if hist.low[-1] <= stop:
            target = 0.0
            reset_trade_state(state)
        elif hist.high[-1] >= take:
            target = 0.0
            reset_trade_state(state)
        else:
            last_add_price = get_last_add_price(state)
            add_count = get_add_count(state)
            if add_count < adds and hist.close[-1] >= last_add_price + 1 * entry_atr:
                set_last_add_price(state, hist.close[-1])
                set_add_count(state, add_count + 1)
                target = min(1.0, pos + position_size)

    if is_short(pos):
        if hist.high[-1] >= stop:
            target = 0.0
            reset_trade_state(state)
        elif hist.low[-1] <= take:
            target = 0.0
            reset_trade_state(state)
        else:
            last_add_price = get_last_add_price(state)
            add_count = get_add_count(state)
            if add_count < adds and hist.close[-1] <= last_add_price - 1 * entry_atr:
                set_last_add_price(state, hist.close[-1])
                set_add_count(state, add_count + 1)
                target = max(-1.0, pos - position_size)

    # Opposite signal to close position
    if is_long(pos) and bearish_signal:
        target = 0.0
        reset_trade_state(state)
    elif is_short(pos) and bullish_signal:
        target = 0.0
        reset_trade_state(state)

    # Round target to grid
    target = round_to_grid(target)

    return {"target": target, "stop": stop, "take": take}

