    box_shift_multiplier = 2.0

    # Calculate ATR
    atr = ind.atr(hist, atr_period)
    entry_atr = atr[-1] if 'entry_atr' not in state else state['entry_atr']

    # Calculate 96-bar high and low
    highest_high = ind.highest(hist.high, n)
    lowest_low = ind.lowest(hist.low, n)

    # Breakout Pullback Logic
    if 'breakout_level' not in state:
        if hist.close[-1] > highest_high[-2]:
            state['breakout_level'] = highest_high[-2]
            state['armed_since'] = len(hist) - 1
        elif hist.close[-1] < lowest_low[-2]:
            state['breakout_level'] = lowest_low[-2]
            state['armed_since'] = len(hist) - 1
    else:
        if len(hist) - 1 - state['armed_since'] > wait:
            del state['breakout_level']
            del state['armed_since']
        else:
            if pos == 0 and hist.close[-1] > highest_high[-2] and hist.close[-1] > state['breakout_level']:
                state['breakout_level'] = highest_high[-2]
                state['armed_since'] = len(hist) - 1
            elif pos == 0 and hist.close[-1] < lowest_low[-2] and hist.close[-1] < state['breakout_level']:
                state['breakout_level'] = lowest_low[-2]
                state['armed_since'] = len(hist) - 1
            elif pos == 0 and 'armed_since' in state and len(hist) - 1 - state['armed_since'] <= wait:
                if hist.low[-1] <= state['breakout_level']:
                    # Bullish signal
                    target = hist.close[-1] + box_shift_multiplier * entry_atr
                    stop = hist.close[-1] - atr_multiplier * entry_atr
                    state['entry_atr'] = entry_atr
                    state['anchor'] = hist.close[-1]
                    state['stop'] = stop
                    state['target'] = target
                    state['partial_taken'] = False
                    return {"target": 0.75, "stop": stop, "take": target}
                elif hist.high[-1] >= state['breakout_level']:
                    # Bearish signal (not used in long_only)
                    return {"target": 0.0, "stop": None, "take": None}

    # Box Shift Logic
    if pos > 0:
        if 'anchor' in state:
            if hist.close[-1] >= state['anchor'] + box_shift_multiplier * entry_atr:
                state['anchor'] = hist.close[-1]
                state['stop'] = state['anchor'] - atr_multiplier * entry_atr
                state['target'] = state['anchor'] + box_shift_multiplier * entry_atr

    # Partial Take Logic
    if pos > 0 and not state.get('partial_taken', False):
        if hist.close[-1] >= state['anchor'] + partial_take_multiplier * entry_atr:
            state['partial_taken'] = True
            return {"target": pos / 2, "stop": state['stop'], "take": state['target']}

    # Stop and Take Levels
    stop = state.get('stop', None)
    take = state.get('target', None)

    # Return current position if no new signals
    return {"target": pos, "stop": stop, "take": take}

