import math
import numpy as np

def strategy(hist, state, pos, ind) -> dict:
    # Parameters from the strategy
    signal_id = "breakout_pullback"
    signal_params = {"n": 48, "wait": 32}
    direction = "long_short"
    filter_id = "htf_trend"
    filter_params = {"minutes": 240, "n": 50}
    sizing_id = "pyramid"
    sizing_params = {"f0": 0.5, "step": 2.0, "adds": 2}
    risk_ids = ["trailing_hwm", "cooldown"]
    risk_params = [{"b": 3.0, "after_be": False}, {"n": 48}]

    # Helper functions
    def round_to_grid(value, grid=0.05):
        return round(value / grid) * grid

    def ma_cross(kind, fast, slow, close):
        if kind == 'sma':
            fast_ma = ind.sma(close, fast)
            slow_ma = ind.sma(close, slow)
        elif kind == 'ema':
            fast_ma = ind.ema(close, fast)
            slow_ma = ind.ema(close, slow)
        else:
            raise ValueError("Invalid MA type")
        return fast_ma, slow_ma

    def macd_cross(fsg, close):
        macd_line, signal_line, _ = ind.macd(close, *fsg)
        return macd_line, signal_line

    def donchian_break(n, high, low):
        highest_high = ind.highest(high, n)
        lowest_low = ind.lowest(low, n)
        return highest_high, lowest_low

    def rsi_revert(n, lo, close):
        rsi = ind.rsi(close, n)
        return rsi

    def box_breakout(m, w, high, low, atr):
        highest_high = ind.highest(high, m)
        lowest_low = ind.lowest(low, m)
        box_height = highest_high - lowest_low
        valid_box = box_height <= w * atr
        return highest_high, lowest_low, valid_box

    def breakout_pullback(n, wait, high, low):
        highest_high = ind.highest(high, n)
        lowest_low = ind.lowest(low, n)
        if 'breakout_level' not in state:
            state['breakout_level'] = None
            state['breakout_time'] = None

        if high[-1] > highest_high[-2]:
            state['breakout_level'] = highest_high[-1]
            state['breakout_time'] = len(hist) - 1

        if low[-1] <= state['breakout_level'] and state['breakout_time'] is not None and len(hist) - 1 - state['breakout_time'] <= wait:
            signal = 'bullish'
        else:
            signal = None

        if low[-1] < lowest_low[-2]:
            state['breakout_level'] = lowest_low[-1]
            state['breakout_time'] = len(hist) - 1

        if high[-1] >= state['breakout_level'] and state['breakout_time'] is not None and len(hist) - 1 - state['breakout_time'] <= wait:
            signal = 'bearish' if signal is None else signal

        return signal

    def htf_trend(minutes, n, close):
        htf_close = hist.htf(minutes).close
        htf_ema = ind.ema(htf_close, n)
        return htf_close, htf_ema

    def atr_risk(r, k, close, atr):
        position_size = r * close[-1] / (k * atr[-1])
        return max(0.05, min(1.0, position_size))

    def fixed_frac(f):
        return f

    def pyramid(f0, step, adds, close, entry_price, entry_atr, pos, state):
        if 'last_add_price' not in state:
            state['last_add_price'] = entry_price
            state['add_count'] = 0

        if pos > 0 and close[-1] >= state['last_add_price'] + step * entry_atr and state['add_count'] < adds:
            state['last_add_price'] = close[-1]
            state['add_count'] += 1
            return min(1.0, pos + f0)
        elif pos < 0 and close[-1] <= state['last_add_price'] - step * entry_atr and state['add_count'] < adds:
            state['last_add_price'] = close[-1]
            state['add_count'] += 1
            return max(-1.0, pos - f0)

        return pos

    def fixed_stop(k, entry_price, entry_atr, pos):
        if pos > 0:
            stop = entry_price - k * entry_atr
        elif pos < 0:
            stop = entry_price + k * entry_atr
        else:
            stop = None
        return stop

    def breakeven(a, entry_price, entry_atr, pos, high, low):
        if pos > 0 and high[-1] >= entry_price + a * entry_atr:
            return entry_price
        elif pos < 0 and low[-1] <= entry_price - a * entry_atr:
            return entry_price
        return None

    def trailing_hwm(b, after_be, entry_price, entry_atr, pos, high, low, state):
        if pos > 0:
            if 'hwm' not in state:
                state['hwm'] = high[-1]
            else:
                state['hwm'] = max(state['hwm'], high[-1])
            stop = state['hwm'] - b * entry_atr
        elif pos < 0:
            if 'hwm' not in state:
                state['hwm'] = low[-1]
            else:
                state['hwm'] = min(state['hwm'], low[-1])
            stop = state['hwm'] + b * entry_atr
        else:
            stop = None
            if 'hwm' in state:
                del state['hwm']

        if after_be and 'breakeven_price' in state:
            stop = max(stop, state['breakeven_price']) if pos > 0 else min(stop, state['breakeven_price'])

        return stop

    def time_stop(n, entry_time, pos):
        if pos != 0 and len(hist) - 1 - entry_time >= n:
            return 0
        return None

    def take_profit(c, entry_price, entry_atr, pos):
        if pos > 0:
            take = entry_price + c * entry_atr
        elif pos < 0:
            take = entry_price - c * entry_atr
        else:
            take = None
        return take

    def partial_take(c, entry_price, entry_atr, pos, high, low, state):
        if pos > 0 and high[-1] >= entry_price + c * entry_atr:
            if 'partial_taken' not in state:
                state['partial_taken'] = True
                return pos / 2
        elif pos < 0 and low[-1] <= entry_price - c * entry_atr:
            if 'partial_taken' not in state:
                state['partial_taken'] = True
                return pos / 2
        return pos

    def box_shift(lo, hi, step, entry_price, entry_atr, pos, high, low, state):
        if 'anchor' not in state:
            state['anchor'] = entry_price

        if pos > 0:
            if high[-1] >= state['anchor'] + hi * entry_atr:
                state['anchor'] = state['anchor'] + step * entry_atr
        elif pos < 0:
            if low[-1] <= state['anchor'] - hi * entry_atr:
                state['anchor'] = state['anchor'] - step * entry_atr

        stop = state['anchor'] - lo * entry_atr
        take = state['anchor'] + hi * entry_atr
        return stop, take

    def cooldown(n, last_trade_time, pos):
        if pos == 0 and 'last_trade_time' in state and len(hist) - 1 - state['last_trade_time'] < n:
            return True
        return False

    def daily_cap(k, last_trade_time, pos):
        if pos == 0 and 'last_trade_time' in state:
            last_trade_day = hist.time[state['last_trade_time']] // (24 * 60 * 60 * 1000)
            current_day = hist.time[-1] // (24 * 60 * 60 * 1000)
            if last_trade_day == current_day:
                return True
        return False

    # Signal
    signal = breakout_pullback(signal_params["n"], signal_params["wait"], hist.high, hist.low)

    # Filter
    htf_close, htf_ema = htf_trend(filter_params["minutes"], filter_params["n"], hist.close)
    htf_trend_condition = (htf_close[-1] > htf_ema[-1]) if signal == 'bullish' else (htf_close[-1] < htf_ema[-1])

    # Sizing
    atr = ind.atr(hist, 14)
    if sizing_id == "fixed_frac":
        position_size = fixed_frac(sizing_params["f"])
    elif sizing_id == "atr_risk":
        position_size = atr_risk(sizing_params["r"], sizing_params["k"], hist.close, atr)
    elif sizing_id == "pyramid":
        position_size = sizing_params["f0"]

    # Risk
    stop = None
    take = None

    if pos != 0:
        entry_price = state['entry_price']
        entry_atr = state['entry_atr']
        entry_time = state['entry_time']

        for risk_id, risk_param in zip(risk_ids, risk_params):
            if risk_id == "fixed_stop":
                stop = fixed_stop(risk_param["k"], entry_price, entry_atr, pos) if stop is None else min(stop, fixed_stop(risk_param["k"], entry_price, entry_atr, pos))
            elif risk_id == "breakeven":
                breakeven_price = breakeven(risk_param["a"], entry_price, entry_atr, pos, hist.high, hist.low)
                if breakeven_price is not None:
                    state['breakeven_price'] = breakeven_price
                    stop = breakeven_price if stop is None else min(stop, breakeven_price)
            elif risk_id == "trailing_hwm":
                trailing_stop = trailing_hwm(risk_param["b"], risk_param["after_be"], entry_price, entry_atr, pos, hist.high, hist.low, state)
                stop = trailing_stop if stop is None else min(stop, trailing_stop)
            elif risk_id == "time_stop":
                time_target = time_stop(risk_param["n"], entry_time, pos)
                if time_target is not None:
                    pos = time_target
            elif risk_id == "take_profit":
                take = take_profit(risk_param["c"], entry_price, entry_atr, pos) if take is None else min(take, take_profit(risk_param["c"], entry_price, entry_atr, pos))
            elif risk_id == "partial_take":
                pos = partial_take(risk_param["c"], entry_price, entry_atr, pos, hist.high, hist.low, state)
            elif risk_id == "box_shift":
                box_stop, box_take = box_shift(risk_param["lo"], risk_param["hi"], risk_param["step"], entry_price, entry_atr, pos, hist.high, hist.low, state)
                stop = box_stop if stop is None else min(stop, box_stop)
                take = box_take if take is None else min(take, box_take)
            elif risk_id == "cooldown":
                if cooldown(risk_param["n"], state['last_trade_time'], pos):
                    signal = None
            elif risk_id == "daily_cap":
                if daily_cap(risk_param["k"], state['last_trade_time'], pos):
                    signal = None

    # Entry logic
    if pos == 0 and signal is not None and htf_trend_condition:
        if (signal == 'bullish' and direction in ["long_only", "long_short"]) or (signal == 'bearish' and direction == "long_short"):
            entry_price = hist.close[-1]
            entry_atr = atr[-1]
            entry_time = len(hist) - 1
            state['entry_price'] = entry_price
            state['entry_atr'] = entry_atr
            state['entry_time'] = entry_time
            pos = position_size if signal == 'bullish' else -position_size

    # Exit logic
    if pos != 0 and signal is not None and ((signal == 'bullish' and pos < 0) or (signal == 'bearish' and pos > 0)):
        pos = 0
        if 'last_trade_time' in state:
            del state['last_trade_time']
        if 'breakout_level' in state:
            del state['breakout_level']
        if 'breakout_time' in state:
            del state['breakout_time']
        if 'breakeven_price' in state:
            del state['breakeven_price']
        if 'hwm' in state:
            del state['hwm']
        if 'anchor' in state:
            del state['anchor']
        if 'last_add_price' in state:
            del state['last_add_price']
        if 'add_count' in state:
            del state['add_count']
        if 'partial_taken' in state:
            del state['partial_taken']

    # Pyramid logic
    if pos != 0 and sizing_id == "pyramid":
        pos = pyramid(sizing_params["f0"], sizing_params["step"], sizing_params["adds"], hist.close, state['entry_price'], state['entry_atr'], pos, state)

    # Cooldown and daily cap
    if pos == 0:
        state['last_trade_time'] = len(hist) - 1

    # Return target, stop, take
    target = round_to_grid(pos)
    return {"target": target, "stop": stop, "take": take}

