        if hist.close[-1] >= last_add_price + entry_atr:
            new_pos = min(pos + PYRAMID_F0, 1.0)
            if new_pos > pos:
                state['last_add_price'] = hist.close[-1]
                target = new_pos
    elif pos < 0 and target < pos:
        last_add_price = state.get('last_add_price', hist.close[-1])
        if hist.close[-1] <= last_add_price - entry_atr:
            new_pos = max(pos - PYRAMID_F0, -1.0)
            if new_pos < pos:
                state['last_add_price'] = hist.close[-1]
                target = new_pos

    # Round target to 0.05 grid
    target = round(target / 0.05) * 0.05

    # Stop and take-profit levels
    stop = None
    take = None

