def strategy(hist, state, pos, ind) -> dict:
    # Constants
    ATR_PERIOD = 14
    DONCHIAN_PERIOD = 192
    RISK_PERCENT = 0.01
    ATR_MULTIPLE = 3.0
    MIN_POSITION = 0.05
    MAX_POSITION = 1.0
    PARTIAL_TAKE_MULTIPLE = 1.5
    TIME_STOP_BARS = 256

    # Calculate ATR
    atr = ind.atr(hist, ATR_PERIOD)
    entry_atr = atr[-1] if 'entry_atr' not in state else state['entry_atr']
    entry_price = hist.close[-1] if 'entry_price' not in state else state['entry_price']
    entry_time = hist.time[-1] if 'entry_time' not in state else state['entry_time']
    bars_since_entry = len(hist) - state['entry_bar'] if 'entry_bar' in state else 0

    # Donchian Breakout Signal
    highest_high = ind.highest(hist.high, DONCHIAN_PERIOD)
    lowest_low = ind.lowest(hist.low, DONCHIAN_PERIOD)

    bullish_signal = hist.close[-1] > highest_high[-1]
    bearish_signal = hist.close[-1] < lowest_low[-1]

    # Trend Filter (no_filter in this case)
    trend_filter = True

    # Position Sizing
    def calculate_position_size():
        position_size = RISK_PERCENT * hist.close[-1] / (ATR_MULTIPLE * entry_atr)
        return max(MIN_POSITION, min(MAX_POSITION, position_size))

    # Risk Management
    stop = None
    take = None

    if pos > 0:  # Long position
        stop = entry_price - entry_atr
        if bars_since_entry >= TIME_STOP_BARS:
            return {"target": 0.0, "stop": stop, "take": take}
        if hist.close[-1] >= entry_price + PARTIAL_TAKE_MULTIPLE * entry_atr:
            if 'partial_take' not in state:
                state['partial_take'] = True
                return {"target": pos / 2, "stop": stop, "take": take}
        take = entry_price + 2 * entry_atr

    if pos < 0:  # Short position
        stop = entry_price + entry_atr
        if bars_since_entry >= TIME_STOP_BARS:
            return {"target": 0.0, "stop": stop, "take": take}
        if hist.close[-1] <= entry_price - PARTIAL_TAKE_MULTIPLE * entry_atr:
            if 'partial_take' not in state:
                state['partial_take'] = True
                return {"target": pos / 2, "stop": stop, "take": take}
        take = entry_price - 2 * entry_atr

    # Entry Logic
    if pos == 0 and trend_filter:
        if bullish_signal:
            state['entry_price'] = hist.close[-1]
            state['entry_atr'] = atr[-1]
            state['entry_time'] = hist.time[-1]
            state['entry_bar'] = len(hist) - 1
            state['partial_take'] = False
            return {"target": calculate_position_size(), "stop": stop, "take": take}
        if bearish_signal:
            state['entry_price'] = hist.close[-1]
            state['entry_atr'] = atr[-1]
            state['entry_time'] = hist.time[-1]
            state['entry_bar'] = len(hist) - 1
            state['partial_take'] = False
            return {"target": -calculate_position_size(), "stop": stop, "take": take}

    # Exit Logic if opposite signal is received
    if pos > 0 and bearish_signal:
        return {"target": 0.0, "stop": stop, "take": take}
    if pos < 0 and bullish_signal:
        return {"target": 0.0, "stop": stop, "take": take}

    # No change
    return {"target": pos, "stop": stop, "take": take}

