def strategy(hist, state, pos, ind) -> dict:
    # Parameters from the strategy
    signal_id = "ma_cross"
    signal_params = {"kind": "sma", "fast": 20, "slow": 50}
    direction = "long_short"
    filter_id = "no_filter"
    filter_params = {}
    sizing_id = "pyramid"
    sizing_params = {"f0": 0.25, "step": 1.0, "adds": 1}
    risk_ids = ["cooldown"]
    risk_params = [{"n": 16}]

    # Indicator calculations
    if signal_id == "ma_cross":
        if signal_params["kind"] == "sma":
            fast_sma = ind.sma(hist.close, signal_params["fast"])
            slow_sma = ind.sma(hist.close, signal_params["slow"])
        elif signal_params["kind"] == "ema":
            fast_sma = ind.ema(hist.close, signal_params["fast"])
            slow_sma = ind.ema(hist.close, signal_params["slow"])

        sma_cross_up = (fast_sma[-1] > slow_sma[-1]) and (fast_sma[-2] <= slow_sma[-2])
        sma_cross_down = (fast_sma[-1] < slow_sma[-1]) and (fast_sma[-2] >= slow_sma[-2])

    # Filter logic
    if filter_id == "no_filter":
        filter_pass = True
    elif filter_id == "htf_trend":
        htf_minutes = filter_params["minutes"]
        htf_n = filter_params["n"]
        htf_close = hist.htf(htf_minutes).close
        htf_ema = ind.ema(htf_close, htf_n)
        filter_pass = (htf_close[-1] > htf_ema[-1]) if direction == "long_only" else (htf_close[-1] < htf_ema[-1])

    # Sizing logic
    if sizing_id == "fixed_frac":
        target_size = sizing_params["f"]
    elif sizing_id == "atr_risk":
        atr_14 = ind.atr(hist, 14)[-1]
        target_size = sizing_params["r"] * hist.close[-1] / (sizing_params["k"] * atr_14)
        target_size = max(0.05, min(1.0, target_size))
    elif sizing_id == "pyramid":
        if "entry_price" not in state:
            state["entry_price"] = hist.close[-1]
            state["entry_atr"] = ind.atr(hist, 14)[-1]
            state["add_count"] = 0
            state["last_add_price"] = state["entry_price"]
        target_size = sizing_params["f0"] + sizing_params["step"] * state["add_count"]
        if (pos > 0 and hist.close[-1] >= state["last_add_price"] + sizing_params["step"] * state["entry_atr"]) or \
           (pos < 0 and hist.close[-1] <= state["last_add_price"] - sizing_params["step"] * state["entry_atr"]):
            if state["add_count"] < sizing_params["adds"]:
                state["add_count"] += 1
                state["last_add_price"] = hist.close[-1]
                target_size = sizing_params["f0"] + sizing_params["step"] * state["add_count"]
        target_size = max(0.05, min(1.0, target_size))

    # Risk management logic
    stop = None
    take = None
    for risk_id, risk_param in zip(risk_ids, risk_params):
        if risk_id == "fixed_stop":
            if pos > 0:
                stop = state["entry_price"] - risk_param["k"] * state["entry_atr"]
            elif pos < 0:
                stop = state["entry_price"] + risk_param["k"] * state["entry_atr"]
        elif risk_id == "breakeven":
            if pos > 0 and hist.close[-1] >= state["entry_price"] + risk_param["a"] * state["entry_atr"]:
                stop = state["entry_price"]
            elif pos < 0 and hist.close[-1] <= state["entry_price"] - risk_param["a"] * state["entry_atr"]:
                stop = state["entry_price"]
        elif risk_id == "trailing_hwm":
            if pos > 0:
                state["hwm"] = max(state.get("hwm", -math.inf), hist.high[-1])
                stop = state["hwm"] - risk_param["b"] * state["entry_atr"]
                if risk_param["after_be"] and hist.close[-1] >= state["entry_price"] + risk_param["b"] * state["entry_atr"]:
                    stop = state["entry_price"]
            elif pos < 0:
                state["hwm"] = min(state.get("hwm", math.inf), hist.low[-1])
                stop = state["hwm"] + risk_param["b"] * state["entry_atr"]
                if risk_param["after_be"] and hist.close[-1] <= state["entry_price"] - risk_param["b"] * state["entry_atr"]:
                    stop = state["entry_price"]
        elif risk_id == "time_stop":
            if "entry_bar" not in state:
                state["entry_bar"] = len(hist) - 1
            if len(hist) - state["entry_bar"] >= risk_param["n"]:
                target_size = 0.0
        elif risk_id == "take_profit":
            if pos > 0:
                take = state["entry_price"] + risk_param["c"] * state["entry_atr"]
            elif pos < 0:
                take = state["entry_price"] - risk_param["c"] * state["entry_atr"]
        elif risk_id == "partial_take":
            if pos > 0 and hist.close[-1] >= state["entry_price"] + risk_param["c"] * state["entry_atr"]:
                target_size /= 2
            elif pos < 0 and hist.close[-1] <= state["entry_price"] - risk_param["c"] * state["entry_atr"]:
                target_size /= 2
        elif risk_id == "box_shift":
            if "anchor" not in state:
                state["anchor"] = state["entry_price"]
            if pos > 0 and hist.close[-1] >= state["anchor"] + risk_param["step"] * state["entry_atr"]:
                state["anchor"] = state["anchor"] + risk_param["step"] * state["entry_atr"]
            elif pos < 0 and hist.close[-1] <= state["anchor"] - risk_param["step"] * state["entry_atr"]:
                state["anchor"] = state["anchor"] - risk_param["step"] * state["entry_atr"]
            stop = state["anchor"] - risk_param["lo"] * state["entry_atr"]
            take = state["anchor"] + risk_param["hi"] * state["entry_atr"]
        elif risk_id == "cooldown":
            if "exit_bar" in state and len(hist) - state["exit_bar"] < risk_param["n"]:
                target_size = pos  # Maintain current position
            elif "exit_bar" in state and len(hist) - state["exit_bar"] >= risk_param["n"]:
                del state["exit_bar"]

    # Entry logic
    if pos == 0 and filter_pass:
        if sma_cross_up:
            target_size = target_size
        elif sma_cross_down:
            target_size = -target_size

    # Exit logic
    if pos > 0 and sma_cross_down:
        target_size = 0.0
    elif pos < 0 and sma_cross_up:
        target_size = 0.0

    # Round target to 0.05 grid
    target_size = round(target_size / 0.05) * 0.05

    # Update state for exit bar
    if pos != 0 and target_size == 0.0:
        state["exit_bar"] = len(hist) - 1

    return {"target": target_size, "stop": stop, "take": take}

