        box_high = ind.highest(hist.high, m)[:-1]
        box_low = ind.lowest(hist.low, m)[:-1]
        box_height = box_high - box_low
        box_valid = box_height <= w * entry_atr
        box_breakout_long = hist.close[-1] > box_high[-1] & box_valid[-1]
        box_breakout_short = hist.close[-1] < box_low[-1] & box_valid[-1]

    # Filter calculation
    if filter_id == "htf_trend":
        htf = hist.htf(filter_params["minutes"])
        htf_ema = ind.ema(htf.close, filter_params["n"])
        htf_trend_long = htf.close[-1] > htf_ema[-1]
        htf_trend_short = htf.close[-1] < htf_ema[-1]

