                lo = risk_params[risk_ids.index("box_shift")]["lo"]
                hi = risk_params[risk_ids.index("box_shift")]["hi"]
                step = risk_params[risk_ids.index("box_shift")]["step"]
                if box_anchor is None:
                    set_box_anchor(state, entry_price)
                    set_box_stop(state, entry_price - lo * entry_atr if pos > 0 else entry_price + lo * entry_atr)
                    set_box_target(state, entry_price + hi * entry_atr if pos > 0 else entry_price - hi * entry_atr)
                else:
                    if pos > 0 and hist.close[-1] >= box_target:
                        new_anchor = box_target
                        set_box_anchor(state, new_anchor)
                        set_box_stop(state, new_anchor - lo * entry_atr)
                        set_box_target(state, new_anchor + hi * entry_atr)
                    elif pos < 0 and hist.close[-1] <= box_target:
                        new_anchor = box_target
                        set_box_anchor(state, new_anchor)
                        set_box_stop(state, new_anchor + lo * entry_atr)
                        set_box_target(state, new_anchor - hi * entry_atr)
                box_stop = get_box_stop(state)
                box_target = get_box_target(state)

            if "breakeven" in risk_ids:
