                if pos > 0:
                    if after_be and breakeven:
                        stop = max(stop, hist.low[-1] + b * entry_atr) if stop is not None else hist.low[-1] + b * entry_atr
                    else:
                        stop = max(stop, hist.high[-1] - b * entry_atr) if stop is not None else hist.high[-1] - b * entry_atr
                elif pos < 0:
                    if after_be and breakeven:
                        stop = min(stop, hist.high[-1] - b * entry_atr) if stop is not None else hist.high[-1] - b * entry_atr
                    else:
                        stop = min(stop, hist.low[-1] + b * entry_atr) if stop is not None else hist.low[-1] + b * entry_atr

            if "time_stop" in risk_ids:
                n = risk_params[risk_ids.index("time_stop")]["n"]
                if "bars_since_signal" not in state:
                    state["bars_since_signal"] = 0
                else:
                    state["bars_since_signal"] += 1
                if state["bars_since_signal"] >= n:
                    target = 0

            if "partial_take" in risk_ids:
                c = risk_params[risk_ids.index("partial_take")]["c"]
                if pos > 0 and hist.close[-1] >= entry_price + c * entry_atr:
                    target = round_to_grid(pos / 2)
                elif pos < 0 and hist.close[-1] <= entry_price - c * entry_atr:
                    target = round_to_grid(pos / 2)

            if "cooldown" in risk_ids:
                n = risk_params[risk_ids.index("cooldown")]["n"]
                if pos == 0:
                    set_cooldown(state, n)
                elif get_cooldown(state) > 0:
                    set_cooldown(state, get_cooldown(state) - 1)
                    target = pos

            if "daily_cap" in risk_ids:
                k = risk_params[risk_ids.index("daily_cap")]["k"]
                current_time = hist.time[-1]
                current_day = current_time // (24 * 60 * 60 * 1000)
                if get_daily_cap(state) != current_day:
                    set_daily_cap(state, current_day)
                    set_cooldown(state, 0)
                elif get_cooldown(state) > 0:
                    target = pos

    # Entry logic
    if pos == 0:
        if box_breakout_long and htf_trend_long:
            set_entry_price(state, hist.close[-1])
            set_entry_atr(state, entry_atr)
            set_add_price(state, None)
            set_add_count(state, 0)
            set_box_anchor(state, None)
            set_box_stop(state, None)
            set_box_target(state, None)
            set_breakeven(state, False)
            set_cooldown(state, 0)
            target = round_to_grid(f0)
        elif box_breakout_short and htf_trend_short:
            set_entry_price(state, hist.close[-1])
            set_entry_atr(state, entry_atr)
            set_add_price(state, None)
            set_add_count(state, 0)
            set_box_anchor(state, None)
            set_box_stop(state, None)
            set_box_target(state, None)
            set_breakeven(state, False)
            set_cooldown(state, 0)
            target = round_to_grid(-f0)
        else:
            target = 0
    else:
        if (box_breakout_long and htf_trend_long) or (box_breakout_short and htf_trend_short):
            target = 0

    return {"target": target, "stop": stop, "take": take}

