    filter_params = {}
    sizing_id = "pyramid"
    sizing_params = {"f0": 0.5, "step": 1.0, "adds": 2}
    risk_ids = ["time_stop"]
    risk_params = [{"n": 256}]

    # Indicator calculations
    if signal_id == "ma_cross":
        if signal_params["kind"] == "sma":
            fast_sma = ind.sma(hist.close, signal_params["fast"])
            slow_sma = ind.sma(hist.close, signal_params["slow"])
        elif signal_params["kind"] == "ema":
            fast_sma = ind.ema(hist.close, signal_params["fast"])
            slow_sma = ind.ema(hist.close, signal_params["slow"])

    # Filter logic
    if filter_id == "no_filter":
        filter_condition = True
    elif filter_id == "htf_trend":
        htf_minutes = filter_params["minutes"]
        htf_n = filter_params["n"]
        htf_close = hist.htf(htf_minutes).close
        htf_ema = ind.ema(htf_close, htf_n)
        filter_condition = (hist.close[-1] > htf_ema[-1]) if direction == "long_only" else (hist.close[-1] < htf_ema[-1])

    # Signal logic
    if signal_id == "ma_cross":
        if filter_condition:
            if fast_sma[-2] <= slow_sma[-2] and fast_sma[-1] > slow_sma[-1]:  # Bullish crossover
                signal = "long"
            elif fast_sma[-2] >= slow_sma[-2] and fast_sma[-1] < slow_sma[-1]:  # Bearish crossover
                signal = "short"
            else:
                signal = None
        else:
            signal = None

    # Sizing logic
    if sizing_id == "pyramid":
        f0 = sizing_params["f0"]
        step = sizing_params["step"]
        adds = sizing_params["adds"]
        if "entry_price" not in state:
            state["entry_price"] = hist.close[-1]
            state["entry_atr"] = ind.atr(hist, 14)[-1]
            state["last_add_price"] = state["entry_price"]
            state["add_count"] = 0
        if pos == 0 and signal == "long":
            target = f0
        elif pos > 0 and signal is None:
            atr = ind.atr(hist, 14)[-1]
            if hist.close[-1] >= state["last_add_price"] + step * atr and state["add_count"] < adds:
                state["last_add_price"] = hist.close[-1]
                state["add_count"] += 1
                target = min(1.0, pos + f0)
            else:
                target = pos
        else:
            target = 0
    elif sizing_id == "fixed_frac":
        f = sizing_params["f"]
        if pos == 0 and signal == "long":
            target = f
        else:
            target = 0
    elif sizing_id == "atr_risk":
        r = sizing_params["r"]
        k = sizing_params["k"]
        atr = ind.atr(hist, 14)[-1]
        target = min(1.0, max(0.05, r * hist.close[-1] / (k * atr)))
        if pos == 0 and signal == "long":
            target = target
        else:
            target = 0

    # Risk management logic
    stop = None
    take = None
    if "signal_bar" not in state and pos > 0:
        state["signal_bar"] = len(hist) - 1

    for risk_id, risk_param in zip(risk_ids, risk_params):
        if risk_id == "fixed_stop":
            k = risk_param["k"]
            if pos > 0:
                stop = state["entry_price"] - k * state["entry_atr"]
        elif risk_id == "breakeven":
            a = risk_param["a"]
            if pos > 0 and hist.close[-1] >= state["entry_price"] + a * state["entry_atr"]:
                stop = state["entry_price"]
        elif risk_id == "trailing_hwm":
            b = risk_param["b"]
            after_be = risk_param["after_be"]
            if pos > 0:
                if "hwm" not in state:
                    state["hwm"] = state["entry_price"]
                if after_be and stop == state["entry_price"]:
                    state["hwm"] = max(state["hwm"], hist.high[-1])
                else:
                    state["hwm"] = max(state["hwm"], hist.high[-1])
                stop = state["hwm"] - b * state["entry_atr"]
        elif risk_id == "time_stop":
            n = risk_param["n"]
            if pos > 0 and len(hist) - 1 - state["signal_bar"] >= n:
                target = 0
        elif risk_id == "take_profit":
            c = risk_param["c"]
            if pos > 0:
                take = state["entry_price"] + c * state["entry_atr"]
        elif risk_id == "partial_take":
            c = risk_param["c"]
            if pos > 0 and hist.close[-1] >= state["entry_price"] + c * state["entry_atr"]:
                if "partial_taken" not in state:
                    state["partial_taken"] = True
                    target = pos / 2
        elif risk_id == "box_shift":
            lo = risk_param["lo"]
            hi = risk_param["hi"]
            step = risk_param["step"]
            if pos > 0:
                if "anchor" not in state:
                    state["anchor"] = state["entry_price"]
                if hist.close[-1] >= state["anchor"] + step * state["entry_atr"]:
                    state["anchor"] = state["anchor"] + step * state["entry_atr"]
                stop = state["anchor"] - lo * state["entry_atr"]
                take = state["anchor"] + hi * state["entry_atr"]
        elif risk_id == "cooldown":
            n = risk_param["n"]
            if pos == 0 and "last_exit_bar" in state and len(hist) - 1 - state["last_exit_bar"] < n:
                target = 0
        elif risk_id == "daily_cap":
            k = risk_param["k"]
            if pos == 0 and "last_entry_time" in state:
                current_time = hist.time[-1] // (24 * 60 * 60 * 1000)
                last_entry_time = state["last_entry_time"] // (24 * 60 * 60 * 1000)
                if current_time == last_entry_time:
                    target = 0
            if pos > 0:
                state["last_entry_time"] = hist.time[-1]

    # Ensure target is on the 0.05 grid
    target = round(target / 0.05) * 0.05

    # Update state for exits
    if target == 0 and pos != 0:
        state["last_exit_bar"] = len(hist) - 1
        del state["entry_price"]
        del state["entry_atr"]
        del state["last_add_price"]
        del state["add_count"]
        del state["signal_bar"]
        if "hwm" in state:
            del state["hwm"]
        if "anchor" in state:
            del state["anchor"]
        if "partial_taken" in state:
            del state["partial_taken"]

    return {"target": target, "stop": stop, "take": take}

