    high_64 = ind.highest(hist.high, m)
    low_64 = ind.lowest(hist.low, m)
    box_height = high_64[-1] - low_64[-1]

    # Check if the box is valid
    is_valid_box = box_height <= w * entry_atr

    # Determine entry signals
    long_signal = hist.close[-1] > high_64[-1] if is_valid_box else False
    short_signal = hist.close[-1] < low_64[-1] if is_valid_box else False

    # Determine if we are in a position
    in_position = pos != 0.0

    # Determine if we need to close the position due to an opposite signal
    if (pos > 0 and short_signal) or (pos < 0 and long_signal):
        return {"target": 0.0, "stop": None, "take": None}

    # Determine if we need to enter a new position
    if not in_position:
        if long_signal:
            state['entry_price'] = hist.close[-1]
            state['entry_atr'] = entry_atr
            state['last_add_price'] = hist.close[-1]
            state['adds_count'] = 0
            state['best_price'] = hist.high[-1]
            state['bars_since_entry'] = 0
            return {"target": f0, "stop": state['entry_price'] - b * entry_atr, "take": None}
        elif short_signal:
            state['entry_price'] = hist.close[-1]
            state['entry_atr'] = entry_atr
            state['last_add_price'] = hist.close[-1]
            state['adds_count'] = 0
            state['best_price'] = hist.low[-1]
            state['bars_since_entry'] = 0
            return {"target": -f0, "stop": state['entry_price'] + b * entry_atr, "take": None}

    # Update state for existing position
    if in_position:
        state['bars_since_entry'] += 1
        if pos > 0:
            state['best_price'] = max(state['best_price'], hist.high[-1])
            stop_price = state['best_price'] - b * entry_atr
            if state['bars_since_entry'] >= n:
                return {"target": 0.0, "stop": None, "take": None}
            if hist.close[-1] >= state['last_add_price'] + step * entry_atr and state['adds_count'] < adds:
                state['last_add_price'] = hist.close[-1]
                state['adds_count'] += 1
                return {"target": min(pos + f0, 1.0), "stop": stop_price, "take": None}
            return {"target": pos, "stop": stop_price, "take": None}
        elif pos < 0:
            state['best_price'] = min(state['best_price'], hist.low[-1])
            stop_price = state['best_price'] + b * entry_atr
            if state['bars_since_entry'] >= n:
                return {"target": 0.0, "stop": None, "take": None}
            if hist.close[-1] <= state['last_add_price'] - step * entry_atr and state['adds_count'] < adds:
                state['last_add_price'] = hist.close[-1]
                state['adds_count'] += 1
                return {"target": max(pos - f0, -1.0), "stop": stop_price, "take": None}
            return {"target": pos, "stop": stop_price, "take": None}

    return {"target": pos, "stop": None, "take": None}

