    rsi_period = 21
    rsi_oversold_level = 25
    rsi_overbought_level = 75
    position_size = 0.25
    time_stop_bars = 256

    # Calculate RSI
    rsi = ind.rsi(hist.close, rsi_period)

    # Determine if we are in a cooldown period
    if 'last_exit_bar' in state:
        if len(hist) - state['last_exit_bar'] < 4:
            return {"target": pos, "stop": None, "take": None}

    # Check for entry signal (RSI crosses above 25)
    if pos == 0.0:
        if rsi[-1] > rsi_oversold_level and rsi[-2] <= rsi_oversold_level:
            # Enter long position
            target = position_size
            state['entry_price'] = hist.close[-1]
            state['entry_atr'] = ind.atr(hist, 14)[-1]
            state['entry_bar'] = len(hist) - 1
            return {"target": target, "stop": None, "take": None}

    # Check for exit signal (RSI crosses below 75)
    if pos > 0.0:
        if rsi[-1] < rsi_overbought_level and rsi[-2] >= rsi_overbought_level:
            # Exit long position
            target = 0.0
            state['last_exit_bar'] = len(hist) - 1
            return {"target": target, "stop": None, "take": None}

    # Check for time stop
    if pos > 0.0:
        if len(hist) - state['entry_bar'] >= time_stop_bars:
            # Exit long position due to time stop
            target = 0.0
            state['last_exit_bar'] = len(hist) - 1
            return {"target": target, "stop": None, "take": None}

