def strategy(hist, state, pos, ind) -> dict:
    # Parameters from the strategy
    rsi_n = 14
    rsi_lo = 30
    htf_minutes = 60
    htf_n = 50
    f0 = 0.25
    step = 2.0
    adds = 2
    trailing_b = 4.0
    time_stop_n = 64
    cooldown_n = 4

    # Calculate indicators
    rsi = ind.rsi(hist.close, rsi_n)
    htf_close = hist.htf(htf_minutes).close
    htf_ema = ind.ema(htf_close, htf_n)
    atr = ind.atr(hist, 14)

    # Current bar index
    t = len(hist) - 1

    # Calculate entry ATR
    entry_atr = atr[t] if 'entry_atr' not in state else state['entry_atr']

    # Check for cooldown
    if 'cooldown_until' in state and t < state['cooldown_until']:
        return {"target": pos, "stop": None, "take": None}

    # Check for time stop
    if 'entry_bar' in state and t - state['entry_bar'] >= time_stop_n:
        return {"target": 0, "stop": None, "take": None}

    # Check for trailing stop
    if pos > 0:
        if 'highest_high' not in state:
            state['highest_high'] = hist.high[t]
        else:
            state['highest_high'] = max(state['highest_high'], hist.high[t])
        stop = state['highest_high'] - trailing_b * entry_atr
    elif pos < 0:
        if 'lowest_low' not in state:
            state['lowest_low'] = hist.low[t]
        else:
            state['lowest_low'] = min(state['lowest_low'], hist.low[t])
        stop = state['lowest_low'] + trailing_b * entry_atr
    else:
        stop = None

    # Check for RSI crossover signal
    if rsi[t] is not None and rsi[t - 1] is not None:
        if rsi[t - 1] < rsi_lo and rsi[t] >= rsi_lo:
            # Bullish signal
            if htf_close[t] > htf_ema[t] and pos <= 0:
                # Long entry conditions met
                state['entry_atr'] = atr[t]
                state['entry_bar'] = t
                state['highest_high'] = hist.high[t]
                state['lowest_low'] = None
                state['adds'] = 0
                return {"target": round_to_grid(f0), "stop": stop, "take": None}
        elif rsi[t - 1] > 100 - rsi_lo and rsi[t] <= 100 - rsi_lo:
            # Bearish signal
            if htf_close[t] < htf_ema[t] and pos >= 0:
                # Short entry conditions met
                state['entry_atr'] = atr[t]
                state['entry_bar'] = t
                state['highest_high'] = None
                state['lowest_low'] = hist.low[t]
                state['adds'] = 0
                return {"target": round_to_grid(-f0), "stop": stop, "take": None}

    # Check for pyramid adds
    if pos > 0 and 'last_add_price' in state:
        if hist.close[t] >= state['last_add_price'] + step * entry_atr and state['adds'] < adds:
            state['adds'] += 1
            state['last_add_price'] = hist.close[t]
            return {"target": round_to_grid(pos + f0), "stop": stop, "take": None}
    elif pos < 0 and 'last_add_price' in state:
        if hist.close[t] <= state['last_add_price'] - step * entry_atr and state['adds'] < adds:
            state['adds'] += 1
            state['last_add_price'] = hist.close[t]
            return {"target": round_to_grid(pos - f0), "stop": stop, "take": None}

    # Update last add price if just entered
    if 'entry_bar' in state and t == state['entry_bar'] + 1:
        state['last_add_price'] = hist.open[t]

    # Return current position if no signals
    return {"target": pos, "stop": stop, "take": None}

def round_to_grid(x):
    return round(x / 0.05) * 0.05

