    atr_14 = ind.atr(hist, 14)

    # Signal calculation
    if signal_id == "ma_cross":
        if signal_params["kind"] == "ema":
            fast_line = ema_fast
            slow_line = ema_slow
        elif signal_params["kind"] == "sma":
            fast_line = ind.sma(hist.close, signal_params["fast"])
            slow_line = ind.sma(hist.close, signal_params["slow"])
        else:
            raise ValueError("Invalid MA kind")

        bullish_signal = (fast_line[-1] > slow_line[-1]) and (fast_line[-2] <= slow_line[-2])
        bearish_signal = (fast_line[-1] < slow_line[-1]) and (fast_line[-2] >= slow_line[-2])

    # Filter calculation
    if filter_id == "no_filter":
        filter_pass = True
    elif filter_id == "htf_trend":
        htf_minutes = filter_params["minutes"]
        htf_n = filter_params["n"]
        htf_close = hist.htf(htf_minutes).close
        htf_ema = ind.ema(htf_close, htf_n)
        filter_pass = (pos <= 0 and hist.close[-1] > htf_ema[-1]) or (pos >= 0 and hist.close[-1] < htf_ema[-1])
    else:
        raise ValueError("Invalid filter")

    # Sizing calculation
    if sizing_id == "fixed_frac":
        target_frac = sizing_params["f"]
