                    target_frac /= 2
                elif pos < 0 and hist.close[-1] <= state["entry_price"] - c * atr_14[-1]:
                    target_frac /= 2
            elif risk_id == "box_shift":
                lo = risk_param["lo"]
                hi = risk_param["hi"]
                step = risk_param["step"]
                if "anchor" not in state:
                    state["anchor"] = state["entry_price"]
                if pos > 0:
                    if hist.close[-1] >= state["anchor"] + step * atr_14[-1]:
                        state["anchor"] = state["anchor"] + step * atr_14[-1]
                    stop = state["anchor"] - lo * atr_14[-1]
                    take = state["anchor"] + hi * atr_14[-1]
                elif pos < 0:
                    if hist.close[-1] <= state["anchor"] - step * atr_14[-1]:
                        state["anchor"] = state["anchor"] - step * atr_14[-1]
                    stop = state["anchor"] + lo * atr_14[-1]
                    take = state["anchor"] - hi * atr_14[-1]
            elif risk_id == "cooldown":
                n = risk_param["n"]
                if "exit_bar" not in state:
                    state["exit_bar"] = len(hist) - 1
                if len(hist) - state["exit_bar"] < n:
                    target_frac = 0
            elif risk_id == "daily_cap":
                k = risk_param["k"]
                current_day = hist.time[-1] // (24 * 60 * 60 * 1000)
                if "last_entry_day" not in state or state["last_entry_day"] < current_day:
                    state["last_entry_day"] = current_day
                    state["daily_entries"] = 1
                else:
                    if state["daily_entries"] >= k:
                        target_frac = 0
                    else:
                        state["daily_entries"] += 1
            else:
                raise ValueError("Invalid risk")

    # Determine target position
    if pos == 0:
        if filter_pass:
            if bullish_signal and (direction == "long_only" or direction == "long_short"):
                target_frac = round(target_frac / 0.05) * 0.05
                state["entry_price"] = hist.close[-1]
                del state.get("hwm", None)
                del state.get("anchor", None)
                del state.get("last_add_price", None)
                del state.get("add_count", None)
                del state.get("entry_bar", None)
                del state.get("exit_bar", None)
            elif bearish_signal and direction == "long_short":
                target_frac = -round(abs(target_frac) / 0.05) * 0.05
                state["entry_price"] = hist.close[-1]
                del state.get("hwm", None)
                del state.get("anchor", None)
                del state.get("last_add_price", None)
                del state.get("add_count", None)
                del state.get("entry_bar", None)
                del state.get("exit_bar", None)
        else:
            target_frac = 0
    else:
        if (bullish_signal and pos < 0) or (bearish_signal and pos > 0):
            target_frac = 0
            state["exit_bar"] = len(hist) - 1
            del state.get("hwm", None)
            del state.get("anchor", None)
            del state.get("last_add_price", None)
            del state.get("add_count", None)
            del state.get("entry_bar", None)

    return {"target": target_frac, "stop": stop, "take": take}

