    if hist.close[-1] > donchian_high[-2]:
        state['breakout_level'] = donchian_high[-2]
        state['breakout_time'] = len(hist) - 1

    if hist.close[-1] < donchian_low[-2]:
        state['breakout_level'] = donchian_low[-2]
        state['breakout_time'] = len(hist) - 1

    # Check if the setup is armed
    if state['breakout_level'] is not None:
        if len(hist) - state['breakout_time'] <= wait:
            if pos == 0:
                if state['breakout_level'] == donchian_high[-2] and hist.low[-1] <= state['breakout_level']:
                    # Bullish signal
                    target = min(max(r * hist.close[-1] / (k * entry_atr), 0.05), 1.0)
                    stop = hist.close[-1] - stop_k * entry_atr
                    take = hist.close[-1] + take_c * entry_atr
                    return {"target": target, "stop": stop, "take": take}
                elif state['breakout_level'] == donchian_low[-2] and hist.high[-1] >= state['breakout_level']:
                    # Bearish signal
                    target = -min(max(r * hist.close[-1] / (k * entry_atr), 0.05), 1.0)
                    stop = hist.close[-1] + stop_k * entry_atr
                    take = hist.close[-1] - take_c * entry_atr
                    return {"target": target, "stop": stop, "take": take}
        else:
            # Expire the setup
            state['breakout_level'] = None
            state['breakout_time'] = None

    # Close position on opposite signal
    if pos > 0 and hist.close[-1] < donchian_low[-2]:
        return {"target": 0, "stop": None, "take": None}
    if pos < 0 and hist.close[-1] > donchian_high[-2]:
        return {"target": 0, "stop": None, "take": None}

    # Scale out logic
    if pos > 0 and 'scaled_out' not in state and hist.close[-1] >= hist.close[state['entry_bar']] + take_c * entry_atr:
