import numpy as np

def strategy(hist, state, pos, ind) -> dict:
    # Constants
    ATR_PERIOD = 14
    BREAKOUT_WINDOW = 96
    ARM_WAIT = 8
    RISK_PERCENT = 0.01
    ATR_MULT = 2.0
    STOP_MULT = 2.0
    TAKE_MULT = 2.0
    STEP_MULT = 1.0
    PARTIAL_TAKE_MULT = 2.0
    COOLDOWN_BARS = 4

    # Calculate ATR
    atr = ind.atr(hist, ATR_PERIOD)
    entry_atr = atr[-1] if 'entry_atr' not in state else state['entry_atr']

    # Calculate Donchian breakout levels
    highest_high = ind.highest(hist.high, BREAKOUT_WINDOW)
    lowest_low = ind.lowest(hist.low, BREAKOUT_WINDOW)

    # Breakout pullback logic
    if 'breakout_level' not in state:
        if hist.close[-1] > highest_high[-2]:
            state['breakout_level'] = highest_high[-2]
            state['arm_time'] = len(hist) - 1
        elif hist.close[-1] < lowest_low[-2]:
            state['breakout_level'] = lowest_low[-2]
            state['arm_time'] = len(hist) - 1
    else:
        if len(hist) - 1 - state['arm_time'] > ARM_WAIT:
            del state['breakout_level']
            del state['arm_time']
        else:
            if pos == 0:
                if hist.close[-1] > state['breakout_level'] and hist.low[-1] <= state['breakout_level']:
                    target = min(1.0, max(0.05, RISK_PERCENT * hist.close[-1] / (ATR_MULT * entry_atr)))
                    state['entry_price'] = hist.close[-1]
                    state['entry_atr'] = entry_atr
                    state['anchor'] = state['entry_price']
                    state['stop'] = state['entry_price'] - STOP_MULT * entry_atr
                    state['take'] = state['entry_price'] + TAKE_MULT * entry_atr
                    state['partial_taken'] = False
                    state['last_add_price'] = state['entry_price']
                    state['last_add_bar'] = len(hist) - 1
                    state['cooldown_until'] = len(hist) - 1 + COOLDOWN_BARS
                    return {"target": target, "stop": state['stop'], "take": state['take']}
                elif hist.close[-1] < state['breakout_level'] and hist.high[-1] >= state['breakout_level']:
                    target = -min(1.0, max(0.05, RISK_PERCENT * hist.close[-1] / (ATR_MULT * entry_atr)))
                    state['entry_price'] = hist.close[-1]
                    state['entry_atr'] = entry_atr
                    state['anchor'] = state['entry_price']
                    state['stop'] = state['entry_price'] + STOP_MULT * entry_atr
                    state['take'] = state['entry_price'] - TAKE_MULT * entry_atr
                    state['partial_taken'] = False
                    state['last_add_price'] = state['entry_price']
                    state['last_add_bar'] = len(hist) - 1
                    state['cooldown_until'] = len(hist) - 1 + COOLDOWN_BARS
                    return {"target": target, "stop": state['stop'], "take": state['take']}

    # Box shift logic
    if pos != 0:
        if pos > 0:
            if hist.high[-1] >= state['anchor'] + STEP_MULT * entry_atr:
                state['anchor'] = state['anchor'] + STEP_MULT * entry_atr
                state['stop'] = state['anchor'] - STOP_MULT * entry_atr
                state['take'] = state['anchor'] + TAKE_MULT * entry_atr
        else:
            if hist.low[-1] <= state['anchor'] - STEP_MULT * entry_atr:
                state['anchor'] = state['anchor'] - STEP_MULT * entry_atr
                state['stop'] = state['anchor'] + STOP_MULT * entry_atr
                state['take'] = state['anchor'] - TAKE_MULT * entry_atr

    # Partial take logic
    if pos != 0 and not state['partial_taken']:
        if pos > 0 and hist.close[-1] >= state['entry_price'] + PARTIAL_TAKE_MULT * entry_atr:
            state['partial_taken'] = True
            return {"target": pos / 2, "stop": state['stop'], "take": state['take']}
        elif pos < 0 and hist.close[-1] <= state['entry_price'] - PARTIAL_TAKE_MULT * entry_atr:
            state['partial_taken'] = True
            return {"target": pos / 2, "stop": state['stop'], "take": state['take']}

    # Cooldown logic
    if 'cooldown_until' in state and len(hist) - 1 < state['cooldown_until']:
        return {"target": 0, "stop": None, "take": None}

    # Return current position if no new signals
    return {"target": pos, "stop": state.get('stop', None), "take": state.get('take', None)}

