        htf_n = filter_params["n"]
        htf_close = hist.htf(htf_minutes).close
        htf_ema = ind.ema(htf_close, htf_n)
        filter_pass = (htf_close[-1] > htf_ema[-1]) if direction == "long_only" else (htf_close[-1] < htf_ema[-1])

    # Sizing logic
    if sizing_id == "fixed_frac":
        target_size = sizing_params["f"]
    elif sizing_id == "atr_risk":
        atr_14 = ind.atr(hist, 14)
        entry_atr = atr_14[-1]
        target_size = sizing_params["r"] * hist.close[-1] / (sizing_params["k"] * entry_atr)
        target_size = max(0.05, min(1.0, target_size))
    elif sizing_id == "pyramid":
        f0 = sizing_params["f0"]
        step = sizing_params["step"]
        adds = sizing_params["adds"]
        if "entry_price" not in state:
            state["entry_price"] = hist.close[-1]
            state["last_add_price"] = hist.close[-1]
            state["add_count"] = 0
        entry_price = state["entry_price"]
        last_add_price = state["last_add_price"]
        add_count = state["add_count"]
        if add_count < adds and hist.close[-1] >= last_add_price + step * entry_atr:
            state["last_add_price"] = hist.close[-1]
            state["add_count"] += 1
            target_size = f0 + add_count * f0
        else:
            target_size = f0 + add_count * f0

    # Risk management logic
    stop = None
    take = None

    if "entry_price" in state:
        entry_price = state["entry_price"]
        entry_atr = state["entry_atr"]
        if risk_ids[0] == "cooldown":
            if "last_exit_bar" in state:
                if len(hist) - state["last_exit_bar"] <= risk_params[0]["n"]:
                    return {"target": pos, "stop": stop, "take": take}
        if risk_ids[1] == "breakeven":
            if "breakeven_triggered" not in state:
                if pos > 0 and hist.close[-1] >= entry_price + risk_params[1]["a"] * entry_atr:
                    state["breakeven_triggered"] = True
                    stop = entry_price
                elif pos < 0 and hist.close[-1] <= entry_price - risk_params[1]["a"] * entry_atr:
                    state["breakeven_triggered"] = True
                    stop = entry_price
        if risk_ids[2] == "trailing_hwm":
            if "breakeven_triggered" in state and state["breakeven_triggered"]:
                if pos > 0:
                    if "highest_high" not in state:
                        state["highest_high"] = entry_price
                    state["highest_high"] = max(state["highest_high"], hist.high[-1])
                    stop = state["highest_high"] - risk_params[2]["b"] * entry_atr
                elif pos < 0:
                    if "lowest_low" not in state:
                        state["lowest_low"] = entry_price
                    state["lowest_low"] = min(state["lowest_low"], hist.low[-1])
                    stop = state["lowest_low"] + risk_params[2]["b"] * entry_atr

    # Entry logic
    if pos == 0 and filter_pass:
        if ma_cross_up:
            if sizing_id == "atr_risk":
                state["entry_atr"] = atr_14[-1]
            state["entry_price"] = hist.close[-1]
            target_size = target_size
        elif ma_cross_down:
            if sizing_id == "atr_risk":
                state["entry_atr"] = atr_14[-1]
            state["entry_price"] = hist.close[-1]
            target_size = -target_size

    # Exit logic
    if pos > 0 and ma_cross_down:
        target_size = 0
        del state["entry_price"]
        del state["entry_atr"]
        if "highest_high" in state:
            del state["highest_high"]
        if "breakeven_triggered" in state:
            del state["breakeven_triggered"]
        state["last_exit_bar"] = len(hist)
    elif pos < 0 and ma_cross_up:
        target_size = 0
        del state["entry_price"]
        del state["entry_atr"]
        if "lowest_low" in state:
            del state["lowest_low"]
        if "breakeven_triggered" in state:
            del state["breakeven_triggered"]
        state["last_exit_bar"] = len(hist)

    # Rounding target to 0.05 grid
    target_size = round(target_size / 0.05) * 0.05

    return {"target": target_size, "stop": stop, "take": take}

