def strategy(hist, state, pos, ind) -> dict:
    # Parameters
    n = 96
    wait = 32
    r = 0.01
    k = 2.0
    c = 2.0
    cooldown_n = 96
    htf_minutes = 60
    htf_n = 20

    # Calculate ATR
    atr_14 = ind.atr(hist, 14)
    entry_atr = atr_14[-1] if pos != 0 else None

    # Calculate HTF EMA for trend filter
    htf_hist = hist.htf(htf_minutes)
    htf_ema_20 = ind.ema(htf_hist.close, htf_n)

    # Breakout Pullback Signal
    highest_high = ind.highest(hist.high, n)
    lowest_low = ind.lowest(hist.low, n)

    if pos == 0:
        if hist.close[-1] > highest_high[-1]:
            state['breakout_level'] = highest_high[-1]
            state['breakout_time'] = len(hist) - 1
        elif hist.close[-1] < lowest_low[-1]:
            state['breakout_level'] = lowest_low[-1]
            state['breakout_time'] = len(hist) - 1

        if 'breakout_level' in state:
            if len(hist) - 1 - state['breakout_time'] < wait:
                if (hist.close[-1] > state['breakout_level'] and hist.low[-1] <= state['breakout_level']) or \
                   (hist.close[-1] < state['breakout_level'] and hist.high[-1] >= state['breakout_level']):
                    if (hist.close[-1] > state['breakout_level'] and htf_hist.close[-1] > htf_ema_20[-1]) or \
                       (hist.close[-1] < state['breakout_level'] and htf_hist.close[-1] < htf_ema_20[-1]):
                        # Calculate position size
                        position_size = r * hist.close[-1] / (k * atr_14[-1])
                        position_size = max(0.05, min(1.0, position_size))
                        return {"target": position_size if hist.close[-1] > state['breakout_level'] else -position_size,
                                "stop": None, "take": None}

    # Cooldown
    if 'last_exit_time' in state and len(hist) - 1 - state['last_exit_time'] < cooldown_n:
        return {"target": pos, "stop": None, "take": None}

    # Take Profit
    if pos > 0 and hist.high[-1] >= state['entry_price'] + c * entry_atr:
        return {"target": 0, "stop": None, "take": None}
    elif pos < 0 and hist.low[-1] <= state['entry_price'] - c * entry_atr:
        return {"target": 0, "stop": None, "take": None}

    # Exit on opposite signal
    if pos > 0 and hist.close[-1] < lowest_low[-1]:
        return {"target": 0, "stop": None, "take": None}
    elif pos < 0 and hist.close[-1] > highest_high[-1]:
        return {"target": 0, "stop": None, "take": None}

    # Set stop and take levels
    if pos > 0:
        stop_level = state['entry_price'] - entry_atr
        take_level = state['entry_price'] + c * entry_atr
    elif pos < 0:
        stop_level = state['entry_price'] + entry_atr
        take_level = state['entry_price'] - c * entry_atr
    else:
        stop_level = None
        take_level = None

    return {"target": pos, "stop": stop_level, "take": take_level}

