import math
import numpy as np

def strategy(hist, state, pos, ind) -> dict:
    # Parameters from the strategy
    signal_id = "breakout_pullback"
    signal_params = {"n": 48, "wait": 32}
    direction = "long_only"
    filter_id = "htf_trend"
    filter_params = {"minutes": 240, "n": 20}
    sizing_id = "pyramid"
    sizing_params = {"f0": 0.5, "step": 1.0, "adds": 1}
    risk_ids = ["fixed_stop", "trailing_hwm", "daily_cap"]
    risk_params = [{"k": 2.0}, {"b": 2.0, "after_be": False}, {"k": 2}]

    # Helper functions
    def ma_cross(kind, fast, slow, close):
        if kind == 'sma':
            fast_ma = ind.sma(close, fast)
            slow_ma = ind.sma(close, slow)
        elif kind == 'ema':
            fast_ma = ind.ema(close, fast)
            slow_ma = ind.ema(close, slow)
        else:
            raise ValueError("Invalid MA kind")
        return fast_ma, slow_ma

    def macd_cross(fsg, close):
        macd_line, signal_line, _ = ind.macd(close, *fsg)
        return macd_line, signal_line

    def donchian_break(n, high, low):
        highest_high = ind.highest(high, n)
        lowest_low = ind.lowest(low, n)
        return highest_high, lowest_low

    def rsi_revert(n, lo, close):
        rsi = ind.rsi(close, n)
        return rsi

    def box_breakout(m, w, high, low, atr):
        highest_high = ind.highest(high, m)
        lowest_low = ind.lowest(low, m)
        box_height = highest_high - lowest_low
        valid_box = box_height <= w * atr
        return highest_high, lowest_low, valid_box

    def breakout_pullback(n, wait, high, low):
        highest_high = ind.highest(high, n)
        breakout_level = highest_high[-1]
        bars_since_breakout = len(hist) - 1 - np.argmax(high == breakout_level)
        armed = bars_since_breakout <= wait
        return breakout_level, armed

    def htf_trend(minutes, n, close):
        htf_close = hist.htf(minutes).close
        htf_ema = ind.ema(htf_close, n)
        return htf_close, htf_ema

    def atr_risk(r, k, close, atr):
        position_fraction = r * close / (k * atr)
        return max(0.05, min(1.0, position_fraction))

    def fixed_frac(f):
        return f

    def pyramid(f0, step, adds, close, entry_price, entry_atr, pos, last_add_price):
        if pos == 0:
            return f0
        if pos > 0:
            target_price = last_add_price + step * entry_atr
            if close >= target_price and adds > 0:
                return min(1.0, pos + f0)
        return pos

    def fixed_stop(k, entry_price, entry_atr, pos):
        if pos > 0:
            return entry_price - k * entry_atr
        elif pos < 0:
            return entry_price + k * entry_atr
        return None

    def breakeven(a, entry_price, entry_atr, pos, high, low):
        if pos > 0:
            breakeven_price = entry_price + a * entry_atr
            if high >= breakeven_price:
                return entry_price
        elif pos < 0:
            breakeven_price = entry_price - a * entry_atr
            if low <= breakeven_price:
                return entry_price
        return None

    def trailing_hwm(b, after_be, entry_price, entry_atr, pos, high, low, best_price):
        if pos > 0:
            best_price = max(best_price, high)
            if after_be and high >= entry_price + entry_atr:
                return best_price - b * entry_atr
            else:
                return entry_price - b * entry_atr
        elif pos < 0:
            best_price = min(best_price, low)
            if after_be and low <= entry_price - entry_atr:
                return best_price + b * entry_atr
            else:
                return entry_price + b * entry_atr
        return None

    def time_stop(n, entry_bar, pos):
        if pos != 0 and len(hist) - 1 - entry_bar >= n:
            return 0
        return pos

    def take_profit(c, entry_price, entry_atr, pos, high, low):
        if pos > 0:
            take_price = entry_price + c * entry_atr
            if high >= take_price:
                return 0
        elif pos < 0:
            take_price = entry_price - c * entry_atr
            if low <= take_price:
                return 0
        return pos

    def partial_take(c, entry_price, entry_atr, pos, high, low):
        if pos > 0:
            take_price = entry_price + c * entry_atr
            if high >= take_price and not state.get("partial_taken", False):
                state["partial_taken"] = True
                return pos / 2
        elif pos < 0:
            take_price = entry_price - c * entry_atr
            if low <= take_price and not state.get("partial_taken", False):
                state["partial_taken"] = True
                return pos / 2
        return pos

    def box_shift(lo, hi, step, entry_price, entry_atr, pos, high, low, anchor):
        if pos > 0:
            if high >= anchor + hi * entry_atr:
                anchor = high - lo * entry_atr
                return anchor, anchor - lo * entry_atr, anchor + hi * entry_atr
        elif pos < 0:
            if low <= anchor - hi * entry_atr:
                anchor = low + lo * entry_atr
                return anchor, anchor + lo * entry_atr, anchor - hi * entry_atr
        return anchor, anchor - lo * entry_atr, anchor + hi * entry_atr

    def cooldown(n, pos, last_exit_bar):
        if pos == 0 and len(hist) - 1 - last_exit_bar < n:
            return True
        return False

    def daily_cap(k, pos, last_entry_time):
        current_time = hist.time[-1]
        current_day = current_time // (24 * 60 * 60 * 1000)
        last_entry_day = last_entry_time // (24 * 60 * 60 * 1000)
        if pos == 0 and current_day > last_entry_day and state.get("daily_entries", 0) < k:
            return False
        return True

    # Signal calculation
    if signal_id == "breakout_pullback":
        breakout_level, armed = breakout_pullback(signal_params["n"], signal_params["wait"], hist.high, hist.low)

    # Filter calculation
    if filter_id == "htf_trend":
        htf_close, htf_ema = htf_trend(filter_params["minutes"], filter_params["n"], hist.close)
        htf_trend_long = htf_close[-1] > htf_ema[-1]
        htf_trend_short = htf_close[-1] < htf_ema[-1]

    # Sizing calculation
    atr = ind.atr(hist, 14)[-1]
    if sizing_id == "fixed_frac":
        position_fraction = fixed_frac(sizing_params["f0"])
    elif sizing_id == "atr_risk":
        position_fraction = atr_risk(sizing_params["r"], sizing_params["k"], hist.close[-1], atr)
    elif sizing_id == "pyramid":
        if "entry_price" not in state:
            state["entry_price"] = hist.close[-1]
            state["entry_atr"] = atr
            state["last_add_price"] = hist.close[-1]
            state["anchor"] = hist.close[-1]
        position_fraction = pyramid(sizing_params["f0"], sizing_params["step"], sizing_params["adds"], hist.close[-1], state["entry_price"], state["entry_atr"], pos, state["last_add_price"])
        if hist.close[-1] >= state["last_add_price"] + sizing_params["step"] * state["entry_atr"]:
            state["last_add_price"] = hist.close[-1]

    # Risk management
    stop = None
    take = None
    for risk_id, risk_param in zip(risk_ids, risk_params):
        if risk_id == "fixed_stop":
            stop = fixed_stop(risk_param["k"], state.get("entry_price", hist.close[-1]), state.get("entry_atr", atr), pos)
        elif risk_id == "breakeven":
            stop = breakeven(risk_param["a"], state.get("entry_price", hist.close[-1]), state.get("entry_atr", atr), pos, hist.high[-1], hist.low[-1])
        elif risk_id == "trailing_hwm":
            if "best_price" not in state:
                state["best_price"] = hist.close[-1]
            state["best_price"] = trailing_hwm(risk_param["b"], risk_param["after_be"], state.get("entry_price", hist.close[-1]), state.get("entry_atr", atr), pos, hist.high[-1], hist.low[-1], state["best_price"])
            stop = state["best_price"]
        elif risk_id == "time_stop":
            if "entry_bar" not in state:
                state["entry_bar"] = len(hist) - 1
            pos = time_stop(risk_param["n"], state["entry_bar"], pos)
        elif risk_id == "take_profit":
            pos = take_profit(risk_param["c"], state.get("entry_price", hist.close[-1]), state.get("entry_atr", atr), pos, hist.high[-1], hist.low[-1])
        elif risk_id == "partial_take":
            pos = partial_take(risk_param["c"], state.get("entry_price", hist.close[-1]), state.get("entry_atr", atr), pos, hist.high[-1], hist.low[-1])
        elif risk_id == "box_shift":
            if "anchor" not in state:
                state["anchor"] = state.get("entry_price", hist.close[-1])
            state["anchor"], stop, take = box_shift(risk_param["lo"], risk_param["hi"], risk_param["step"], state.get("entry_price", hist.close[-1]), state.get("entry_atr", atr), pos, hist.high[-1], hist.low[-1], state["anchor"])
        elif risk_id == "cooldown":
            if "last_exit_bar" not in state:
                state["last_exit_bar"] = len(hist) - 1
            if cooldown(risk_param["n"], pos, state["last_exit_bar"]):
                return {"target": pos, "stop": stop, "take": take}
        elif risk_id == "daily_cap":
            if "last_entry_time" not in state:
                state["last_entry_time"] = 0
            if daily_cap(risk_param["k"], pos, state["last_entry_time"]):
                return {"target": pos, "stop": stop, "take": take}

    # Entry logic
    if pos == 0 and direction == "long_only" and htf_trend_long and armed and hist.low[-1] <= breakout_level:
        pos = position_fraction
        state["entry_price"] = hist.close[-1]
        state["entry_atr"] = atr
        state["last_add_price"] = hist.close[-1]
        state["anchor"] = hist.close[-1]
        state["daily_entries"] = state.get("daily_entries", 0) + 1
        state["last_entry_time"] = hist.time[-1]
        del state["partial_taken"]
    elif pos == 0 and direction == "long_short" and htf_trend_short and armed and hist.high[-1] >= breakout_level:
        pos = -position_fraction
        state["entry_price"] = hist.close[-1]
        state["entry_atr"] = atr
        state["last_add_price"] = hist.close[-1]
        state["anchor"] = hist.close[-1]
        state["daily_entries"] = state.get("daily_entries", 0) + 1
        state["last_entry_time"] = hist.time[-1]
        del state["partial_taken"]

    # Exit logic
    if pos != 0 and (stop is not None and (hist.low[-1] <= stop or hist.high[-1] >= stop)):
        pos = 0
        state["last_exit_bar"] = len(hist) - 1
        del state["entry_price"]
        del state["entry_atr"]
        del state["last_add_price"]
        del state["anchor"]
        del state["daily_entries"]
        del state["last_entry_time"]
        del state["partial_taken"]
    elif pos != 0 and (take is not None and (hist.high[-1] >= take or hist.low[-1] <= take)):
        pos = 0
        state["last_exit_bar"] = len(hist) - 1
        del state["entry_price"]
        del state["entry_atr"]
        del state["last_add_price"]
        del state["anchor"]
        del state["daily_entries"]
        del state["last_entry_time"]
        del state["partial_taken"]

    # Round target to 0.05 grid
    target = round(pos / 0.05) * 0.05

    return {"target": target, "stop": stop, "take": take}

