    sizing_params = {"r": 0.01, "k": 2.0}
    risk_ids = ["daily_cap"]
    risk_params = [{"k": 3}]

    # Helper functions
    def round_to_grid(value, grid=0.05):
        return round(value / grid) * grid

    def get_daily_bar_index(hist):
        current_time = hist.time[-1]
        daily_start_time = current_time - (current_time % (24 * 60 * 60 * 1000))
        return daily_start_time

    # Signal calculation
    if signal_id == "box_breakout":
        m = signal_params["m"]
        w = signal_params["w"]
        high = hist.high
        low = hist.low
        close = hist.close
        atr_14 = ind.atr(hist, 14)
        entry_atr = atr_14[-1]
        highest_high = ind.highest(high, m)
        lowest_low = ind.lowest(low, m)
        box_height = highest_high - lowest_low
        box_valid = box_height <= w * entry_atr
        breakout_long = close[-1] > highest_high[-1] and box_valid
        breakout_short = close[-1] < lowest_low[-1] and box_valid

    # Filter calculation
    if filter_id == "htf_trend":
        minutes = filter_params["minutes"]
        n = filter_params["n"]
        htf_close = hist.htf(minutes).close
        htf_ema = ind.ema(htf_close, n)
        htf_last_close = htf_close[-1]
        htf_last_ema = htf_ema[-1]
        filter_long = htf_last_close > htf_last_ema
        filter_short = htf_last_close < htf_last_ema

    # Sizing calculation
    if sizing_id == "atr_risk":
        r = sizing_params["r"]
        k = sizing_params["k"]
        close = hist.close
        atr_14 = ind.atr(hist, 14)
        entry_atr = atr_14[-1]
        position_size = r * close[-1] / (k * entry_atr)
        position_size = max(0.05, min(1.0, position_size))

    # Risk management
    stop = None
    take = None
    if risk_ids and risk_params:
        for risk_id, risk_param in zip(risk_ids, risk_params):
            if risk_id == "daily_cap":
                k = risk_param["k"]
                daily_bar_index = get_daily_bar_index(hist)
                if "last_daily_trade_time" in state and state["last_daily_trade_time"] == daily_bar_index:
                    if state.get("daily_trade_count", 0) >= k:
                        return {"target": pos, "stop": stop, "take": take}
                else:
                    state["daily_trade_count"] = 0
                    state["last_daily_trade_time"] = daily_bar_index

    # Entry logic
    if pos == 0:
        if direction == "long_only" or direction == "long_short":
            if breakout_long and filter_long:
                target = round_to_grid(position_size)
                stop = close[-1] - entry_atr
                take = close[-1] + 2 * entry_atr
                state["entry_price"] = close[-1]
                state["entry_atr"] = entry_atr
                state["daily_trade_count"] = state.get("daily_trade_count", 0) + 1
                return {"target": target, "stop": stop, "take": take}
        if direction == "long_short":
            if breakout_short and filter_short:
                target = round_to_grid(-position_size)
                stop = close[-1] + entry_atr
                take = close[-1] - 2 * entry_atr
                state["entry_price"] = close[-1]
                state["entry_atr"] = entry_atr
                state["daily_trade_count"] = state.get("daily_trade_count", 0) + 1
                return {"target": target, "stop": stop, "take": take}

    # Exit logic
    if pos != 0:
        entry_price = state["entry_price"]
        entry_atr = state["entry_atr"]
        if pos > 0:
            if hist.low[-1] <= stop:
                return {"target": 0, "stop": None, "take": None}
            if hist.high[-1] >= take:
                return {"target": 0, "stop": None, "take": None}
        if pos < 0:
            if hist.high[-1] >= stop:
                return {"target": 0, "stop": None, "take": None}
            if hist.low[-1] <= take:
                return {"target": 0, "stop": None, "take": None}

    # Opposite signal logic
    if pos > 0 and breakout_short and filter_short:
        return {"target": 0, "stop": None, "take": None}
    if pos < 0 and breakout_long and filter_long:
        return {"target": 0, "stop": None, "take": None}

    return {"target": pos, "stop": stop, "take": take}

