                    state["position_size"] = min(1.0, state["position_size"] + f0)
                    state["last_add_price"] = hist.close[-1]
                    state["adds_count"] += 1

    # Risk management
    stop = None
    take = None

    if risk_ids and risk_params:
        for risk_id, risk_param in zip(risk_ids, risk_params):
            if risk_id == "breakeven":
                a = risk_param["a"]
                if pos > 0 and hist.close[-1] >= state["entry_price"] + a * entry_atr:
