               (signal == "short" and hist.close[-1] <= entry_price - step * entry_atr):
                if current_adds < adds:
                    position_fraction = min(1.0, position_fraction + f0)
                    state["position_fraction"] = position_fraction
                    state["entry_price"] = hist.close[-1]
