                c = risk_param["c"]
                if pos > 0 and hist.close[-1] >= state["entry_price"] + c * entry_atr:
                    position_fraction /= 2.0
                elif pos < 0 and hist.close[-1] <= state["entry_price"] - c * entry_atr:
                    position_fraction /= 2.0
            elif risk_id == "box_shift":
                lo = risk_param["lo"]
                hi = risk_param["hi"]
                step = risk_param["step"]
                if "anchor" not in state:
                    state["anchor"] = state["entry_price"]
                if pos > 0:
                    if hist.close[-1] >= state["anchor"] + step * entry_atr:
                        state["anchor"] = state["anchor"] + step * entry_atr
                    stop = state["anchor"] - lo * entry_atr
                    take = state["anchor"] + hi * entry_atr
                elif pos < 0:
                    if hist.close[-1] <= state["anchor"] - step * entry_atr:
                        state["anchor"] = state["anchor"] - step * entry_atr
                    stop = state["anchor"] + lo * entry_atr
                    take = state["anchor"] - hi * entry_atr
            elif risk_id == "cooldown":
                n = risk_param["n"]
                if "exit_bar" in state and len(hist) - state["exit_bar"] < n:
                    signal = None
            elif risk_id == "daily_cap":
                k = risk_param["k"]
                current_day = hist.time[-1] // (1000 * 60 * 60 * 24)
                if "last_entry_day" in state and state["last_entry_day"] == current_day:
                    signal = None
                else:
                    state["last_entry_day"] = current_day

    # Determine target position
    if signal == "long" and filter_signal:
        target = position_fraction
    elif signal == "short" and filter_signal:
        target = -position_fraction
    else:
        target = 0.0
        if pos != 0.0:
            state["exit_bar"] = len(hist) - 1
        if "entry_price" in state:
            del state["entry_price"]
        if "position_fraction" in state:
            del state["position_fraction"]
        if "adds" in state:
            del state["adds"]
        if "hwm" in state:
            del state["hwm"]
        if "anchor" in state:
            del state["anchor"]

    # Round target to 0.05 grid
    target = round(target / 0.05) * 0.05

    return {"target": target, "stop": stop, "take": take}

