    sizing_frac = 0.75
    daily_cap = 1

    # Calculate RSI
    rsi = ind.rsi(hist.close, rsi_length)

    # Calculate ATR for stop and take-profit levels
    atr = ind.atr(hist, 14)
    entry_atr = atr[-1] if pos != 0 else None

