    HTF_N = 50
    SIZING_F = 0.75
    COOLDOWN_N = 48
    DAILY_CAP_K = 1

    # Helper functions
    def is_new_day(bar_time):
        if 'last_day' not in state:
            state['last_day'] = bar_time // (1000 * 60 * 60 * 24)
            return True
        current_day = bar_time // (1000 * 60 * 60 * 24)
        if current_day > state['last_day']:
            state['last_day'] = current_day
            return True
        return False

    def round_to_grid(value, grid=0.05):
        return round(value / grid) * grid

    # Check for cooldown
    if 'cooldown_until' in state and len(hist) < state['cooldown_until']:
        return {"target": pos, "stop": None, "take": None}

    # Check for daily cap
    if 'daily_entry' in state and not is_new_day(hist.time[-1]):
        return {"target": pos, "stop": None, "take": None}

    # Calculate indicators
    htf = hist.htf(HTF_MINUTES)
    htf_ema = ind.ema(htf.close, HTF_N)
    atr_14 = ind.atr(hist, 14)
    entry_atr = atr_14[-1] if 'entry_atr' not in state else state['entry_atr']
    highest_high = ind.highest(hist.high, SIGNAL_N)
    lowest_low = ind.lowest(hist.low, SIGNAL_N)

    # Breakout pullback signal
    if 'breakout_high' not in state and hist.close[-1] > highest_high[-2]:
        state['breakout_high'] = hist.close[-1]
        state['breakout_time'] = len(hist)
    elif 'breakout_high' in state and len(hist) - state['breakout_time'] > SIGNAL_WAIT:
        del state['breakout_high']
        del state['breakout_time']

    if 'breakout_low' not in state and hist.close[-1] < lowest_low[-2]:
        state['breakout_low'] = hist.close[-1]
        state['breakout_time'] = len(hist)
    elif 'breakout_low' in state and len(hist) - state['breakout_time'] > SIGNAL_WAIT:
        del state['breakout_low']
        del state['breakout_time']

    # Check for long entry
    if 'breakout_high' in state and hist.low[-1] <= state['breakout_high'] and htf.close[-1] > htf_ema[-1]:
        if pos == 0:
            state['entry_price'] = hist.close[-1]
            state['entry_atr'] = entry_atr
            state['daily_entry'] = True
            target = round_to_grid(SIZING_F)
            stop = state['entry_price'] - entry_atr
            return {"target": target, "stop": stop, "take": None}

    # Check for short entry
    if 'breakout_low' in state and hist.high[-1] >= state['breakout_low'] and htf.close[-1] < htf_ema[-1]:
        if pos == 0:
            state['entry_price'] = hist.close[-1]
            state['entry_atr'] = entry_atr
            state['daily_entry'] = True
            target = round_to_grid(-SIZING_F)
            stop = state['entry_price'] + entry_atr
            return {"target": target, "stop": stop, "take": None}

    # Opposite signal to close position
    if pos > 0 and 'breakout_low' in state and hist.high[-1] >= state['breakout_low']:
        return {"target": 0, "stop": None, "take": None}
    if pos < 0 and 'breakout_high' in state and hist.low[-1] <= state['breakout_high']:
        return {"target": 0, "stop": None, "take": None}

    # Maintain stop for long position
    if pos > 0:
        stop = state['entry_price'] - entry_atr
        return {"target": pos, "stop": stop, "take": None}

    # Maintain stop for short position
    if pos < 0:
        stop = state['entry_price'] + entry_atr
        return {"target": pos, "stop": stop, "take": None}

    # No action
    return {"target": pos, "stop": None, "take": None}

