    # Signal calculation
    if signal_id == "ma_cross":
        if signal_params["kind"] == "ema":
            bullish_signal = (ema_fast[-1] > ema_slow[-1]) and (ema_fast[-2] <= ema_slow[-2])
            bearish_signal = (ema_fast[-1] < ema_slow[-1]) and (ema_fast[-2] >= ema_slow[-2])
        else:
