    if risk_ids[2] == "daily_cap":
        k = risk_params[2]["k"]
        current_time = hist.time[-1]
        current_day = current_time // (1000 * 60 * 60 * 24)
        if "last_entry_day" not in state or state["last_entry_day"] != current_day:
