    lowest_low = ind.lowest(hist.low, BOX_PERIOD)
    box_height = highest_high - lowest_low
    box_valid = box_height <= BOX_WIDTH_MULTIPLE * atr[-1]

    # Determine signal bar
    signal_bar = False
    if pos == 0:
        if hist.close[-1] > highest_high[-1] and box_valid:
            signal_bar = True
            entry_atr = atr[-1]

    # Determine breakout pullback
    if pos != 0:
        if hist.close[-1] < lowest_low[-1]:
            return {"target": 0.0, "stop": None, "take": None}

    # Determine position target
    target = pos
    if signal_bar:
        target = POSITION_SIZE

    # Determine stop and take levels
    stop = None
    take = None
    if pos > 0:
        stop = hist.close[-1] - STOP_MULTIPLE * entry_atr
        take = hist.close[-1] + TAKE_PROFIT_MULTIPLE * entry_atr

    # Box shift logic
    if pos > 0 and entry_atr is not None:
        if "anchor" not in state:
            state["anchor"] = hist.close[-1]
        else:
            while hist.close[-1] >= state["anchor"] + BOX_SHIFT_MULTIPLE * entry_atr:
                state["anchor"] += BOX_SHIFT_MULTIPLE * entry_atr
                stop = state["anchor"] - STOP_MULTIPLE * entry_atr
                take = state["anchor"] + TAKE_PROFIT_MULTIPLE * entry_atr

    # Cooldown logic
    if pos == 0:
        if "last_exit_bar" in state:
            if len(hist) - state["last_exit_bar"] < COOLDOWN_BARS:
                return {"target": 0.0, "stop": None, "take": None}

    # Daily cap logic
    if pos == 0:
        current_day = hist.time[-1] // (1000 * 60 * 60 * 24)
        if "daily_entries" not in state:
            state["daily_entries"] = {}
        if current_day not in state["daily_entries"]:
            state["daily_entries"][current_day] = 0
        if state["daily_entries"][current_day] >= DAILY_CAP:
            return {"target": 0.0, "stop": None, "take": None}

    # Update daily entries
    if signal_bar:
        current_day = hist.time[-1] // (1000 * 60 * 60 * 24)
        if current_day not in state["daily_entries"]:
            state["daily_entries"][current_day] = 0
        state["daily_entries"][current_day] += 1

    # Update last exit bar
    if pos == 0 and state.get("last_exit_bar", -COOLDOWN_BARS) < len(hist) - 1:
        state["last_exit_bar"] = len(hist) - 1

