            take = entry_price + hi
            if hist.close[-1] >= state["anchor"] + step:
                state["anchor"] = hist.close[-1]
                stop = entry_price - lo
                take = entry_price + hi
        elif pos < 0:
            stop = entry_price + lo
            take = entry_price - hi
            if hist.close[-1] <= state["anchor"] - step:
                state["anchor"] = hist.close[-1]
                stop = entry_price + lo
                take = entry_price - hi

