                    if hist.close[-1] >= state["anchor"] + step * entry_atr:
                        state["anchor"] = state["anchor"] + step * entry_atr
                    stop = state["anchor"] - lo * entry_atr
                    take = state["anchor"] + hi * entry_atr
                elif pos < 0:
                    if hist.close[-1] <= state["anchor"] - step * entry_atr:
                        state["anchor"] = state["anchor"] - step * entry_atr
                    stop = state["anchor"] + lo * entry_atr
                    take = state["anchor"] - hi * entry_atr
            elif risk_id == "cooldown":
                n = risk_param["n"]
                if "exit_bar" in state:
                    bars_since_exit = len(hist) - 1 - state["exit_bar"]
                    if bars_since_exit < n:
                        filter_pass = False
            elif risk_id == "daily_cap":
                k = risk_param["k"]
                if "last_entry_time" in state:
                    current_day = hist.time[-1] // (24 * 60 * 60 * 1000)
                    last_entry_day = state["last_entry_time"] // (24 * 60 * 60 * 1000)
                    if current_day == last_entry_day:
                        filter_pass = False

    # Determine target position
    if pos == 0:
        if filter_pass and ((direction == "long_only" and bullish_signal) or (direction == "long_short" and (bullish_signal or bearish_signal))):
            target_size = target_size
            state["entry_price"] = hist.close[-1]
            state["entry_bar"] = len(hist) - 1
            state["last_entry_time"] = hist.time[-1]
            del state.get("best_high", None)
            del state.get("best_low", None)
            del state.get("anchor", None)
            del state.get("last_add_price", None)
            del state.get("add_count", None)
        else:
            target_size = 0.0
    else:
        if bearish_signal:
            target_size = 0.0
            state["exit_bar"] = len(hist) - 1

    # Round target to 0.05 grid
    target_size = round(target_size / 0.05) * 0.05

    return {"target": target_size, "stop": stop, "take": take}

