    bearish_signal = (current_sma_fast < current_sma_slow) and (previous_sma_fast >= previous_sma_slow)

    # Cooldown check
    if 'last_exit_bar' in state:
        bars_since_last_exit = len(hist) - state['last_exit_bar']
        if bars_since_last_exit < cooldown_period:
