        # Box shift logic
        if 'anchor_price' not in state:
            state['anchor_price'] = entry_price

        anchor_price = state['anchor_price']
        if pos > 0:
            if hist.close[-1] >= anchor_price + box_shift_step * entry_atr:
                new_anchor_price = math.ceil((hist.close[-1] - entry_atr) / entry_atr) * entry_atr
                state['anchor_price'] = new_anchor_price
        else:
            if hist.close[-1] <= anchor_price - box_shift_step * entry_atr:
                new_anchor_price = math.floor((hist.close[-1] + entry_atr) / entry_atr) * entry_atr
                state['anchor_price'] = new_anchor_price

        anchor_price = state['anchor_price']
        stop = anchor_price - box_shift_lo * entry_atr
        take = anchor_price + box_shift_hi * entry_atr

        # Trailing stop logic
        if pos > 0:
