    highest_high = ind.highest(hist.high, BREAKOUT_PULLBACK_N)
    lowest_low = ind.lowest(hist.low, BREAKOUT_PULLBACK_N)

    # Breakout Pullback Logic
    if 'breakout_level' not in state:
        if hist.close[-1] > highest_high[-2]:
            state['breakout_level'] = highest_high[-2]
            state['breakout_time'] = len(hist) - 1
        elif hist.close[-1] < lowest_low[-2]:
            state['breakout_level'] = lowest_low[-2]
            state['breakout_time'] = len(hist) - 1
    else:
        if len(hist) - 1 - state['breakout_time'] > BREAKOUT_PULLBACK_WAIT:
            del state['breakout_level']
            del state['breakout_time']
        elif 'long_setup' in state and hist.low[-1] <= state['breakout_level']:
            target = POSITION_SIZE
            stop = hist.close[-1] - STOP_ATR_MULT * entry_atr
            state['entry_atr'] = entry_atr
            state['entry_price'] = hist.close[-1]
            state['long_setup'] = False
            del state['breakout_level']
            del state['breakout_time']
            return {"target": target, "stop": stop, "take": None}
        elif 'short_setup' in state and hist.high[-1] >= state['breakout_level']:
            target = -POSITION_SIZE
            stop = hist.close[-1] + STOP_ATR_MULT * entry_atr
            state['entry_atr'] = entry_atr
            state['entry_price'] = hist.close[-1]
            state['short_setup'] = False
            del state['breakout_level']
            del state['breakout_time']
            return {"target": target, "stop": stop, "take": None}

    # Check for new breakout
    if 'breakout_level' not in state:
        if hist.close[-1] > highest_high[-2]:
            state['breakout_level'] = highest_high[-2]
            state['breakout_time'] = len(hist) - 1
            state['long_setup'] = True
        elif hist.close[-1] < lowest_low[-2]:
            state['breakout_level'] = lowest_low[-2]
            state['breakout_time'] = len(hist) - 1
            state['short_setup'] = True

    # Breakeven Logic
    if pos > 0 and 'entry_price' in state:
        breakeven_price = state['entry_price']
        if hist.close[-1] >= breakeven_price + BREAKEVEN_ATR_MULT * entry_atr:
            stop = breakeven_price
            return {"target": pos, "stop": stop, "take": None}
    elif pos < 0 and 'entry_price' in state:
        breakeven_price = state['entry_price']
        if hist.close[-1] <= breakeven_price - BREAKEVEN_ATR_MULT * entry_atr:
            stop = breakeven_price
            return {"target": pos, "stop": stop, "take": None}

    # Exit if opposite signal comes in
    if pos > 0 and 'breakout_level' in state and hist.low[-1] <= state['breakout_level']:
        return {"target": 0, "stop": None, "take": None}
    elif pos < 0 and 'breakout_level' in state and hist.high[-1] >= state['breakout_level']:
        return {"target": 0, "stop": None, "take": None}

    # Return current position if no new signals
    return {"target": pos, "stop": None, "take": None}

