            state['short_setup_time'] = t

    # Check for long entry
    if pos == 0 and 'long_setup' in state and t - state['long_setup_time'] < wait:
        if hist.low[t] <= state['long_setup']:
            return {"target": position_size, "stop": state['long_setup'] - entry_atr, "take": None}

    # Check for short entry
    if pos == 0 and 'short_setup' in state and t - state['short_setup_time'] < wait:
        if hist.high[t] >= state['short_setup']:
            return {"target": -position_size, "stop": state['short_setup'] + entry_atr, "take": None}

    # Check for opposite signal while in a trade
    if pos > 0 and hist.close[t] < low_48[t - 1]:
        return {"target": 0, "stop": None, "take": None}
    if pos < 0 and hist.close[t] > high_48[t - 1]:
        return {"target": 0, "stop": None, "take": None}

    # Manage stops and takes
    stop = None
    take = None
    if pos > 0:
        stop = state['long_setup'] - entry_atr
    if pos < 0:
        stop = state['short_setup'] + entry_atr

    return {"target": pos, "stop": stop, "take": take}

