        short_allowed = htf_close[-1] < htf_ema[-1]

    # Sizing calculation
    if sizing_id == "atr_risk":
        atr_14 = ind.atr(hist, 14)
        entry_atr = atr_14[-1]
        risk_fraction = sizing_params["r"]
        atr_multiple = sizing_params["k"]
        position_fraction = risk_fraction * hist.close[-1] / (atr_multiple * entry_atr)
        position_fraction = max(0.05, min(1.0, position_fraction))

    # Risk management
    stop = None
    take = None

    if risk_ids:
        for risk_id, risk_param in zip(risk_ids, risk_params):
            if risk_id == "fixed_stop":
                k = risk_param["k"]
                if pos > 0:
                    stop = hist.close[-1] - k * entry_atr
                elif pos < 0:
                    stop = hist.close[-1] + k * entry_atr
            elif risk_id == "breakeven":
                a = risk_param["a"]
                if pos > 0 and hist.close[-1] >= hist.close[state.get("entry_bar", -1)] + a * entry_atr:
                    stop = hist.close[state.get("entry_bar", -1)]
                elif pos < 0 and hist.close[-1] <= hist.close[state.get("entry_bar", -1)] - a * entry_atr:
                    stop = hist.close[state.get("entry_bar", -1)]
            elif risk_id == "trailing_hwm":
                b = risk_param["b"]
                after_be = risk_param["after_be"]
                if pos > 0:
                    if "hwm" not in state:
                        state["hwm"] = hist.high[-1]
                    else:
                        state["hwm"] = max(state["hwm"], hist.high[-1])
                    if after_be and stop is not None and stop >= hist.close[state.get("entry_bar", -1)]:
                        stop = state["hwm"] - b * entry_atr
                    else:
                        stop = state["hwm"] - b * entry_atr
                elif pos < 0:
                    if "hwm" not in state:
                        state["hwm"] = hist.low[-1]
                    else:
                        state["hwm"] = min(state["hwm"], hist.low[-1])
                    if after_be and stop is not None and stop <= hist.close[state.get("entry_bar", -1)]:
                        stop = state["hwm"] + b * entry_atr
                    else:
                        stop = state["hwm"] + b * entry_atr
            elif risk_id == "time_stop":
                n = risk_param["n"]
                if "entry_bar" in state and len(hist) - state["entry_bar"] >= n:
                    stop = hist.open[-1]
            elif risk_id == "take_profit":
                c = risk_param["c"]
                if pos > 0:
                    take = hist.close[state.get("entry_bar", -1)] + c * entry_atr
                elif pos < 0:
                    take = hist.close[state.get("entry_bar", -1)] - c * entry_atr
            elif risk_id == "partial_take":
                c = risk_param["c"]
                if pos > 0 and hist.close[-1] >= hist.close[state.get("entry_bar", -1)] + c * entry_atr:
                    if "partial_taken" not in state:
                        state["partial_taken"] = True
                        position_fraction /= 2
                elif pos < 0 and hist.close[-1] <= hist.close[state.get("entry_bar", -1)] - c * entry_atr:
                    if "partial_taken" not in state:
                        state["partial_taken"] = True
                        position_fraction /= 2
            elif risk_id == "box_shift":
                lo = risk_param["lo"]
                hi = risk_param["hi"]
                step = risk_param["step"]
                if "anchor" not in state:
                    state["anchor"] = hist.close[state.get("entry_bar", -1)]
                if pos > 0:
                    if hist.close[-1] >= state["anchor"] + step * entry_atr:
                        state["anchor"] = hist.close[-1]
                        stop = state["anchor"] - lo * entry_atr
                        take = state["anchor"] + hi * entry_atr
                elif pos < 0:
                    if hist.close[-1] <= state["anchor"] - step * entry_atr:
                        state["anchor"] = hist.close[-1]
                        stop = state["anchor"] + lo * entry_atr
                        take = state["anchor"] - hi * entry_atr
            elif risk_id == "cooldown":
                n = risk_param["n"]
                if "exit_bar" in state and len(hist) - state["exit_bar"] < n:
                    long_allowed = False
                    short_allowed = False
            elif risk_id == "daily_cap":
                k = risk_param["k"]
                current_day = hist.time[-1] // (24 * 60 * 60 * 1000)
                if "last_entry_day" in state and state["last_entry_day"] == current_day:
                    if state.get("daily_entries", 0) >= k:
                        long_allowed = False
                        short_allowed = False
                else:
                    state["last_entry_day"] = current_day
                    state["daily_entries"] = 0

    # Determine target position
    target = pos
    if pos == 0:
        if long_signal and long_allowed:
            target = position_fraction
            state["entry_bar"] = len(hist) - 1
            state["daily_entries"] = state.get("daily_entries", 0) + 1
            del state.get("exit_bar", None)
            del state.get("hwm", None)
            del state.get("partial_taken", None)
            del state.get("anchor", None)
        elif short_signal and short_allowed:
            target = -position_fraction
            state["entry_bar"] = len(hist) - 1
            state["daily_entries"] = state.get("daily_entries", 0) + 1
            del state.get("exit_bar", None)
            del state.get("hwm", None)
            del state.get("partial_taken", None)
            del state.get("anchor", None)
    else:
        if (pos > 0 and short_signal) or (pos < 0 and long_signal):
            target = 0
            state["exit_bar"] = len(hist) - 1

    # Round target to 0.05 grid
    target = round(target / 0.05) * 0.05

    return {"target": target, "stop": stop, "take": take}

