def strategy(hist, state, pos, ind) -> dict:
    # Constants
    ATR_PERIOD = 14
    DONCHIAN_PERIOD = 48
    COOLDOWN_PERIOD = 48
    PYRAMID_STEP = 1.0
    PYRAMID_ADDS = 1
    INITIAL_SIZE = 0.25
    MAX_SIZE = 1.0

    # Calculate ATR
    atr = ind.atr(hist, ATR_PERIOD)
    entry_atr = atr[-1] if 'entry_atr' not in state else state['entry_atr']

    # Calculate Donchian Channel
    donchian_high = ind.highest(hist.high, DONCHIAN_PERIOD)
    donchian_low = ind.lowest(hist.low, DONCHIAN_PERIOD)

    # Determine signals
    long_signal = hist.close[-1] > donchian_high[-2]
    short_signal = hist.close[-1] < donchian_low[-2]

    # Check for opposite direction breakout to close position
    if pos > 0 and short_signal:
        return {"target": 0.0, "stop": None, "take": None}
    if pos < 0 and long_signal:
        return {"target": 0.0, "stop": None, "take": None}

    # Check for cooldown
    if 'last_exit_bar' in state and len(hist) - state['last_exit_bar'] <= COOLDOWN_PERIOD:
        return {"target": pos, "stop": None, "take": None}

    # Determine target size based on pyramid
    target_size = pos
    if pos == 0:
        if long_signal:
            target_size = INITIAL_SIZE
        elif short_signal:
            target_size = -INITIAL_SIZE
    else:
        if pos > 0:
            last_add_price = state.get('last_add_price', hist.close[-1])
            if hist.close[-1] >= last_add_price + entry_atr * PYRAMID_STEP:
                target_size = min(pos + INITIAL_SIZE, MAX_SIZE)
                state['last_add_price'] = hist.close[-1]
        elif pos < 0:
            last_add_price = state.get('last_add_price', hist.close[-1])
            if hist.close[-1] <= last_add_price - entry_atr * PYRAMID_STEP:
                target_size = max(pos - INITIAL_SIZE, -MAX_SIZE)
                state['last_add_price'] = hist.close[-1]

    # Set stop and take levels
    stop_level = None
    take_level = None

    # Update state
    if target_size != pos:
        state['entry_atr'] = entry_atr
        state['last_add_price'] = hist.close[-1]
        if target_size == 0:
            state['last_exit_bar'] = len(hist)

    # Return the target, stop, and take levels
    return {"target": target_size, "stop": stop_level, "take": take_level}

import math
import numpy as np

def strategy(hist, state, pos, ind) -> dict:
    # Parameters from the strategy
    signal_id = "breakout_pullback"
    signal_params = {"n": 48, "wait": 16}
    direction = "long_short"
    filter_id = "htf_trend"
    filter_params = {"minutes": 60, "n": 20}
    sizing_id = "atr_risk"
    sizing_params = {"r": 0.005, "k": 2.0}
    risk_ids = ["cooldown"]
    risk_params = [{"n": 48}]

    # Helper functions
    def ma_cross(kind, fast, slow, close):
        if kind == 'sma':
            fast_ma = ind.sma(close, fast)
            slow_ma = ind.sma(close, slow)
        elif kind == 'ema':
            fast_ma = ind.ema(close, fast)
            slow_ma = ind.ema(close, slow)
        else:
            raise ValueError("Invalid MA kind")
        return fast_ma, slow_ma

    def macd_cross(fsg, close):
        macd_line, signal_line, _ = ind.macd(close, *fsg)
        return macd_line, signal_line

    def donchian_break(n, high, low):
        highest_high = ind.highest(high, n)
        lowest_low = ind.lowest(low, n)
        return highest_high, lowest_low

    def rsi_revert(n, lo, close):
        rsi = ind.rsi(close, n)
        return rsi

    def box_breakout(m, w, high, low):
        highest_high = ind.highest(high, m)
        lowest_low = ind.lowest(low, m)
        atr_14 = ind.atr(hist, 14)
        box_height = highest_high - lowest_low
        valid_box = box_height <= w * atr_14
        return highest_high, lowest_low, valid_box

    def breakout_pullback(n, wait, high, low):
        highest_high = ind.highest(high, n)
        lowest_low = ind.lowest(low, n)
        return highest_high, lowest_low

    def htf_trend(minutes, n, close):
        htf_close = hist.htf(minutes).close
        htf_ema = ind.ema(htf_close, n)
        return htf_close, htf_ema

    def atr_risk(r, k, close, atr):
        position_fraction = r * close / (k * atr)
        return max(0.05, min(1.0, position_fraction))

    def fixed_stop(k, entry_price, entry_atr):
        stop_level = entry_price - k * entry_atr if pos > 0 else entry_price + k * entry_atr
        return stop_level

    def breakeven(a, entry_price, entry_atr, high, low):
        breakeven_level = entry_price + a * entry_atr if pos > 0 else entry_price - a * entry_atr
        return breakeven_level

    def trailing_hwm(b, after_be, entry_price, entry_atr, high, low):
        if pos > 0:
            hwm = max(entry_price, high)
            stop_level = hwm - b * entry_atr
            if after_be and state.get('breakeven_hit', False):
                stop_level = max(stop_level, entry_price)
        else:
            hwm = min(entry_price, low)
            stop_level = hwm + b * entry_atr
            if after_be and state.get('breakeven_hit', False):
                stop_level = min(stop_level, entry_price)
        return stop_level

    def time_stop(n, entry_bar):
        return len(hist) - entry_bar >= n

    def take_profit(c, entry_price, entry_atr):
        take_level = entry_price + c * entry_atr if pos > 0 else entry_price - c * entry_atr
        return take_level

    def partial_take(c, entry_price, entry_atr, high, low):
        take_level = entry_price + c * entry_atr if pos > 0 else entry_price - c * entry_atr
        return take_level

    def box_shift(lo, hi, step, entry_price, entry_atr, high, low):
        if pos > 0:
            anchor = state.get('box_anchor', entry_price)
            stop_level = anchor - lo * entry_atr
            target_level = anchor + hi * entry_atr
            if high >= anchor + step * entry_atr:
                new_anchor = anchor + step * entry_atr
                state['box_anchor'] = new_anchor
                stop_level = new_anchor - lo * entry_atr
                target_level = new_anchor + hi * entry_atr
        else:
            anchor = state.get('box_anchor', entry_price)
            stop_level = anchor + lo * entry_atr
            target_level = anchor - hi * entry_atr
            if low <= anchor - step * entry_atr:
                new_anchor = anchor - step * entry_atr
                state['box_anchor'] = new_anchor
                stop_level = new_anchor + lo * entry_atr
                target_level = new_anchor - hi * entry_atr
        return stop_level, target_level

    def cooldown(n, last_trade_bar):
        return len(hist) - last_trade_bar < n

    def daily_cap(k, last_trade_time):
        current_time = hist.time[-1]
        current_day = current_time // (1000 * 60 * 60 * 24)
        last_trade_day = last_trade_time // (1000 * 60 * 60 * 24)
        return current_day == last_trade_day and (current_day - last_trade_day) < k

    # Signal calculation
    high = hist.high
    low = hist.low
    close = hist.close
    atr_14 = ind.atr(hist, 14)

    if signal_id == "breakout_pullback":
        highest_high, lowest_low = breakout_pullback(signal_params["n"], signal_params["wait"], high, low)

    # Filter calculation
    if filter_id == "htf_trend":
        htf_close, htf_ema = htf_trend(filter_params["minutes"], filter_params["n"], close)
        htf_trend_long = htf_close[-1] > htf_ema[-1]
        htf_trend_short = htf_close[-1] < htf_ema[-1]

    # Sizing calculation
    if sizing_id == "atr_risk":
        position_fraction = atr_risk(sizing_params["r"], sizing_params["k"], close[-1], atr_14[-1])

    # Risk management
    stop_level = None
    take_level = None

    if risk_ids:
        for risk_id, risk_param in zip(risk_ids, risk_params):
            if risk_id == "fixed_stop":
                stop_level = fixed_stop(risk_param["k"], state.get('entry_price', 0), state.get('entry_atr', 0))
            elif risk_id == "breakeven":
                breakeven_level = breakeven(risk_param["a"], state.get('entry_price', 0), state.get('entry_atr', 0), high, low)
                if (pos > 0 and high[-1] >= breakeven_level) or (pos < 0 and low[-1] <= breakeven_level):
                    state['breakeven_hit'] = True
                if state.get('breakeven_hit', False):
