    entry_atr = atr[-1] if 'entry_atr' not in state else state['entry_atr']

    # Determine the current date for daily cap
    current_date = hist.time[-1] // (24 * 60 * 60 * 1000)

    # Check for daily cap
    if current_date in state.get('daily_entries', {}):
        if state['daily_entries'][current_date] >= DAILY_CAP:
            return {"target": pos, "stop": None, "take": None}
    else:
        state['daily_entries'] = {current_date: 0}

    # Check for opposite signal to close position
    if pos > 0 and rsi[-1] < RSI_HI and rsi[-2] >= RSI_HI:
        return {"target": 0, "stop": None, "take": None}
    if pos < 0 and rsi[-1] > RSI_LO and rsi[-2] <= RSI_LO:
        return {"target": 0, "stop": None, "take": None}

