        if state.get('daily_entries', {}).get(current_date, 0) < DAILY_CAP:
            state['entry_atr'] = atr[-1]
            state['entry_price'] = hist.close[-1]
            state['daily_entries'][current_date] += 1
            state['partial_take_triggered'] = False
            return {"target": POSITION_SIZE, "stop": None, "take": None}

    # Check for new short entry
    if pos == 0 and rsi[-1] < RSI_HI and rsi[-2] >= RSI_HI:
        if state.get('daily_entries', {}).get(current_date, 0) < DAILY_CAP:
            state['entry_atr'] = atr[-1]
            state['entry_price'] = hist.close[-1]
            state['daily_entries'][current_date] += 1
            state['partial_take_triggered'] = False
            return {"target": -POSITION_SIZE, "stop": None, "take": None}

    # Calculate stop and take levels
    stop_level = None
    take_level = None

    if pos > 0:
        stop_level = state['entry_price'] - PARTIAL_TAKE_C * entry_atr
        if not state['partial_take_triggered'] and hist.close[-1] >= state['entry_price'] + PARTIAL_TAKE_C * entry_atr:
            state['partial_take_triggered'] = True
            return {"target": pos / 2, "stop": stop_level, "take": None}
        take_level = None

    if pos < 0:
