        if not state['partial_take_triggered'] and hist.close[-1] <= state['entry_price'] - PARTIAL_TAKE_C * entry_atr:
            state['partial_take_triggered'] = True
            return {"target": pos / 2, "stop": stop_level, "take": None}
        take_level = None

    return {"target": pos, "stop": stop_level, "take": take_level}

