        if "entry_atr" in state:
            del state["entry_atr"]
        if "last_add_price" in state:
            del state["last_add_price"]
        if "adds" in state:
            del state["adds"]

    # Pyramid logic
    if pos != 0 and "last_add_price" in state and "entry_atr" in state and "adds" in state:
        if pos > 0 and hist.close[signal_bar] >= state["last_add_price"] + pyramid_step * state["entry_atr"]:
            if state["adds"] < pyramid_adds:
                target = min(1.0, pos + 0.5)
                state["last_add_price"] = hist.close[signal_bar]
