        elif pos < 0 and hist.close[signal_bar] <= state["last_add_price"] - pyramid_step * state["entry_atr"]:
            if state["adds"] < pyramid_adds:
                target = max(-1.0, pos - 0.5)
                state["last_add_price"] = hist.close[signal_bar]
                state["adds"] += 1

