        state['breakout_time'] = len(hist) - 1
        state['entry_atr'] = entry_atr = atr[-1]
        state['armed'] = True
    elif hist.close[-1] < breakout_low:
        state['breakout_level'] = breakout_low
        state['breakout_time'] = len(hist) - 1
        state['entry_atr'] = entry_atr = atr[-1]
        state['armed'] = True

    # Check if the setup is armed and has not expired
    if 'armed' in state and state['armed']:
        if len(hist) - 1 - state['breakout_time'] > wait:
            state['armed'] = False
        else:
            # Check for pullback to breakout level
            if hist.close[-1] > state['breakout_level'] and hist.low[-1] <= state['breakout_level']:
                if pos == 0:
                    return {"target": position_size, "stop": None, "take": None}
            elif hist.close[-1] < state['breakout_level'] and hist.high[-1] >= state['breakout_level']:
                if pos == 0:
                    return {"target": -position_size, "stop": None, "take": None}

    # Breakeven stop
    stop_price = None
    if pos > 0 and 'entry_price' in state:
        breakeven_price = state['entry_price'] + breakeven_factor * entry_atr
        if hist.close[-1] >= breakeven_price:
            stop_price = state['entry_price']
        else:
            stop_price = state['entry_price'] - entry_atr
    elif pos < 0 and 'entry_price' in state:
        breakeven_price = state['entry_price'] - breakeven_factor * entry_atr
        if hist.close[-1] <= breakeven_price:
            stop_price = state['entry_price']
        else:
            stop_price = state['entry_price'] + entry_atr

    # Partial take profit
    take_price = None
    if pos > 0 and 'entry_price' in state:
        partial_take_price = state['entry_price'] + partial_take_factor * entry_atr
        if hist.close[-1] >= partial_take_price:
            take_price = partial_take_price
    elif pos < 0 and 'entry_price' in state:
        partial_take_price = state['entry_price'] - partial_take_factor * entry_atr
        if hist.close[-1] <= partial_take_price:
            take_price = partial_take_price

    # Update entry price if we just entered a position
    if pos != 0 and 'entry_price' not in state:
        state['entry_price'] = hist.close[-1]

