    # Determine target based on direction and signals
    target = pos
    if direction == "long_only":
        if bullish_signal and long_allowed:
            target = position_fraction
        elif bearish_signal:
            target = 0
    elif direction == "long_short":
        if bullish_signal and long_allowed:
            target = position_fraction
        elif bearish_signal and short_allowed:
