            if (hist.close[t] > state['breakout_level'] and hist.low[t] <= state['breakout_level']) or \
               (hist.close[t] < state['breakout_level'] and hist.high[t] >= state['breakout_level']):
                if pos == 0:
                    entry_price = hist.close[t]
