    DAILY_CAP_KEY = "daily_cap"
    COOLDOWN_KEY = "cooldown"
    LAST_TRADE_TIME_KEY = "last_trade_time"
    LAST_TRADE_PRICE_KEY = "last_trade_price"
    LAST_TRADE_DIRECTION_KEY = "last_trade_direction"
    LAST_TRADE_ANCHOR_KEY = "last_trade_anchor"
    LAST_TRADE_STOP_KEY = "last_trade_stop"
    LAST_TRADE_TARGET_KEY = "last_trade_target"
    LAST_TRADE_ADDS_KEY = "last_trade_adds"
    LAST_TRADE_PARTIAL_TAKE_KEY = "last_trade_partial_take"

    # Initialize state variables if not already set
    if DAILY_CAP_KEY not in state:
        state[DAILY_CAP_KEY] = 0
    if COOLDOWN_KEY not in state:
        state[COOLDOWN_KEY] = 0
    if LAST_TRADE_TIME_KEY not in state:
        state[LAST_TRADE_TIME_KEY] = 0
    if LAST_TRADE_PRICE_KEY not in state:
        state[LAST_TRADE_PRICE_KEY] = 0
    if LAST_TRADE_DIRECTION_KEY not in state:
        state[LAST_TRADE_DIRECTION_KEY] = 0
    if LAST_TRADE_ANCHOR_KEY not in state:
        state[LAST_TRADE_ANCHOR_KEY] = 0
    if LAST_TRADE_STOP_KEY not in state:
        state[LAST_TRADE_STOP_KEY] = 0
    if LAST_TRADE_TARGET_KEY not in state:
        state[LAST_TRADE_TARGET_KEY] = 0
    if LAST_TRADE_ADDS_KEY not in state:
        state[LAST_TRADE_ADDS_KEY] = 0
    if LAST_TRADE_PARTIAL_TAKE_KEY not in state:
        state[LAST_TRADE_PARTIAL_TAKE_KEY] = False

    # Check for cooldown
    if state[COOLDOWN_KEY] > 0:
        state[COOLDOWN_KEY] -= 1
        return {"target": pos, "stop": None, "take": None}

    # Check for daily cap
    current_day = hist.time[SIGNAL_BAR] // (24 * 60 * 60 * 1000)
    if current_day != state[LAST_TRADE_TIME_KEY]:
        state[DAILY_CAP_KEY] = 0

    # Trend filter
    htf_1h = hist.htf(60)
    htf_ema_20 = ind.ema(htf_1h.close, 20)
    htf_1h_close = htf_1h.close[-1]
    htf_ema_20_value = htf_ema_20[-1]

    if htf_1h_close <= htf_ema_20_value:
        return {"target": pos, "stop": None, "take": None}

    # Box breakout signal
    box_high = ind.highest(hist.high, 16)[SIGNAL_BAR]
    box_low = ind.lowest(hist.low, 16)[SIGNAL_BAR]
    box_height = box_high - box_low
    atr_14 = ind.atr(hist, 14)[SIGNAL_BAR]

    if box_height > 3 * atr_14:
        return {"target": pos, "stop": None, "take": None}

    if hist.close[SIGNAL_BAR] > box_high:
        if state[DAILY_CAP_KEY] >= 3:
            return {"target": pos, "stop": None, "take": None}

        # Calculate position size
        position_size = 0.005 * ENTRY_PRICE / (3 * ENTRY_ATR)
        position_size = max(0.05, min(1.0, position_size))

        # Set new trade state
        state[LAST_TRADE_TIME_KEY] = current_day
        state[DAILY_CAP_KEY] += 1
        state[COOLDOWN_KEY] = 96
        state[LAST_TRADE_PRICE_KEY] = ENTRY_PRICE
        state[LAST_TRADE_DIRECTION_KEY] = 1
        state[LAST_TRADE_ANCHOR_KEY] = ENTRY_PRICE
        state[LAST_TRADE_STOP_KEY] = ENTRY_PRICE - 1 * ENTRY_ATR
        state[LAST_TRADE_TARGET_KEY] = ENTRY_PRICE + 2 * ENTRY_ATR
        state[LAST_TRADE_ADDS_KEY] = 0
        state[LAST_TRADE_PARTIAL_TAKE_KEY] = False

        return {"target": position_size, "stop": state[LAST_TRADE_STOP_KEY], "take": state[LAST_TRADE_TARGET_KEY]}

    # Check for bearish box breakdown to close the trade
    if pos > 0 and hist.close[SIGNAL_BAR] < box_low:
        return {"target": 0, "stop": None, "take": None}

    # Existing long position logic
    if pos > 0:
        # Update stop and target based on box shift
        if hist.close[SIGNAL_BAR] >= state[LAST_TRADE_ANCHOR_KEY] + 1 * ENTRY_ATR:
            steps = math.floor((hist.close[SIGNAL_BAR] - state[LAST_TRADE_ANCHOR_KEY]) / ENTRY_ATR)
            state[LAST_TRADE_ANCHOR_KEY] += steps * ENTRY_ATR
            state[LAST_TRADE_STOP_KEY] = state[LAST_TRADE_ANCHOR_KEY] - 1 * ENTRY_ATR
            state[LAST_TRADE_TARGET_KEY] = state[LAST_TRADE_ANCHOR_KEY] + 2 * ENTRY_ATR

        # Partial take profit
        if not state[LAST_TRADE_PARTIAL_TAKE_KEY] and hist.close[SIGNAL_BAR] >= state[LAST_TRADE_PRICE_KEY] + 1.5 * ENTRY_ATR:
            state[LAST_TRADE_PARTIAL_TAKE_KEY] = True
            return {"target": pos / 2, "stop": state[LAST_TRADE_STOP_KEY], "take": state[LAST_TRADE_TARGET_KEY]}

        return {"target": pos, "stop": state[LAST_TRADE_STOP_KEY], "take": state[LAST_TRADE_TARGET_KEY]}

    return {"target": pos, "stop": None, "take": None}

