                state['last_add_price'] = hist.close[-1]
                state['adds_remaining'] = adds
                del state['armed_level']
                del state['armed_time']
                return {"target": target, "stop": None, "take": None}

    # Pyramid Logic
    if pos != 0:
        if state['adds_remaining'] > 0:
            if pos > 0 and hist.close[-1] >= state['last_add_price'] + step * entry_atr:
                state['last_add_price'] = hist.close[-1]
                state['adds_remaining'] -= 1
                return {"target": round(pos + f0, 2), "stop": None, "take": None}
            elif pos < 0 and hist.close[-1] <= state['last_add_price'] - step * entry_atr:
                state['last_add_price'] = hist.close[-1]
                state['adds_remaining'] -= 1
                return {"target": round(pos - f0, 2), "stop": None, "take": None}

    # Opposite Signal Flips Out
    if pos > 0 and hist.close[-1] < highest_high[-2]:
        return {"target": 0, "stop": None, "take": None}
    elif pos < 0 and hist.close[-1] > lowest_low[-2]:
        return {"target": 0, "stop": None, "take": None}

    # Cooldown Logic
    if 'last_exit_time' in state and len(hist) - 1 - state['last_exit_time'] < cooldown:
        return {"target": pos, "stop": None, "take": None}

    # No change if no conditions met
    return {"target": pos, "stop": None, "take": None}

