        if signal_params["kind"] == "sma":
            fast_ma = ind.sma(hist.close, signal_params["fast"])
            slow_ma = ind.sma(hist.close, signal_params["slow"])
        elif signal_params["kind"] == "ema":
            fast_ma = ind.ema(hist.close, signal_params["fast"])
            slow_ma = ind.ema(hist.close, signal_params["slow"])

        golden_cross = (fast_ma[-1] > slow_ma[-1]) and (fast_ma[-2] <= slow_ma[-2])
        death_cross = (fast_ma[-1] < slow_ma[-1]) and (fast_ma[-2] >= slow_ma[-2])

    # Filter calculation
    if filter_id == "no_filter":
        filter_condition = True
    elif filter_id == "htf_trend":
        htf_minutes = filter_params["minutes"]
        htf_n = filter_params["n"]
        htf_close = hist.htf(htf_minutes).close
        htf_ema = ind.ema(htf_close, htf_n)
