    elif sizing_id == "atr_risk":
        atr_14 = ind.atr(hist, 14)
        entry_atr = atr_14[-1]
        target_size = sizing_params["r"] * hist.close[-1] / (sizing_params["k"] * entry_atr)
        target_size = max(0.05, min(1.0, target_size))
    elif sizing_id == "pyramid":
        f0 = sizing_params["f0"]
        step = sizing_params["step"]
        adds = sizing_params["adds"]
        if "entry_price" not in state:
            state["entry_price"] = hist.close[-1]
            state["last_add_price"] = hist.close[-1]
            state["add_count"] = 0
        entry_price = state["entry_price"]
        last_add_price = state["last_add_price"]
        add_count = state["add_count"]
        entry_atr = ind.atr(hist, 14)[-1]
        if add_count < adds and hist.close[-1] >= last_add_price + step * entry_atr:
            state["last_add_price"] = hist.close[-1]
            state["add_count"] += 1
        target_size = f0 + add_count * f0
        target_size = min(1.0, target_size)

    # Risk management
    stop = None
    take = None
    for risk_id, risk_param in zip(risk_ids, risk_params):
        if risk_id == "fixed_stop":
            entry_atr = ind.atr(hist, 14)[-1]
            stop = state["entry_price"] - risk_param["k"] * entry_atr if pos > 0 else state["entry_price"] + risk_param["k"] * entry_atr
        elif risk_id == "breakeven":
            entry_atr = ind.atr(hist, 14)[-1]
            if pos > 0 and hist.close[-1] >= state["entry_price"] + risk_param["a"] * entry_atr:
                stop = state["entry_price"]
            elif pos < 0 and hist.close[-1] <= state["entry_price"] - risk_param["a"] * entry_atr:
                stop = state["entry_price"]
        elif risk_id == "trailing_hwm":
            entry_atr = ind.atr(hist, 14)[-1]
            if pos > 0:
                state["hwm"] = max(state.get("hwm", -math.inf), hist.high[-1])
                stop = state["hwm"] - risk_param["b"] * entry_atr
            elif pos < 0:
                state["hwm"] = min(state.get("hwm", math.inf), hist.low[-1])
                stop = state["hwm"] + risk_param["b"] * entry_atr
            if risk_param["after_be"] and "breakeven_price" in state:
                stop = max(stop, state["breakeven_price"]) if pos > 0 else min(stop, state["breakeven_price"])
        elif risk_id == "time_stop":
            if "entry_bar" not in state:
                state["entry_bar"] = len(hist) - 1
            if len(hist) - state["entry_bar"] >= risk_param["n"]:
                target_size = 0
        elif risk_id == "take_profit":
            entry_atr = ind.atr(hist, 14)[-1]
            take = state["entry_price"] + risk_param["c"] * entry_atr if pos > 0 else state["entry_price"] - risk_param["c"] * entry_atr
        elif risk_id == "partial_take":
            entry_atr = ind.atr(hist, 14)[-1]
            if pos > 0 and hist.close[-1] >= state["entry_price"] + risk_param["c"] * entry_atr and not state.get("partial_taken", False):
                target_size /= 2
                state["partial_taken"] = True
            elif pos < 0 and hist.close[-1] <= state["entry_price"] - risk_param["c"] * entry_atr and not state.get("partial_taken", False):
                target_size /= 2
                state["partial_taken"] = True
        elif risk_id == "box_shift":
            entry_atr = ind.atr(hist, 14)[-1]
            if "anchor" not in state:
                state["anchor"] = state["entry_price"]
            if pos > 0:
                if hist.close[-1] >= state["anchor"] + risk_param["step"] * entry_atr:
                    state["anchor"] = state["anchor"] + risk_param["step"] * entry_atr
            elif pos < 0:
                if hist.close[-1] <= state["anchor"] - risk_param["step"] * entry_atr:
                    state["anchor"] = state["anchor"] - risk_param["step"] * entry_atr
            stop = state["anchor"] - risk_param["lo"] * entry_atr if pos > 0 else state["anchor"] + risk_param["lo"] * entry_atr
            take = state["anchor"] + risk_param["hi"] * entry_atr if pos > 0 else state["anchor"] - risk_param["hi"] * entry_atr
        elif risk_id == "cooldown":
            if "exit_bar" in state and len(hist) - state["exit_bar"] < risk_param["n"]:
                target_size = 0
        elif risk_id == "daily_cap":
            current_day = hist.time[-1] // (1000 * 60 * 60 * 24)
            if "last_entry_day" in state and state["last_entry_day"] == current_day:
                if state.get("entry_count", 0) >= risk_param["k"]:
                    target_size = 0
            else:
                state["last_entry_day"] = current_day
                state["entry_count"] = 0

    # Entry logic
    if pos == 0 and target_size > 0 and filter_condition:
        if golden_cross:
            state["entry_price"] = hist.close[-1]
            state["entry_bar"] = len(hist) - 1
            state["entry_count"] = state.get("entry_count", 0) + 1
            state["partial_taken"] = False
            state["breakeven_price"] = None
            state["hwm"] = None
            state["anchor"] = None
        elif death_cross:
            target_size = 0

    # Rounding target size to 0.05 grid
    target_size = round(target_size / 0.05) * 0.05

    # Exit logic
    if pos > 0 and (stop is not None and hist.low[-1] <= stop) or (take is not None and hist.high[-1] >= take):
        target_size = 0
        state["exit_bar"] = len(hist) - 1
    elif pos < 0 and (stop is not None and hist.high[-1] >= stop) or (take is not None and hist.low[-1] <= take):
        target_size = 0
        state["exit_bar"] = len(hist) - 1

    return {"target": target_size, "stop": stop, "take": take}

