    if state[ARMED_LEVEL_KEY] == 0.0:
        if hist.close[-1] > highest_high[-1]:
            state[ARMED_LEVEL_KEY] = highest_high[-1]
            state[ARMED_TIME_KEY] = len(hist) - 1
        elif hist.close[-1] < lowest_low[-1]:
            state[ARMED_LEVEL_KEY] = lowest_low[-1]
            state[ARMED_TIME_KEY] = len(hist) - 1
    else:
        if len(hist) - 1 - state[ARMED_TIME_KEY] > WAIT_BARS:
            state[ARMED_LEVEL_KEY] = 0.0
            state[ARMED_TIME_KEY] = 0
        elif pos == 0 and not state[DAILY_CAP_KEY]:
            if hist.close[-1] > state[ARMED_LEVEL_KEY] and hist.low[-1] <= state[ARMED_LEVEL_KEY]:
                # Long entry
                state[ENTRY_PRICE_KEY] = hist.close[-1]
                state[ENTRY_ATR_KEY] = current_atr
                state[LAST_ADD_PRICE_KEY] = hist.close[-1]
                state[ADD_COUNT_KEY] = 0
                state[DAILY_CAP_KEY] = True
                state[LAST_TRADE_TIME_KEY] = current_time
                return {"target": 0.5, "stop": None, "take": None}

    # Pyramid logic
    if pos > 0:
        if hist.close[-1] >= state[LAST_ADD_PRICE_KEY] + 2 * state[ENTRY_ATR_KEY] and state[ADD_COUNT_KEY] < 2:
            state[LAST_ADD_PRICE_KEY] = hist.close[-1]
            state[ADD_COUNT_KEY] += 1
            return {"target": min(1.0, pos + 0.5), "stop": None, "take": None}

    # Exit logic
    if pos > 0:
        stop_level = state[ENTRY_PRICE_KEY] - 1 * state[ENTRY_ATR_KEY]
        return {"target": pos, "stop": stop_level, "take": None}

    # No position, no action
    return {"target": pos, "stop": None, "take": None}

import math
import numpy as np

def strategy(hist, state, pos, ind) -> dict:
    # Constants
    n = 96
    wait = 32
    f0 = 0.25
    step = 1.0
    adds = 2
    k_daily_cap = 2

    # Calculate ATR
    atr_14 = ind.atr(hist, 14)
    entry_atr = atr_14[-1] if 'entry_atr' not in state else state['entry_atr']

    # Calculate 96-bar high and low
    highest_high_96 = ind.highest(hist.high, n)
    lowest_low_96 = ind.lowest(hist.low, n)

    # Breakout and retest logic
    if 'breakout_level' not in state:
        state['breakout_level'] = highest_high_96[-1]
        state['breakout_time'] = len(hist) - 1

    if highest_high_96[-1] > state['breakout_level']:
        state['breakout_level'] = highest_high_96[-1]
        state['breakout_time'] = len(hist) - 1

    # Check if we are in the cooldown period
    if 'last_exit_time' in state and len(hist) - state['last_exit_time'] < 4:
        return {"target": pos, "stop": None, "take": None}

    # Check if we are within the daily cap
    current_day = hist.time[-1] // (24 * 60 * 60 * 1000)
    if 'last_entry_day' in state and state['last_entry_day'] == current_day:
        if state.get('entry_count', 0) >= k_daily_cap:
            return {"target": pos, "stop": None, "take": None}
    else:
        state['last_entry_day'] = current_day
        state['entry_count'] = 0

    # Check for breakout and retest
    if (len(hist) - 1 - state['breakout_time'] <= wait) and (hist.low[-1] <= state['breakout_level']):
        if pos == 0:
            target = round(f0, 2)
            state['entry_atr'] = entry_atr
            state['last_add_price'] = hist.close[-1]
            state['entry_count'] = state.get('entry_count', 0) + 1
            return {"target": target, "stop": None, "take": None}

    # Pyramid logic
    if pos > 0:
        if hist.close[-1] >= state['last_add_price'] + step * entry_atr and state.get('adds_made', 0) < adds:
            new_target = min(round(pos + f0, 2), 1.0)
            state['last_add_price'] = hist.close[-1]
            state['adds_made'] = state.get('adds_made', 0) + 1
            return {"target": new_target, "stop": None, "take": None}

    # Bearish breakdown signal
    if hist.close[-1] <= lowest_low_96[-1]:
        return {"target": 0, "stop": None, "take": None}

    # No change
    return {"target": pos, "stop": None, "take": None}
